INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93e52142-9415-4dba-bd3f-8822a8d15bf4', '巫山', '巫山', '2f6f0734-9f2f-40a4-b9b5-ef0c45f03018', '唐', '["昔時亦雲雨，今時亦雲雨。","自是荒淫多，夢得巫山女。","從來聖明君，可聽妖魅語。","只今峰上雲，徒自生容與。"]', '["昔时亦云雨，今时亦云雨。","自是荒淫多，梦得巫山女。","從来聖明君，可听妖魅語。","只今峰上云，徒自生容與。"]', '诗', 'shi', '', NULL, '巫山 蘇拯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1ee0ff4-7f70-4dab-a4f7-a20f32cadd13', '賈客', '賈客', '2f6f0734-9f2f-40a4-b9b5-ef0c45f03018', '唐', '["長帆挂短舟，所願疾如箭。","得喪一驚飄，生死無良賤。","不謂天不祐，自是人苟患。","嘗言海利深，利深不如淺。"]', '["长帆挂短舟，所願疾如箭。","得喪一驚飄，生死無良賤。","不謂天不祐，自是人苟患。","嘗言海利深，利深不如淺。"]', '诗', 'shi', '', NULL, '賈客 蘇拯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4863a586-8671-4df3-acbe-ef1133bae5a5', '狡兔行', '狡兔行', '2f6f0734-9f2f-40a4-b9b5-ef0c45f03018', '唐', '["秋來無骨肥，鷹犬遍原野。","草中三穴無處藏，何況平田無穴者。"]', '["秋来無骨肥，鷹犬遍原野。","草中三穴無处藏，何況平田無穴者。"]', '诗', 'shi', '', NULL, '狡兔行 蘇拯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f5d4639-6caf-4a12-90a5-c30b98e8c770', '長城', '长城', '2f6f0734-9f2f-40a4-b9b5-ef0c45f03018', '唐', '["嬴氏設防胡，烝沙築冤壘。","蒙公取勳名，豈算生民死。","運畚力不禁，碎身砂磧裏。","黔黎欲半空，長城舂未已。","皇天潛鼓怒，力化一女子。","遂使萬雉崩，不盡數行淚。","自古進身者，本非陷物致。","當時文德修，不到三世地。"]', '["嬴氏設防胡，烝沙築冤壘。","蒙公取勳名，豈算生民死。","運畚力不禁，碎身砂磧裏。","黔黎欲半空，长城舂未已。","皇天潛鼓怒，力化一女子。","遂使万雉崩，不尽數行泪。","自古進身者，本非陷物致。","當时文德修，不到三世地。"]', '诗', 'shi', '', NULL, '長城 蘇拯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bffd0608-68af-4b82-9f2f-b5539066a68d', '織婦女', '织婦女', '2f6f0734-9f2f-40a4-b9b5-ef0c45f03018', '唐', '["伊余盡少女，一種飾螓首。","徒能事機杼，與之作歌舞。","歌舞片時間，黃金翻袖取。","秪看舞者樂，豈念織者苦。","感此嘗憶古人言，一婦不織天下寒。"]', '["伊余尽少女，一種飾螓首。","徒能事機杼，與之作歌舞。","歌舞片时间，黄金翻袖取。","秪看舞者乐，豈念织者苦。","感此嘗憶古人言，一婦不织天下寒。"]', '诗', 'shi', '', NULL, '織婦女 蘇拯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54935912-4030-4fa7-8722-6502cb26b8a3', '古塞下', '古塞下', '2f6f0734-9f2f-40a4-b9b5-ef0c45f03018', '唐', '["百戰已休兵，寒雲愁未歇。","血染長城沙，馬踏征人骨。","早得用蛾眉，免陷邊戍卒。","始知髦頭星，不在彎弓沒。"]', '["百戰已休兵，寒云愁未歇。","血染长城沙，马踏征人骨。","早得用蛾眉，免陷邊戍卒。","始知髦头星，不在彎弓沒。"]', '诗', 'shi', '', NULL, '古塞下 蘇拯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3260b4ef-89e7-4942-87d7-45c7d1d6c630', '水旱禱', '水旱禱', '2f6f0734-9f2f-40a4-b9b5-ef0c45f03018', '唐', '["禱祈勿告天，酒漿勿澆地。","陰陽和也無妖氣，陰陽愆期乃人致。","病生心腹不自醫，古屋澄潭何神祟。"]', '["禱祈勿告天，酒漿勿澆地。","陰陽和也無妖氣，陰陽愆期乃人致。","病生心腹不自醫，古屋澄潭何神祟。"]', '诗', 'shi', '', NULL, '水旱禱 蘇拯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e1ca461-7267-41ca-b2ef-d8bbe5df888c', '鄒律', '鄒律', '2f6f0734-9f2f-40a4-b9b5-ef0c45f03018', '唐', '["鄒律暖燕谷，青史徒編錄。","人心不變遷，空吹閑草木。","世患有三惑，爾律莫能抑。","邊苦有長征，爾律莫能息。","斯術未濟時，斯律亦何益。","爭如至公一開口，吹起賢良霸邦國。"]', '["鄒律暖燕谷，青史徒編錄。","人心不变遷，空吹闲草木。","世患有三惑，爾律莫能抑。","邊苦有长征，爾律莫能息。","斯術未濟时，斯律亦何益。","爭如至公一开口，吹起賢良霸邦国。"]', '诗', 'shi', '', NULL, '鄒律 蘇拯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c94e69f-461f-46fd-83f6-d4cc44001edf', '蜘蛛諭', '蜘蛛諭', '2f6f0734-9f2f-40a4-b9b5-ef0c45f03018', '唐', '["春蠶吐出絲，濟世功不絕。","蜘蛛吐出絲，飛蟲成聚血。","蠶絲何專利，爾絲何專孽。","映日張網羅，遮天亦何別。","儻居要地門，害物可堪說。","網成雖福己，網敗還禍爾。","小人與君子，利害一如此。"]', '["春蠶吐出絲，濟世功不絕。","蜘蛛吐出絲，飞蟲成聚血。","蠶絲何專利，爾絲何專孽。","映日張網羅，遮天亦何別。","儻居要地门，害物可堪说。","網成雖福己，網敗還禍爾。","小人與君子，利害一如此。"]', '诗', 'shi', '', NULL, '蜘蛛諭 蘇拯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef1f83b2-8784-48ac-bac1-0c37bd587dc7', '獵犬行', '獵犬行', '2f6f0734-9f2f-40a4-b9b5-ef0c45f03018', '唐', '["獵犬未成行，狐兔無奈何。","獵犬今盈羣，狐兔依舊多。","自爾初跳躍，人言多拏躩。","常指天外狼，立可口中嚼。","骨長毛衣重，燒殘烟草薄。","狡兔何曾擒，時把家雞捉。","食盡者飯翻，增養者惡壯。","可嗟獵犬壯復壯，不堪兔絕良弓喪。"]', '["獵犬未成行，狐兔無奈何。","獵犬今盈羣，狐兔依旧多。","自爾初跳躍，人言多拏躩。","常指天外狼，立可口中嚼。","骨长毛衣重，燒殘烟草薄。","狡兔何曾擒，时把家雞捉。","食尽者飯翻，增養者惡壯。","可嗟獵犬壯复壯，不堪兔絕良弓喪。"]', '诗', 'shi', '', NULL, '獵犬行 蘇拯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b4fe8ad-ec28-4e02-b811-6d0be1debfe4', '斷火謠', '斷火謠', '2f6f0734-9f2f-40a4-b9b5-ef0c45f03018', '唐', '["誰謂之推賢，於世何功果。","絕爾晉侯交，禁我唐虞火。","國閉檀榆煙，大禮成隳墮。","暗室枯槁飯，冷面相看坐。","陽昇既非佑，陰伏若爲佐。","焉凍羣生腹，將止天下禍。","但究冤濫刑，天道無不可。","鄙哉前朝翊贊臣，訏謨之規何瑣瑣。"]', '["誰謂之推賢，於世何功果。","絕爾晉侯交，禁我唐虞火。","国閉檀榆煙，大禮成隳墮。","暗室枯槁飯，冷面相看坐。","陽昇既非佑，陰伏若爲佐。","焉凍羣生腹，將止天下禍。","但究冤濫刑，天道無不可。","鄙哉前朝翊贊臣，訏謨之規何瑣瑣。"]', '诗', 'shi', '', NULL, '斷火謠 蘇拯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58279968-e510-4460-9a4c-d807cb0845e4', '思婦吟', '思婦吟', '2f6f0734-9f2f-40a4-b9b5-ef0c45f03018', '唐', '["秋風雁又歸，邊信一何早。","攬衣出門望，落葉滿長道。","一從秉箕箒，十載孤懷抱。","可堪日日醉寵榮，不說思君令人老。"]', '["秋风雁又归，邊信一何早。","攬衣出门望，落葉满长道。","一從秉箕箒，十載孤懷抱。","可堪日日醉寵榮，不说思君令人老。"]', '诗', 'shi', '', NULL, '思婦吟 蘇拯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf708e15-02b2-4888-ac58-8bf8e53cc007', '雉兔者', '雉兔者', '2f6f0734-9f2f-40a4-b9b5-ef0c45f03018', '唐', '["所獵一何酷，終年耗林麓。","飛走如未空，貪殘豈知足。","嘗聞獵書史，可以鑒榮辱。","嘗聞獵賢良，可以霸邦國。","如何縱網羅，空成肥骨肉。","和濟俱不聞，曷所禳顛覆。","誰能爲扣天地鑪，鑄此傷生其可乎。"]', '["所獵一何酷，終年耗林麓。","飞走如未空，貪殘豈知足。","嘗闻獵书史，可以鑒榮辱。","嘗闻獵賢良，可以霸邦国。","如何縱網羅，空成肥骨肉。","和濟俱不闻，曷所禳顛覆。","誰能爲扣天地鑪，鑄此傷生其可乎。"]', '诗', 'shi', '', NULL, '雉兔者 蘇拯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ec18a32-d556-46e2-912d-f8077493b3fa', '藥草', '藥草', '2f6f0734-9f2f-40a4-b9b5-ef0c45f03018', '唐', '["天子卹疲瘵，坤靈奉其職。","年年濟世功，貴賤相兼植。","因產衆草中，所希採者識。","一枝當若神，千金亦何直。","生草不生藥，無以彰土德。","生藥不生草，無以彰奇特。","國忠在臣賢，民患憑藥力。","靈草猶如此，賢人豈多得。"]', '["天子卹疲瘵，坤靈奉其職。","年年濟世功，貴賤相兼植。","因產衆草中，所希採者識。","一枝當若神，千金亦何直。","生草不生藥，無以彰土德。","生藥不生草，無以彰奇特。","国忠在臣賢，民患憑藥力。","靈草猶如此，賢人豈多得。"]', '诗', 'shi', '', NULL, '藥草 蘇拯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('694dd661-36ca-4673-8071-6d604ec97dcd', '凡草誡', '凡草誡', '2f6f0734-9f2f-40a4-b9b5-ef0c45f03018', '唐', '["野草凡不凡，亦應生和出。","鉏夫耘藥欄，根不留其一。","良由本蕪穢，著地成棄物。","人生行不修，何門可容膝。","不唯不爾容，得無凡草嫉。","賢愚偃仰間，鑒之宜日日。"]', '["野草凡不凡，亦應生和出。","鉏夫耘藥欄，根不留其一。","良由本蕪穢，著地成棄物。","人生行不修，何门可容膝。","不唯不爾容，得無凡草嫉。","賢愚偃仰间，鑒之宜日日。"]', '诗', 'shi', '', NULL, '凡草誡 蘇拯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e38631da-4d38-4af7-ad60-f7e6195edbbe', '明禁忌', '明禁忌', '2f6f0734-9f2f-40a4-b9b5-ef0c45f03018', '唐', '["陰陽家有書，卜築多禁忌。","土中若有神，穴處何無祟。","我識先賢意，本誡驕侈地。","恣欲剏樓臺，率情染朱翠。","四面興土功，四時妨農事。","可以沒凶災，四隅通一二。","一年省修營，萬民停困躓。","動若契於理，福匪神之遺。","動若越於常，禍乃身之致。","神在虛無間，土中非神位。"]', '["陰陽家有书，卜築多禁忌。","土中若有神，穴处何無祟。","我識先賢意，本誡驕侈地。","恣欲剏楼台，率情染朱翠。","四面兴土功，四时妨農事。","可以沒凶災，四隅通一二。","一年省修營，万民停困躓。","动若契於理，福匪神之遺。","动若越於常，禍乃身之致。","神在虛無间，土中非神位。"]', '诗', 'shi', '', NULL, '明禁忌 蘇拯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56286f96-de44-48ef-aa70-35560c092656', '傷彩飾', '傷彩飾', '2f6f0734-9f2f-40a4-b9b5-ef0c45f03018', '唐', '["朝見亦光彩，暮見亦光彩。","一旦風雨飄，十分無一在。","爾形才似削，爾貌不如昨。","本爲是凡姿，誰教染丹雘。","虛飾片時間，天意以爲惡。","物假猶如此，人假爭堪作。"]', '["朝见亦光彩，暮见亦光彩。","一旦风雨飄，十分無一在。","爾形才似削，爾貌不如昨。","本爲是凡姿，誰教染丹雘。","虛飾片时间，天意以爲惡。","物假猶如此，人假爭堪作。"]', '诗', 'shi', '', NULL, '傷彩飾 蘇拯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfc5efde-fe98-46d9-b095-33d0453b6fd3', '世迷', '世迷', '2f6f0734-9f2f-40a4-b9b5-ef0c45f03018', '唐', '["烏兔日夜行，與人運枯榮。","爲善不常缺，爲惡不常盈。","天道無阿黨，人心自覆傾。","所以多遷變，寧合天地情。","我願造化手，莫放狐兔走。","恣海產珍奇，縱地生花柳。","美者一齊美，醜者一齊醜。","民心歸大朴，戰爭亦何有。"]', '["烏兔日夜行，與人運枯榮。","爲善不常缺，爲惡不常盈。","天道無阿黨，人心自覆傾。","所以多遷变，寧合天地情。","我願造化手，莫放狐兔走。","恣海產珍奇，縱地生花柳。","美者一齊美，醜者一齊醜。","民心归大朴，戰爭亦何有。"]', '诗', 'shi', '', NULL, '世迷 蘇拯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4275eea0-31db-4c75-bec8-e7d23267c688', '鴟梟', '鴟梟', '2f6f0734-9f2f-40a4-b9b5-ef0c45f03018', '唐', '["爲害未爲害，其如汚物類。","斯言之一玷，流傳極天地。","良木不得栖，清波不得戲。","曾戲水堪疑，曾栖樹終棄。","天不殲爾族，與夫惡相濟。","地若默爾聲，與夫妖爲諱。","一時懷害心，千古不能替。","傷哉醜行人，茲禽亦爲譬。"]', '["爲害未爲害，其如汚物類。","斯言之一玷，流傳極天地。","良木不得栖，清波不得戲。","曾戲水堪疑，曾栖樹終棄。","天不殲爾族，與夫惡相濟。","地若默爾声，與夫妖爲諱。","一时懷害心，千古不能替。","傷哉醜行人，茲禽亦爲譬。"]', '诗', 'shi', '', NULL, '鴟梟 蘇拯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dccaae80-d48f-4071-bab5-52a00fc01ce7', '山中道者', '山中道者', '2f6f0734-9f2f-40a4-b9b5-ef0c45f03018', '唐', '["筇杖六尺許，坐石流泉所。","舉頭看古松，似對仙鶴語。","是時天氣清，四迥無塵侶。","顧我笑相迎，知有丹砂異。"]', '["筇杖六尺許，坐石流泉所。","舉头看古松，似对仙鹤語。","是时天氣清，四迥無塵侶。","顧我笑相迎，知有丹砂異。"]', '诗', 'shi', '', NULL, '山中道者 蘇拯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c72f1b5-15ab-4ae9-b452-75ce94cf8e2a', '漁人', '漁人', '2f6f0734-9f2f-40a4-b9b5-ef0c45f03018', '唐', '["垂竿朝與暮，披簑臥橫楫。","不問清平時，自樂滄波業。","長畏不得閑，幾度避遊畋。","當笑釣臺上，逃名名却傳。"]', '["垂竿朝與暮，披簑臥橫楫。","不问清平时，自乐滄波業。","长畏不得闲，幾度避游畋。","當笑釣台上，逃名名却傳。"]', '诗', 'shi', '', NULL, '漁人 蘇拯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82364db2-abc9-4de7-8d21-13c8475f4f63', '聞猨', '闻猨', '2f6f0734-9f2f-40a4-b9b5-ef0c45f03018', '唐', '["秋風颯颯猨聲起，客恨猨哀一相似。","漫向孤危驚客心，何曾解入笙歌耳。"]', '["秋风颯颯猨声起，客恨猨哀一相似。","漫向孤危驚客心，何曾解入笙歌耳。"]', '诗', 'shi', '', NULL, '聞猨 蘇拯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91d26328-ead6-40ce-b16e-6c4b8c9fbfb6', '經馬嵬坡', '經马嵬坡', '2f6f0734-9f2f-40a4-b9b5-ef0c45f03018', '唐', '["一從殺貴妃，春來花無意。","此地縱千年，土香猶破鼻。","寵既出常理，辱豈同常死。","一等異於衆，傾覆皆如此。"]', '["一從殺貴妃，春来花無意。","此地縱千年，土香猶破鼻。","寵既出常理，辱豈同常死。","一等異於衆，傾覆皆如此。"]', '诗', 'shi', '', NULL, '經馬嵬坡 蘇拯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4200b0b9-0667-4174-980e-a58517214821', '經鶴臺', '經鹤台', '2f6f0734-9f2f-40a4-b9b5-ef0c45f03018', '唐', '["築臺非謂賢，獨聚乘軒鶴。","六馬不能馭，九臯欲何託。","一旦敵兵來，萬民同隕濩。","如何警露禽，不似銜環雀。","一物欲誤時，衆類皆成惡。","至今臺基上，飛鳥不至泊。"]', '["築台非謂賢，独聚乘軒鹤。","六马不能馭，九臯欲何託。","一旦敵兵来，万民同隕濩。","如何警露禽，不似銜环雀。","一物欲誤时，衆類皆成惡。","至今台基上，飞鸟不至泊。"]', '诗', 'shi', '', NULL, '經鶴臺 蘇拯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e049b8b7-d011-4a51-bf9f-f4c4ef51f4ac', '寄遠', '寄远', '2f6f0734-9f2f-40a4-b9b5-ef0c45f03018', '唐', '["游子雖惜別，一去何時見。","飛鳥猶戀巢，萬里亦何遠。","妾願化爲霜，日日下河梁。","若能侵鬢色，先染薄情郎。"]', '["游子雖惜別，一去何时见。","飞鸟猶戀巢，万里亦何远。","妾願化爲霜，日日下河梁。","若能侵鬢色，先染薄情郎。"]', '诗', 'shi', '', NULL, '寄遠 蘇拯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d38c844-8c30-457e-a689-2a008c0a2143', '芭蕉', '芭蕉', '33451a73-fd5d-46ff-8a33-c47f2f830144', '唐', '["一種靈苗異，天然體性虛。","葉如斜界紙，心似倒抽書。"]', '["一種靈苗異，天然體性虛。","葉如斜界紙，心似倒抽书。"]', '诗', 'shi', '', NULL, '芭蕉 路德延 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5cf5238-0407-4e47-8c22-f996188dc327', '感舊詩', '感旧诗', '33451a73-fd5d-46ff-8a33-c47f2f830144', '唐', '["初騎竹馬詠芭蕉，嘗忝名卿誦滿朝。","五字便容趨絳帳，一枝尋許折丹霄。","豈知流落萍蓬遠，不覺推遷歲月遙。","國境未安身未立，至今顏巷守簞瓢。"]', '["初騎竹马詠芭蕉，嘗忝名卿誦满朝。","五字便容趨絳帳，一枝尋許折丹霄。","豈知流落萍蓬远，不覺推遷歲月遙。","国境未安身未立，至今顏巷守簞瓢。"]', '诗', 'shi', '', NULL, '感舊詩 路德延 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3ee511a-64e6-42ec-8637-1c6d098e6178', '小兒詩', '小兒诗', '33451a73-fd5d-46ff-8a33-c47f2f830144', '唐', '["情態任天然，桃紅兩頰鮮。","乍行人共看，初語客多憐。","臂膊肥如瓠，肌膚軟勝綿。","長頭纔覆額，分角漸垂肩。","散誕無塵慮，逍遙占地仙。","排衙朱閣上，喝道畫堂前。","合調歌楊柳，齊聲踏採蓮。","走隄行細雨，奔巷趁輕煙。","嫩竹乘爲馬，新蒲折作鞭。","鶯雛金鏇繫，猫自綵絲牽。","擁鶴歸晴島，驅鵝入暖泉。","楊花爭弄雪，榆葉共收錢。","錫鏡當胸挂，銀珠對耳懸。","頭依蒼鶻裹，袖學柘枝揎。","酒殢丹砂暖，茶催小玉煎。","頻邀籌箸掙，時乞繡鍼穿。","寶篋拏紅豆，妝奩拾翠鈿。","戲袍披按褥，劣帽戴靴氈。","展畫趍三聖，開屏笑七賢。","貯懷青杏小，垂額綠荷圓。","驚滴霑羅淚，嬌流汚錦涎。","倦書饒婭姹，憎藥巧遷延。","弄帳鸞綃映，藏衾鳳綺纏。","指敲迎使鼓，筋撥賽神弦。","簾拂魚鉤動，箏推雁柱偏。","碁圖添路畫，笛管欠聲鐫。","惱客初酣睡，驚僧半入禪。","尋蛛窮屋瓦，探雀遍樓椽。","拋果忙開口，藏鉤亂出拳。","夜分圍榾柮，朝聚打鞦韆。","折竹裝泥燕，添絲放紙鳶。","互誇輪水碓，相教放風旋。","旗小裁紅絹，書幽截碧牋。","遠鋪張鴿網，低控射蠅弦。","詀語時時道，謠歌處處傳。","匿牕眉乍曲，遮路臂相連。","鬬草當春逕，爭毬出晚田。","柳傍慵獨坐，花底困橫眠。","等鵲前籬畔，聽蛩伏砌邊。","傍枝粘舞蝶，隈樹捉鳴蟬。","平島誇趫上，層崖逞捷緣。","嫩苔車跡小，深雪履痕全。","競指雲生岫，齊呼月上天。","蟻窠尋逕斸，蜂穴遶階填。","樵唱迴深嶺，牛歌下遠川。","壘柴爲屋木，和土作盤筵。","險砌高臺石，危跳峻塔磚。","忽陞隣舍樹，偷上後池船。","項橐稱師日，甘羅作相年。","明時方任德，勸爾減狂顛。"]', '["情態任天然，桃紅兩頰鲜。","乍行人共看，初語客多怜。","臂膊肥如瓠，肌膚軟勝綿。","长头纔覆額，分角漸垂肩。","散誕無塵慮，逍遙占地仙。","排衙朱閣上，喝道畫堂前。","合調歌楊柳，齊声踏採蓮。","走隄行細雨，奔巷趁轻煙。","嫩竹乘爲马，新蒲折作鞭。","鶯雛金鏇繫，猫自綵絲牽。","擁鹤归晴島，驱鵝入暖泉。","楊花爭弄雪，榆葉共收錢。","錫镜當胸挂，銀珠对耳懸。","头依蒼鶻裹，袖学柘枝揎。","酒殢丹砂暖，茶催小玉煎。","頻邀籌箸掙，时乞繡鍼穿。","寶篋拏紅豆，妝奩拾翠鈿。","戲袍披按褥，劣帽戴靴氈。","展畫趍三聖，开屏笑七賢。","貯懷青杏小，垂額綠荷圓。","驚滴霑羅泪，嬌流汚錦涎。","倦书饒婭姹，憎藥巧遷延。","弄帳鸾綃映，藏衾鳳綺纏。","指敲迎使鼓，筋撥賽神弦。","簾拂鱼鉤动，箏推雁柱偏。","碁圖添路畫，笛管欠声鐫。","惱客初酣睡，驚僧半入禪。","尋蛛窮屋瓦，探雀遍楼椽。","拋果忙开口，藏鉤亂出拳。","夜分圍榾柮，朝聚打鞦韆。","折竹裝泥燕，添絲放紙鳶。","互誇輪水碓，相教放风旋。","旗小裁紅絹，书幽截碧牋。","远鋪張鴿網，低控射蠅弦。","詀語时时道，謠歌处处傳。","匿牕眉乍曲，遮路臂相連。","鬬草當春逕，爭毬出晚田。","柳傍慵独坐，花底困橫眠。","等鵲前籬畔，听蛩伏砌邊。","傍枝粘舞蝶，隈樹捉鳴蟬。","平島誇趫上，層崖逞捷緣。","嫩苔车跡小，深雪履痕全。","競指云生岫，齊呼月上天。","蟻窠尋逕斸，蜂穴遶階填。","樵唱迴深嶺，牛歌下远川。","壘柴爲屋木，和土作盤筵。","險砌高台石，危跳峻塔磚。","忽陞隣舍樹，偷上後池船。","項橐稱師日，甘羅作相年。","明时方任德，勸爾減狂顛。"]', '诗', 'shi', '', NULL, '小兒詩 路德延 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('324ec432-94b4-4fe1-b253-0bfc3f5797c8', '句', '句', '33451a73-fd5d-46ff-8a33-c47f2f830144', '唐', '["不是上台知姓字，五花賓館敢從容。"]', '["不是上台知姓字，五花賓館敢從容。"]', '诗', 'shi', '', NULL, '句 路德延 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90203085-be1b-4eff-a131-8375081baed1', '及第後呈朝中知己', '及第後呈朝中知己', 'f88c632a-25f8-4e58-ac6e-fa497a325cd4', '唐', '["凌晨曉鼓奏嘉音，雷擁龍迎出陸沈。","金榜高懸當玉闕，錦衣即著到家林。","真珠每被塵泥陷，病鶴多遭螻蟻侵。","今日始知天有意，還教雪得一生心。"]', '["凌晨晓鼓奏嘉音，雷擁龙迎出陸沈。","金榜高懸當玉闕，錦衣即著到家林。","真珠每被塵泥陷，病鹤多遭螻蟻侵。","今日始知天有意，還教雪得一生心。"]', '诗', 'shi', '', NULL, '及第後呈朝中知己 李旭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c5514cb-0c95-4b12-ba4e-fde332be34d1', '題惠嚴寺', '題惠嚴寺', '7411f124-aa3e-44f6-9b82-761c463dbf4a', '唐', '["人莫嫌山小，僧還愛寺靈。","殿高神氣力，龍活客丹青。"]', '["人莫嫌山小，僧還愛寺靈。","殿高神氣力，龙活客丹青。"]', '诗', 'shi', '', NULL, '題惠嚴寺 崔庸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5d28ce3-202c-4072-a26c-7d7100cae796', '經費拾遺舊隱', '經費拾遺旧隐', '921c4a4e-1878-43c8-8153-06cfcf9cc16d', '唐', '["林下茅齋已半傾，九華幽逕少人行。","不將冠劒爲榮事，只向煙蘿寄此生。","松竹漸荒池上色，琴書徒立世間名。","白楊風起秋山暮，時復哀猨啼一聲。"]', '["林下茅斋已半傾，九华幽逕少人行。","不將冠劒爲榮事，只向煙蘿寄此生。","松竹漸荒池上色，琴书徒立世间名。","白楊风起秋山暮，时复哀猨啼一声。"]', '诗', 'shi', '', NULL, '經費拾遺舊隱 胡駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5deb79e-b7ec-48f3-9d7e-9264792cea70', '失題', '失題', '290fbfc9-875d-4b59-929c-f26bfa8da01a', '唐', '["莫道春花獨照人，秋花未必怯青春。","四時風雨沒時節，共保松筠根底塵。"]', '["莫道春花独照人，秋花未必怯青春。","四时风雨沒时節，共保松筠根底塵。"]', '诗', 'shi', '', NULL, '失題 周祚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53388d6f-5bc5-4836-9a5f-8aa4fddb31ac', '蛺蝶行', '蛺蝶行', '48e3383b-2fb3-48c5-84b9-9ff2dc834d28', '唐', '["東園宮草綠，上下飛相逐。","君恩不禁春，昨夜花中宿。"]', '["东园宮草綠，上下飞相逐。","君恩不禁春，昨夜花中宿。"]', '诗', 'shi', '', NULL, '蛺蝶行 盧頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2915a943-3f25-4f92-8b13-3868693f9440', '東西行', '东西行', '48e3383b-2fb3-48c5-84b9-9ff2dc834d28', '唐', '["種荷玉盆裏，不及溝中水。","養雉黃金籠，見草心先喜。"]', '["種荷玉盆裏，不及溝中水。","養雉黄金籠，见草心先喜。"]', '诗', 'shi', '', NULL, '東西行 盧頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b67abe08-3ab7-40eb-9faf-a8322a7af4ad', '失題 一', '失題 一', '48e3383b-2fb3-48c5-84b9-9ff2dc834d28', '唐', '["春淚爛羅綺，泣聲抽恨多。","莫滴芙蓉池，愁傷連蔕荷。"]', '["春泪爛羅綺，泣声抽恨多。","莫滴芙蓉池，愁傷連蔕荷。"]', '诗', 'shi', '', NULL, '失題 一 盧頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e6695be-23c6-497f-b756-c82bb5321e3b', '失題 二', '失題 二', '48e3383b-2fb3-48c5-84b9-9ff2dc834d28', '唐', '["一朵花葉飛，一枝花光彩。","美人惜花心，但願春長在。"]', '["一朵花葉飞，一枝花光彩。","美人惜花心，但願春长在。"]', '诗', 'shi', '', NULL, '失題 二 盧頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5ab00ce-47a8-423b-80f8-acccfe48dc27', '晚泊漢江渡', '晚泊漢江渡', '978b45bf-bd16-4509-a4b2-3435d89e2301', '唐', '["末秋雲木輕，蓮折晚香清。","雨下侵苔色，雲涼出浪聲。","疊帆依岸盡，微照夾隄明。","渡吏已頭白，遙知客姓名。"]', '["末秋云木轻，蓮折晚香清。","雨下侵苔色，云涼出浪声。","叠帆依岸尽，微照夾隄明。","渡吏已头白，遙知客姓名。"]', '诗', 'shi', '', NULL, '晚泊漢江渡 劉畋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa0104b2-3fd9-4f07-a71d-19083ff0fee9', '句', '句', '978b45bf-bd16-4509-a4b2-3435d89e2301', '唐', '["殘陽來霽岫，獨興起滄洲。"]', '["殘陽来霽岫，独兴起滄洲。"]', '诗', 'shi', '', NULL, '句 劉畋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38690232-17dc-4a98-99d6-07f8c59e37e3', '遊洞庭湖', '游洞庭湖', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["楚雲團翠八百里，澧蘭吹香墮春水。","白頭漁子搖蒼煙，鸂鶒眠沙曉驚起。","沙頭龍叟夜歎憂，鐵笛未響春風羞。","露寒紫藟結新愁，城角泣斷關河秋。","謫仙欲識雷斧手，剗却古今愁共醜。","鯨遊碧落杳無踪，作詩三歎君知否。","瀛洲一櫂何時還，滿江宮錦看湖山。"]', '["楚云團翠八百里，澧蘭吹香墮春水。","白头漁子搖蒼煙，鸂鶒眠沙晓驚起。","沙头龙叟夜歎憂，鐵笛未响春风羞。","露寒紫藟結新愁，城角泣斷关河秋。","謫仙欲識雷斧手，剗却古今愁共醜。","鯨游碧落杳無踪，作诗三歎君知否。","瀛洲一櫂何时還，满江宮錦看湖山。"]', '诗', 'shi', '', NULL, '遊洞庭湖 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6ff1e2f-0e01-4459-a5db-51239ab4345c', '懷素臺歌', '懷素台歌', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["我呼古人名，鬼神側耳聽。","杜甫李白與懷素，文星酒星草書星。","永州東郭有奇怪，筆冢墨池遺跡在。","筆冢低低高如山，墨池淺淺深如海。","我來恨不已，爭得青天化爲一張紙。","高聲喚起懷素書，搦管研朱點湘水。","欲歸家，重歎嗟。","眼前有三箇字，枯樹槎，烏梢蛇，墨老鵶。"]', '["我呼古人名，鬼神側耳听。","杜甫李白與懷素，文星酒星草书星。","永州东郭有奇怪，笔冢墨池遺跡在。","笔冢低低高如山，墨池淺淺深如海。","我来恨不已，爭得青天化爲一張紙。","高声喚起懷素书，搦管研朱点湘水。","欲归家，重歎嗟。","眼前有三箇字，枯樹槎，烏梢蛇，墨老鵶。"]', '诗', 'shi', '', NULL, '懷素臺歌 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04517228-74f6-41af-bcba-9bda057ed296', '聞砧', '闻砧', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["深閨乍冷鑑開篋，玉筯微微濕紅頰。","一陣霜風殺柳條，濃煙半夜成黃葉。","垂垂白練明如雪，獨下閑堦轉淒切。","祗知抱杵搗秋砧，不覺高樓已無月。","時聞寒雁聲相喚，紗窓只有燈相伴。","幾展齊紈又嬾裁，離腸恐逐金刀斷。","細想儀形執牙尺，回刀剪破澄江色。","愁捻銀鍼信手縫，惆悵無人試寬窄。","時時舉袖勻紅淚，紅牋謾有千行字。","書中不盡心中事，一片慇懃寄邊使。"]', '["深閨乍冷鑑开篋，玉筯微微濕紅頰。","一陣霜风殺柳條，濃煙半夜成黄葉。","垂垂白練明如雪，独下闲堦轉淒切。","祗知抱杵捣秋砧，不覺高楼已無月。","时闻寒雁声相喚，紗窓只有灯相伴。","幾展齊紈又嬾裁，離腸恐逐金刀斷。","細想儀形執牙尺，回刀剪破澄江色。","愁捻銀鍼信手縫，惆悵無人試寬窄。","时时舉袖勻紅泪，紅牋謾有千行字。","书中不尽心中事，一片慇懃寄邊使。"]', '诗', 'shi', '', NULL, '聞砧 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37bfc9c1-4135-4ba0-854a-2d0f1a2f5cf5', '春早寄華下同人', '春早寄华下同人', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["正是花時節，思君寢復興。","市沽終不醉，春夢亦無憑。","岳面懸青雨，河心走濁冰。","東門一條路，離恨鎮相仍。"]', '["正是花时節，思君寢复兴。","市沽終不醉，春梦亦無憑。","岳面懸青雨，河心走濁冰。","东门一條路，離恨鎮相仍。"]', '诗', 'shi', '', NULL, '春早寄華下同人 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76f9562f-aa08-4257-9634-c3e714326076', '贈衡山令', '贈衡山令', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["君吟十二載，辛苦必能官。","造化猶難隱，生靈豈易謾。","猿跳高岳靜，魚擺大江寬。","與我爲同道，相留夜話闌。"]', '["君吟十二載，辛苦必能官。","造化猶难隐，生靈豈易謾。","猿跳高岳静，鱼擺大江寬。","與我爲同道，相留夜話闌。"]', '诗', 'shi', '', NULL, '贈衡山令 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37a66d45-bfe5-4fc7-a629-6918b79ee8b4', '南中縣令', '南中縣令', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["寂寥雖下邑，良宰有清威。","苦節長如病，爲官豈肯肥。","山多村地狹，水淺客舟稀。","上國搜賢急，陶公早晚歸。"]', '["寂寥雖下邑，良宰有清威。","苦節长如病，爲官豈肯肥。","山多村地狹，水淺客舟稀。","上国搜賢急，陶公早晚归。"]', '诗', 'shi', '', NULL, '南中縣令 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5779950b-aa62-4bcb-a185-429204d80b7c', '寄曹松', '寄曹松', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["莫怪苦吟遲，詩成鬢亦絲。","鬢絲猶可染，詩病却難醫。","山暝雲橫處，星沈月側時。","冥搜不可得，一句至公知。"]', '["莫怪苦吟遲，诗成鬢亦絲。","鬢絲猶可染，诗病却难醫。","山暝云橫处，星沈月側时。","冥搜不可得，一句至公知。"]', '诗', 'shi', '', NULL, '寄曹松 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1084793e-4e3a-41b7-9808-259e0be11113', '贈賓貢', '贈賓貢', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["惟君懷至業，萬里信悠悠。","路向東[溟]出，枝來北闕求。","家無一夜夢，帆挂隔年秋。","鬢髮爭禁得，孤舟往復愁。"]', '["惟君懷至業，万里信悠悠。","路向东[溟]出，枝来北闕求。","家無一夜梦，帆挂隔年秋。","鬢髮爭禁得，孤舟往复愁。"]', '诗', 'shi', '', NULL, '贈賓貢 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('822840b5-ff7a-448a-95ec-801b555d16a7', '漢南郵亭', '漢南郵亭', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["高閣水風清，開門日送迎。","帆張獨鳥起，樂奏大魚驚。","驟雨拖山過，微風拂面生。","閑吟雖得句，留此謝多情。"]', '["高閣水风清，开门日送迎。","帆張独鸟起，乐奏大鱼驚。","驟雨拖山過，微风拂面生。","闲吟雖得句，留此謝多情。"]', '诗', 'shi', '', NULL, '漢南郵亭 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae3e162f-6d07-4f90-ab29-9751c747d535', '棋', '棋', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["十九條平路，言平又嶮巇。","人心無算處，國手有輸時。","勢逈流星遠，聲乾下雹遲。","臨軒才一局，寒日又西垂。"]', '["十九條平路，言平又嶮巇。","人心無算处，国手有輸时。","勢逈流星远，声乾下雹遲。","臨軒才一局，寒日又西垂。"]', '诗', 'shi', '', NULL, '棋 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f67ae712-e29a-4d5c-a18b-1ce75aba14a4', '夏日即事', '夏日即事', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["僻居門巷靜，竟日坐階墀。","鵲喜雖傳信，蛩吟不見詩。","筍抽通舊竹，梅落立閑枝。","此際無塵撓，僧來稱所宜。"]', '["僻居门巷静，竟日坐階墀。","鵲喜雖傳信，蛩吟不见诗。","筍抽通旧竹，梅落立闲枝。","此際無塵撓，僧来稱所宜。"]', '诗', 'shi', '', NULL, '夏日即事 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93a2ad3c-7dc2-46bc-8114-d7d5e4b27c76', '送人宰邑', '送人宰邑', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["官小任還重，命官難偶然。","皇恩輕一邑，赤子病三年。","瘦馬稀飡粟，羸童不識錢。","如君清苦節，到處有人傳。"]', '["官小任還重，命官难偶然。","皇恩轻一邑，赤子病三年。","瘦马稀飡粟，羸童不識錢。","如君清苦節，到处有人傳。"]', '诗', 'shi', '', NULL, '送人宰邑 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49968c68-8693-4c90-b3e4-6ffda80f18ba', '春暖送人下第', '春暖送人下第', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["相送短亭前，知君愚復賢。","事多憑夜夢，老爲待明年。","春樹添山脊，晴雲學曉煙。","雄文有公道，此別莫澘然。"]', '["相送短亭前，知君愚复賢。","事多憑夜梦，老爲待明年。","春樹添山脊，晴云学晓煙。","雄文有公道，此別莫澘然。"]', '诗', 'shi', '', NULL, '春暖送人下第 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b710d4a-a537-4ac6-96fd-c327adbfbfb1', '湖外送何崇入閣', '湖外送何崇入閣', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["因詩相識久，忽此告臨途。","便是有船發，也須容市沽。","精吟五箇字，穩泛兩重湖。","長短逢公道，清名振帝都。"]', '["因诗相識久，忽此告臨途。","便是有船發，也須容市沽。","精吟五箇字，穩泛兩重湖。","长短逢公道，清名振帝都。"]', '诗', 'shi', '', NULL, '湖外送何崇入閣 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6976d145-9fe3-47a1-ae82-a7614e6c5161', '送進士蘇瞻亂後出家', '送進士蘇瞻亂後出家', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["因亂事空王，孤心亦不傷。","梵僧爲骨肉，柏寺作家鄉。","眼閉千行淚，頭梳一把霜。","詩書不得力，誰與問蒼蒼。"]', '["因亂事空王，孤心亦不傷。","梵僧爲骨肉，柏寺作家乡。","眼閉千行泪，头梳一把霜。","诗书不得力，誰與问蒼蒼。"]', '诗', 'shi', '', NULL, '送進士蘇瞻亂後出家 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a7f41d9-d8e2-40d4-8757-79c19029a616', '秋日送河北從事', '秋日送河北從事', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["北風沙漠地，吾子遠從軍。","官路雖非遠，詩名要且聞。","蟬悲欲落日，鵰下擬陰雲。","此去難相戀，前山摻袂分。"]', '["北风沙漠地，吾子远從軍。","官路雖非远，诗名要且闻。","蟬悲欲落日，鵰下擬陰云。","此去难相戀，前山摻袂分。"]', '诗', 'shi', '', NULL, '秋日送河北從事 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db5620d2-67d1-4e8a-b39b-bb9e0ccf9b84', '喜友人再面', '喜友人再面', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["一別幾寒暄，迢迢隔塞垣。","相思長有事，及見却無言。","靜坐將茶試，閑書把葉翻。","依依又留宿，圓月上東軒。"]', '["一別幾寒暄，迢迢隔塞垣。","相思长有事，及见却無言。","静坐將茶試，闲书把葉翻。","依依又留宿，圓月上东軒。"]', '诗', 'shi', '', NULL, '喜友人再面 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1386a44a-bc5a-43e7-bf89-846bad3140e9', '對雪', '对雪', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["大片向空舞，出門肌骨寒。","路岐平即易，溝壑滿應難。","兔穴歸時失，禽枝宿處乾。","豪家寧肯厭，五月畫圖看。"]', '["大片向空舞，出门肌骨寒。","路岐平即易，溝壑满應难。","兔穴归时失，禽枝宿处乾。","豪家寧肯厭，五月畫圖看。"]', '诗', 'shi', '', NULL, '對雪 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3515d0f8-7d6b-41c8-9f98-77366eb6b9ef', '冬日後作', '冬日後作', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["寂寞掩荆扉，昏昏坐欲癡。","事無前定處，愁有併來時。","日影纔添線，鬢根已半絲。","明庭正公道，應許苦心詩。"]', '["寂寞掩荆扉，昏昏坐欲癡。","事無前定处，愁有併来时。","日影纔添線，鬢根已半絲。","明庭正公道，應許苦心诗。"]', '诗', 'shi', '', NULL, '冬日後作 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d47db03-2ee3-4555-8cb3-5bcb164cdf2c', '冬日作', '冬日作', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["糲食擁敗絮，苦吟吟過冬。","稍寒人却健，太飽事多慵。","樹老生煙薄，牆陰貯雪重。","安能只如此，公道會相容。"]', '["糲食擁敗絮，苦吟吟過冬。","稍寒人却健，太飽事多慵。","樹老生煙薄，牆陰貯雪重。","安能只如此，公道會相容。"]', '诗', 'shi', '', NULL, '冬日作 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71080d30-4dd4-4b3b-a73c-d4308bc0b956', '中秋月', '中秋月', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["一歲幾盈虧，當軒重此期。","幸無偏照處，剛有不明時。","色靜雲歸早，光寒鶴睡遲。","相看吟未足，皎皎下疎籬。"]', '["一歲幾盈虧，當軒重此期。","幸無偏照处，剛有不明时。","色静云归早，光寒鹤睡遲。","相看吟未足，皎皎下疎籬。"]', '诗', 'shi', '', NULL, '中秋月 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('126d88a2-367a-45c0-b8ab-160868b02fe4', '塞上曲', '塞上曲', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["極目望空闊，馬羸程又賒。","月生方見樹，風定始無沙。","楚水辭魚窟，燕山到雁家。","如斯名利役，爭不老天涯。"]', '["極目望空闊，马羸程又賒。","月生方见樹，风定始無沙。","楚水辞鱼窟，燕山到雁家。","如斯名利役，爭不老天涯。"]', '诗', 'shi', '', NULL, '塞上曲 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e35b895-4e09-4684-b145-c10fa5e6279a', '終南山', '終南山', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["九衢南面色，蒼翠絕纖塵。","寸步有閑處，百年無到人。","禁林寒對望，太華淨相鄰。","誰與羣峰並，祥雲瑞露頻。"]', '["九衢南面色，蒼翠絕纖塵。","寸步有闲处，百年無到人。","禁林寒对望，太华淨相鄰。","誰與羣峰並，祥云瑞露頻。"]', '诗', 'shi', '', NULL, '終南山 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce876e0a-68ac-4ffe-b735-02546c4639a8', '訪道士', '訪道士', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["高岡微雨後，木脫草堂新。","惟有疎慵者，來看淡薄人。","竹牙生礙路，松子落敲巾。","麤得玄中趣，當期宿話頻。"]', '["高岡微雨後，木脫草堂新。","惟有疎慵者，来看淡薄人。","竹牙生礙路，松子落敲巾。","麤得玄中趣，當期宿話頻。"]', '诗', 'shi', '', NULL, '訪道士 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('237f07cc-729b-4af7-af21-cae00a44bf52', '道林寺', '道林寺', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["獨立憑危闌，高低落照間。","寺分一派水，僧鎖半房山。","對面浮世隔，垂簾到老閑。","煙雲與塵土，寸步不相關。"]', '["独立憑危闌，高低落照间。","寺分一派水，僧鎖半房山。","对面浮世隔，垂簾到老闲。","煙云與塵土，寸步不相关。"]', '诗', 'shi', '', NULL, '道林寺 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4dc15366-2770-4a69-a4bc-279e51c306c5', '般若寺', '般若寺', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["南嶽古般若，自來天下知。","翠籠無價寺，光射有名詩。","一水湧獸跡，五峰排鳳儀。","高僧引閑步，晝出夕陽歸。"]', '["南嶽古般若，自来天下知。","翠籠無價寺，光射有名诗。","一水湧獸跡，五峰排鳳儀。","高僧引闲步，晝出夕陽归。"]', '诗', 'shi', '', NULL, '般若寺 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70c5664f-c775-48d1-9a55-301a4e3b6ef7', '兜率寺', '兜率寺', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["一片無塵地，高連夢澤南。","僧居跨鳥道，佛影照魚潭。","朽枿雲斜映，平蕪日半涵。","行行不得住，回首望煙嵐。"]', '["一片無塵地，高連梦澤南。","僧居跨鸟道，佛影照鱼潭。","朽枿云斜映，平蕪日半涵。","行行不得住，回首望煙嵐。"]', '诗', 'shi', '', NULL, '兜率寺 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c04e408e-84bb-4e11-8a4c-59881a0cabfa', '鹿門寺', '鹿门寺', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["鹿門山上寺，突兀盡無塵。","到此修行者，應非取次人。","鳥過驚石磬，日出礙金身。","何計生煩惱，虛空是四鄰。"]', '["鹿门山上寺，突兀尽無塵。","到此修行者，應非取次人。","鸟過驚石磬，日出礙金身。","何計生煩惱，虛空是四鄰。"]', '诗', 'shi', '', NULL, '鹿門寺 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41c23948-3d4b-4b52-8489-153143a1e6ac', '題岳州僧舍', '題岳州僧舍', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["喜到重湖北，孤州橫晚煙。","鷺銜魚入寺，鵶接飯隨船。","松檜君山逈，菰蒲夢澤連。","與師吟論處，秋水浸遙天。"]', '["喜到重湖北，孤州橫晚煙。","鷺銜鱼入寺，鵶接飯隨船。","松檜君山逈，菰蒲梦澤連。","與師吟論处，秋水浸遙天。"]', '诗', 'shi', '', NULL, '題岳州僧舍 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f223bcbc-bd70-44cc-8380-ef38958ebe2b', '過洞庭湖', '過洞庭湖', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["浪高風力大，挂席亦言遲。","及到堪憂處，爭如未濟時。","魚龍侵莫測，雷雨動須疑。","此際情無賴，何門寄所思。"]', '["浪高风力大，挂席亦言遲。","及到堪憂处，爭如未濟时。","鱼龙侵莫測，雷雨动須疑。","此際情無賴，何门寄所思。"]', '诗', 'shi', '', NULL, '過洞庭湖 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5568477b-3eed-4b6c-9def-910a3cefd20d', '旅行聞寇', '旅行闻寇', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["動步憂多事，將行問四鄰。","深山不畏虎，當路却防人。","豪富田園廢，疲羸屋舍新。","自慙爲旅客，無計避煙塵。"]', '["动步憂多事，將行问四鄰。","深山不畏虎，當路却防人。","豪富田园廢，疲羸屋舍新。","自慙爲旅客，無計避煙塵。"]', '诗', 'shi', '', NULL, '旅行聞寇 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9eef7cd5-886a-4803-8516-72c333ffc4c4', '旅中作', '旅中作', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["妄動遠拋山，其如餒與寒。","投人言去易，開口說貧難。","澤國雲千片，湘江竹一竿。","時明未忍別，猶待計窮看。"]', '["妄动远拋山，其如餒與寒。","投人言去易，开口说貧难。","澤国云千片，湘江竹一竿。","时明未忍別，猶待計窮看。"]', '诗', 'shi', '', NULL, '旅中作 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('513fc384-eca0-493e-897b-3b4a722e8f86', '旅次衡陽', '旅次衡陽', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["欲往幾經年，今來意豁然。","江風長借客，岳雨不因天。","戲鷺飛輕雪，驚鴻呌亂煙。","晚秋紅藕裏，十宿寄漁船。"]', '["欲往幾經年，今来意豁然。","江风长借客，岳雨不因天。","戲鷺飞轻雪，驚鴻呌亂煙。","晚秋紅藕裏，十宿寄漁船。"]', '诗', 'shi', '', NULL, '旅次衡陽 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('363bff95-6035-4d1c-b674-2947238a8164', '不出院僧', '不出院僧', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["四遠參尋徧，修行却不行。","耳邊無俗語，門外是前生。","塔見移來影，鐘聞過去聲。","一齋唯默坐，應笑我營營。"]', '["四远參尋徧，修行却不行。","耳邊無俗語，门外是前生。","塔见移来影，鐘闻過去声。","一斋唯默坐，應笑我營營。"]', '诗', 'shi', '', NULL, '不出院僧 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c19deb7c-c7a6-424a-aa6f-97666066b8ab', '湖外寄處賓上人', '湖外寄处賓上人', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["怪得意相親，高攜一軸新。","能搜大雅句，不似小乘人。","嶽麓擎枯檜，瀟湘吐白蘋。","他年遇同道，爲我話風塵。"]', '["怪得意相親，高携一軸新。","能搜大雅句，不似小乘人。","嶽麓擎枯檜，瀟湘吐白蘋。","他年遇同道，爲我話风塵。"]', '诗', 'shi', '', NULL, '湖外寄處賓上人 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('618ec44f-ba5c-4aa7-8ab6-1c26b7f97774', '寄貫休', '寄貫休', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["憶昔與吾師，山中靜論時。","總無方是法，難得始爲詩。","凍犬眠乾葉，飢禽啄病梨。","他年白蓮社，猶許重相期。"]', '["憶昔與吾師，山中静論时。","總無方是法，难得始爲诗。","凍犬眠乾葉，飢禽啄病梨。","他年白蓮社，猶許重相期。"]', '诗', 'shi', '', NULL, '寄貫休 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c014ac81-7f9e-4c12-9e83-fbd91cea1d83', '寄僧尚顏', '寄僧尚顏', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["曾居五老峰，所得共誰同。","才大天全與，吟精楚欲空。","客來庭減日，鳥過竹生風。","早晚搖輕拂，重歸瀑布中。"]', '["曾居五老峰，所得共誰同。","才大天全與，吟精楚欲空。","客来庭減日，鸟過竹生风。","早晚搖轻拂，重归瀑布中。"]', '诗', 'shi', '', NULL, '寄僧尚顏 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46f45c84-1a15-47c7-abd0-d4b888af9309', '哭處默上人', '哭处默上人', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["淒涼繐幕下，香吐一燈分。","鬬老輸寒檜，留閑與白雲。","挈盂曾幾度，傳衲不教焚。","泣罷重回首，暮山鐘半聞。"]', '["淒涼繐幕下，香吐一灯分。","鬬老輸寒檜，留闲與白云。","挈盂曾幾度，傳衲不教焚。","泣罷重回首，暮山鐘半闻。"]', '诗', 'shi', '', NULL, '哭處默上人 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2859f8e7-e2e5-41b1-af95-f9b28c61626a', '廬山瀑布', '廬山瀑布', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["靜景憑高望，光分翠嶂開。","嶮飛千尺雪，寒撲一聲雷。","過去雲衝斷，旁來燒隔廻。","何當住峰下，終歲絕塵埃。"]', '["静景憑高望，光分翠嶂开。","嶮飞千尺雪，寒撲一声雷。","過去云衝斷，旁来燒隔廻。","何當住峰下，終歲絕塵埃。"]', '诗', 'shi', '', NULL, '廬山瀑布 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c25a3e47-051d-4b17-b729-1328e5583a39', '華山上方', '华山上方', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["獨上上方上，立高聊稱心。","氣衝雲易黑，影落縣多陰。","有雲草不死，無風松自吟。","會當求大藥，他日復追尋。"]', '["独上上方上，立高聊稱心。","氣衝云易黑，影落縣多陰。","有云草不死，無风松自吟。","會當求大藥，他日复追尋。"]', '诗', 'shi', '', NULL, '華山上方 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97582184-21c7-4f82-9f49-a80c8e30d0df', '詠鸚鵡', '詠鸚鵡', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["常貴西山鳥，銜恩在玉堂。","語傳明主意，衣拂美人香。","緩步尋珠網，高飛上畫梁。","長安頻道樂，何日從君王。"]', '["常貴西山鸟，銜恩在玉堂。","語傳明主意，衣拂美人香。","緩步尋珠網，高飞上畫梁。","长安頻道乐，何日從君王。"]', '诗', 'shi', '', NULL, '詠鸚鵡 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cb2e663-bb27-40b3-abec-ba6ff12afce9', '鷺鷥', '鷺鷥', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["秋江清淺時，魚過亦頻窺。","却爲分明極，翻成所得遲。","浴偎紅日色，棲壓碧蘆枝。","會共鵷同侶，翺翔應可期。"]', '["秋江清淺时，鱼過亦頻窺。","却爲分明極，翻成所得遲。","浴偎紅日色，棲壓碧蘆枝。","會共鵷同侶，翺翔應可期。"]', '诗', 'shi', '', NULL, '鷺鷥 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3ac669f-ef56-4e7a-b4f6-7da96f54a069', '牡丹', '牡丹', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["數朵欲傾城，安同桃李榮。","未嘗貧處見，不似地中生。","此物疑無價，當春獨有名。","遊蜂與蝴蝶，來往自多情。"]', '["數朵欲傾城，安同桃李榮。","未嘗貧处见，不似地中生。","此物疑無價，當春独有名。","游蜂與蝴蝶，来往自多情。"]', '诗', 'shi', '', NULL, '牡丹 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d84a1d6c-b0a6-43a0-83f7-b3c5dabdbcf0', '見王貞白', '见王貞白', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["共賀登科後，明宣入紫宸。","又看重試榜，還見苦吟人。","此得名渾別，歸來話亦新。","分明一枝桂，堪動楚江濱。"]', '["共賀登科後，明宣入紫宸。","又看重試榜，還见苦吟人。","此得名渾別，归来話亦新。","分明一枝桂，堪动楚江濱。"]', '诗', 'shi', '', NULL, '見王貞白 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c64fb66-2c36-4866-a2a7-3508dd901c49', '經杜工部墳', '經杜工部墳', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["騷人久不出，安得國風清。","擬掘孤墳破，重教大雅生。","皇天高莫問，白酒恨難平。","悒怏寒江上，誰人知此情。"]', '["騷人久不出，安得国风清。","擬掘孤墳破，重教大雅生。","皇天高莫问，白酒恨难平。","悒怏寒江上，誰人知此情。"]', '诗', 'shi', '', NULL, '經杜工部墳 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ccce8e3-1f79-44bf-bf27-39db091ba39d', '寄僧知乾', '寄僧知乾', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["貌高清入骨，帝里舊臨壇。","出語經相似，行心佛證安。"]', '["貌高清入骨，帝里旧臨壇。","出語經相似，行心佛證安。"]', '诗', 'shi', '', NULL, '寄僧知乾 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d37902f-1d76-4551-9b1a-a78ea50a0400', '亂中偷路入故鄉', '亂中偷路入故乡', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["愁看賊火起諸烽，偷得餘程悵望中。","一國半爲亡國燼，數城俱作古城空。"]', '["愁看賊火起諸烽，偷得餘程悵望中。","一国半爲亡国燼，數城俱作古城空。"]', '诗', 'shi', '', NULL, '亂中偷路入故鄉 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d09bc622-2cbb-4bc2-b44e-2025bb97c356', '薔薇', '薔薇', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["一架長條萬朵春，嫩紅深綠小窠勻。","只應根下千年土，曾葬西川織錦人。"]', '["一架长條万朵春，嫩紅深綠小窠勻。","只應根下千年土，曾葬西川织錦人。"]', '诗', 'shi', '', NULL, '薔薇 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f218ba8-5435-41c9-9157-7bdd2f8e6cfc', '春日山中竹', '春日山中竹', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["數竿蒼翠擬龍形，峭拔須教此地生。","無限野花開不得，半山寒色與春爭。"]', '["數竿蒼翠擬龙形，峭拔須教此地生。","無限野花开不得，半山寒色與春爭。"]', '诗', 'shi', '', NULL, '春日山中竹 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e603c101-a23a-413b-ad14-b08e218c117e', '柳', '柳', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["高拂危樓低拂塵，灞橋攀折一何頻。","思量却是無情樹，不解迎人只送人。"]', '["高拂危楼低拂塵，灞橋攀折一何頻。","思量却是無情樹，不解迎人只送人。"]', '诗', 'shi', '', NULL, '柳 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd280271-92d4-4466-b715-39c75b5f45e7', '岳陽兵火後題僧舍', '岳陽兵火後題僧舍', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["十年兵火真多事，再到禪扉却破顏。","唯有兩般燒不得，洞庭湖水老僧閑。"]', '["十年兵火真多事，再到禪扉却破顏。","唯有兩般燒不得，洞庭湖水老僧闲。"]', '诗', 'shi', '', NULL, '岳陽兵火後題僧舍 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('678c0799-cd43-43c0-9503-26d4645ff022', '句', '句', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["讀書貧裏樂，搜句靜中忙。","苦吟僧入定，得句將成功。","是事精皆易，唯詩會却難。","因攜一家住，贏得半年吟。","吟餘潮入浦，坐久燒移山。","三年清似水，六月冷如冰。","一通紅錦重，三事紫羅輕。","瘦肌寒帶粟，病眼餒生花。","避亂一生多，雪留寒竹寺舍冷。","風撼早梅城郭香，畫毬輕蹴壺中地。","綵索高飛掌上身。"]', '["读书貧裏乐，搜句静中忙。","苦吟僧入定，得句將成功。","是事精皆易，唯诗會却难。","因携一家住，贏得半年吟。","吟餘潮入浦，坐久燒移山。","三年清似水，六月冷如冰。","一通紅錦重，三事紫羅轻。","瘦肌寒带粟，病眼餒生花。","避亂一生多，雪留寒竹寺舍冷。","风撼早梅城郭香，畫毬轻蹴壺中地。","綵索高飞掌上身。"]', '诗', 'shi', '', NULL, '句 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e3f6a3d-0c41-4ec7-804d-97d138241a24', '贈唐山人', '贈唐山人', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["垂鬚長似髮，七十色如黳。","醉眼青天小，吟情太華低。","千年松繞屋，半夜雨連溪。","邛蜀路無限，往來琴獨攜。"]', '["垂鬚长似髮，七十色如黳。","醉眼青天小，吟情太华低。","千年松繞屋，半夜雨連溪。","邛蜀路無限，往来琴独携。"]', '诗', 'shi', '', NULL, '贈唐山人 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73cf71e9-a558-4a5c-a6b4-ea8f5a49d16a', '送雲卿上人游安南', '送云卿上人游安南', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["春往海南邊，秋聞半夜蟬。","鯨吞洗鉢水，犀觸點燈船。","島嶼分諸國，星河共一天。","長安却迴日，松偃舊房前。"]', '["春往海南邊，秋闻半夜蟬。","鯨吞洗鉢水，犀觸点灯船。","島嶼分諸国，星河共一天。","长安却迴日，松偃旧房前。"]', '诗', 'shi', '', NULL, '送雲卿上人游安南 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e6b17a7-2c56-49cc-9262-aee91d573587', '鄭補闕山居', '鄭補闕山居', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["高節諫垣客，白雲居靜坊。","馬飢餐落葉，鶴病曬殘陽。","野霧昏朝燭，溪牋惹御香。","相招倚蒲壁，論句夜何長。"]', '["高節諫垣客，白云居静坊。","马飢餐落葉，鹤病曬殘陽。","野霧昏朝燭，溪牋惹御香。","相招倚蒲壁，論句夜何长。"]', '诗', 'shi', '', NULL, '鄭補闕山居 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9e89292-9e3a-485e-bb3a-8fd48ffe253f', '送曹郎中南歸時南中用軍', '送曹郎中南归时南中用軍', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["桂水淨和天，南歸似謫仙。","繫絛輕象笏，買布接蠻船。","海氣蒸鼙軟，江風激箭偏。","罷郎吟亂裏，帝遠豈知賢。"]', '["桂水淨和天，南归似謫仙。","繫絛轻象笏，買布接蠻船。","海氣蒸鼙軟，江风激箭偏。","罷郎吟亂裏，帝远豈知賢。"]', '诗', 'shi', '', NULL, '送曹郎中南歸時南中用軍 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c54c4e5d-cb5e-4176-9f7d-07da3468aac4', '錦江陪兵部鄭侍郎話詩著棊', '錦江陪兵部鄭侍郎話诗著棊', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["落葉濺吟身，會棊雲外人。","海枯搜不盡，天定著長新。","月上分題遍，鐘殘布子勻。","忘餐二絕境，取意鑄陶鈞。"]', '["落葉濺吟身，會棊云外人。","海枯搜不尽，天定著长新。","月上分題遍，鐘殘布子勻。","忘餐二絕境，取意鑄陶鈞。"]', '诗', 'shi', '', NULL, '錦江陪兵部鄭侍郎話詩著棊 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5bb6110-6129-49a8-8a26-ee3eb12815d6', '中秋月', '中秋月', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["四十五秋宵，月分千里毫。","冷沈中嶽短，光溢太行高。","不寐清人眼，移棲濕鶴毛。","露華臺上別，吟望十年勞。"]', '["四十五秋宵，月分千里毫。","冷沈中嶽短，光溢太行高。","不寐清人眼，移棲濕鹤毛。","露华台上別，吟望十年勞。"]', '诗', 'shi', '', NULL, '中秋月 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('788f1ad1-15c9-4b5d-8e9d-53509c83abc1', '送沈光赴福幕', '送沈光赴福幕', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["泉齊嶺鳥飛，雨熟荔枝肥。","南斗看應近，北人來恐稀。","潮浮廉使宴，珠照島僧歸。","幕下逢遷拜，何官着茜衣。"]', '["泉齊嶺鸟飞，雨熟荔枝肥。","南斗看應近，北人来恐稀。","潮浮廉使宴，珠照島僧归。","幕下逢遷拜，何官着茜衣。"]', '诗', 'shi', '', NULL, '送沈光赴福幕 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82ae295e-360d-4e4e-be5a-1ed9f27e7cd7', '鄠郊山舍題趙處士林亭', '鄠郊山舍題趙处士林亭', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["圭峰秋後疊，亂葉落寒墟。","四五百竿竹，二三千卷書。","雲深猿拾栗，雨霽蟻緣蔬。","只隔門前水，如同萬里餘。"]', '["圭峰秋後叠，亂葉落寒墟。","四五百竿竹，二三千卷书。","云深猿拾栗，雨霽蟻緣蔬。","只隔门前水，如同万里餘。"]', '诗', 'shi', '', NULL, '鄠郊山舍題趙處士林亭 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f73ea87-0ea1-4cdc-b224-ca76236abe77', '賦得送賈島謫長江', '賦得送賈島謫长江', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["敲驢吟雪月，謫出國西門。","行傍長江影，愁深汨水魂。","笻攜過竹寺，琴典在花村。","飢拾山松子，誰知賈傅孫。"]', '["敲驢吟雪月，謫出国西门。","行傍长江影，愁深汨水魂。","笻携過竹寺，琴典在花村。","飢拾山松子，誰知賈傅孫。"]', '诗', 'shi', '', NULL, '賦得送賈島謫長江 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a076c629-99c0-4c67-b662-1a2b8fa54210', '河陽道中', '河陽道中', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["衝風仍躡凍，提轡手頻呵。","得事應須早，愁人不在多。","雪田平入塞，煙郭曲隨河。","飜憶江濤裏，船中睡蓋蓑。"]', '["衝风仍躡凍，提轡手頻呵。","得事應須早，愁人不在多。","雪田平入塞，煙郭曲隨河。","飜憶江濤裏，船中睡蓋蓑。"]', '诗', 'shi', '', NULL, '河陽道中 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd0603b1-22cb-455c-87e2-f15a07470843', '送知己赴濮州', '送知己赴濮州', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["中路行僧謁，郵亭話海濤。","劒搖林狖落，旗閃岳禽高。","苔長空州獄，花開夢省曹。","濮陽流政化，一半布風騷。"]', '["中路行僧謁，郵亭話海濤。","劒搖林狖落，旗閃岳禽高。","苔长空州獄，花开梦省曹。","濮陽流政化，一半布风騷。"]', '诗', 'shi', '', NULL, '送知己赴濮州 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1affd2e2-07c9-4c11-acd5-e63213a6ccf2', '送行脚僧', '送行脚僧', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["缾枕繞腰垂，出門何所之。","毳衣霑雨重，椶笠看山欹。","夜觀入枯樹，野眠逢斷碑。","鄰房母淚下，相課別離詞。"]', '["缾枕繞腰垂，出门何所之。","毳衣霑雨重，椶笠看山欹。","夜观入枯樹，野眠逢斷碑。","鄰房母泪下，相課別離词。"]', '诗', 'shi', '', NULL, '送行脚僧 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c98dcd1-a93e-4664-a63c-df62b04ca798', '龍州送人赴舉', '龙州送人赴舉', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["獻策赴招攜，行宮積翠西。","挈囊秋卷重，轉棧晚峰齊。","踏月趨金闕，拂雲看御題。","飛鳴豈回顧，獨鶴困江泥。"]', '["獻策赴招携，行宮積翠西。","挈囊秋卷重，轉棧晚峰齊。","踏月趨金闕，拂云看御題。","飞鳴豈回顧，独鹤困江泥。"]', '诗', 'shi', '', NULL, '龍州送人赴舉 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43455d60-ad4a-4531-ba0e-3452c72c5e5a', '送安撫從兄夷偶中丞', '送安撫從兄夷偶中丞', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["奉詔向軍前，朱袍暎雪鮮。","河橋吹角凍，嶽月卷旗圓。","僧救焚經火，人修著釣船。","六州安撫後，萬戶解衣眠。"]', '["奉詔向軍前，朱袍暎雪鲜。","河橋吹角凍，嶽月卷旗圓。","僧救焚經火，人修著釣船。","六州安撫後，万戶解衣眠。"]', '诗', 'shi', '', NULL, '送安撫從兄夷偶中丞 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4aa267cd-08ab-419b-8259-a0fbbc3bcaa4', '送遠上人', '送远上人', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["海嶽兩無邊，去來都偶然。","齒因吟後冷，心向靜中圓。","蟲網花間井，鴻鳴雨後天。","葉書歸舊寺，應附載鐘船。"]', '["海嶽兩無邊，去来都偶然。","齒因吟後冷，心向静中圓。","蟲網花间井，鴻鳴雨後天。","葉书归旧寺，應附載鐘船。"]', '诗', 'shi', '', NULL, '送遠上人 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de2bfa12-cd5f-41e3-859d-af38ed2d3b34', '宿鳳翔天柱寺窮易玄上人房', '宿鳳翔天柱寺窮易玄上人房', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["天柱暮相逢，吟思天柱峰。","墨研青露月，茶吸白雲鐘。","臥語身黏蘚，行禪頂拂松。","探玄爲一決，明日去臨邛。"]', '["天柱暮相逢，吟思天柱峰。","墨研青露月，茶吸白云鐘。","臥語身黏蘚，行禪頂拂松。","探玄爲一決，明日去臨邛。"]', '诗', 'shi', '', NULL, '宿鳳翔天柱寺窮易玄上人房 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cee609d-a344-4284-9c33-38d3bc06cf5d', '下第送張霞歸覲江南', '下第送張霞归覲江南', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["此道背於時，攜歸一軸詩。","樹沈孤鳥遠，風逆蹇驢遲。","草入吟房壞，潮衝釣石移。","恐傷歡覲意，半路摘愁髭。"]', '["此道背於时，携归一軸诗。","樹沈孤鸟远，风逆蹇驢遲。","草入吟房壞，潮衝釣石移。","恐傷歡覲意，半路摘愁髭。"]', '诗', 'shi', '', NULL, '下第送張霞歸覲江南 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1c3e41d-abbf-493d-857b-1310850859b3', '送人之天台', '送人之天台', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["行李一枝藤，雲邊曉扣冰。","丹經如不謬，白髮亦何能。","淺井仙人鏡，明珠海客燈。","乃知真隱者，笑就漢廷徴。"]', '["行李一枝藤，云邊晓扣冰。","丹經如不謬，白髮亦何能。","淺井仙人镜，明珠海客灯。","乃知真隐者，笑就漢廷徴。"]', '诗', 'shi', '', NULL, '送人之天台 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cce0f37e-2e0b-43d8-ba1c-bd7ff2650a8e', '維摩暢林居', '維摩暢林居', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["諸方游幾臘，五夏五峰銷。","越講迎騎象，蕃齋懺射鵰。","冷筇和雪倚，朽櫟帶雲燒。","從此西林老，瞥然三萬朝。"]', '["諸方游幾臘，五夏五峰銷。","越講迎騎象，蕃斋懺射鵰。","冷筇和雪倚，朽櫟带云燒。","從此西林老，瞥然三万朝。"]', '诗', 'shi', '', NULL, '維摩暢林居 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d00b4df-f560-4cb3-92e9-eb2282038793', '送張喬下第歸宣州', '送張喬下第归宣州', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["詩道世難通，歸寧楚浪中。","早程殘嶽月，夜泊隔淮鐘。","一鏡隨雙鬢，全家老半峰。","無成來往過，折盡謝亭松。"]', '["诗道世难通，归寧楚浪中。","早程殘嶽月，夜泊隔淮鐘。","一镜隨雙鬢，全家老半峰。","無成来往過，折尽謝亭松。"]', '诗', 'shi', '', NULL, '送張喬下第歸宣州 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a245422b-ea2b-4e25-a4de-0dc2970a095b', '送盧郎中赴金州', '送盧郎中赴金州', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["雲明天嶺高，刺郡輟仙曹。","危棧窺猿頂，公庭埽鶴毛。","出軍青壁罅，話道白眉毫。","遠集歌謠客，州前泊幾艘。"]', '["云明天嶺高，刺郡輟仙曹。","危棧窺猿頂，公庭埽鹤毛。","出軍青壁罅，話道白眉毫。","远集歌謠客，州前泊幾艘。"]', '诗', 'shi', '', NULL, '送盧郎中赴金州 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('440a89da-70cd-4130-99f3-7fa5c608ba48', '江干即事', '江干即事', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["病臥四更後，愁聞報早衙。","隔關沈水鳥，侵郭噪園鴉。","吏瘦餐溪栢，身羸憑海槎。","滿朝吟五字，應不老煙霞。"]', '["病臥四更後，愁闻報早衙。","隔关沈水鸟，侵郭噪园鴉。","吏瘦餐溪栢，身羸憑海槎。","满朝吟五字，應不老煙霞。"]', '诗', 'shi', '', NULL, '江干即事 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42482ecf-6871-4a95-9df5-85b908fd216c', '寄賀鄭常侍', '寄賀鄭常侍', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["山亦懷恩地，高禽盡下飛。","吏穿霞片望，僧埽月稜歸。","省拜墀煙近，林居玉漏微。","曾令駐錫話，聊用慰攀依。"]', '["山亦懷恩地，高禽尽下飞。","吏穿霞片望，僧埽月稜归。","省拜墀煙近，林居玉漏微。","曾令駐錫話，聊用慰攀依。"]', '诗', 'shi', '', NULL, '寄賀鄭常侍 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7549405-8160-48a2-8865-273176c65a27', '登樓', '登楼', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["川上值樓開，寒山四面來。","竹吹人語遠，峰礙鳥飛迴。","生死別離陌，朝昏雲雨堆。","誰知獨立意，濺淚落莓苔。"]', '["川上值楼开，寒山四面来。","竹吹人語远，峰礙鸟飞迴。","生死別離陌，朝昏云雨堆。","誰知独立意，濺泪落莓苔。"]', '诗', 'shi', '', NULL, '登樓 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5db456e2-61e3-4a28-85a3-d0414914f964', '贈禪友', '贈禪友', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["散花留內殿，宮女夢談禪。","樹杪開樓鎖，雲中認嶽蓮。","溪聲過長耳，筇節出羸肩。","飛句相招宿，多逢有月天。"]', '["散花留內殿，宮女梦談禪。","樹杪开楼鎖，云中認嶽蓮。","溪声過长耳，筇節出羸肩。","飞句相招宿，多逢有月天。"]', '诗', 'shi', '', NULL, '贈禪友 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f59a4e1e-75f9-4a09-afe6-79ff58e72d86', '早春友人訪別南歸', '早春友人訪別南归', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["南歸來取別，窮巷坐青苔。","一盞薄醨酒，數枝零落梅。","潮生楚驛閉，星在越樓開。","明日望君處，前臨風月臺。"]', '["南归来取別，窮巷坐青苔。","一盞薄醨酒，數枝零落梅。","潮生楚驛閉，星在越楼开。","明日望君处，前臨风月台。"]', '诗', 'shi', '', NULL, '早春友人訪別南歸 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d55f4392-a769-4209-8db3-77cdabb9c8fd', '題雲際寺', '題云際寺', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["開門風雪頂，上徹困飛禽。","猿戲青冥裏，人行紫閣陰。","臘泉冰下出，夜磬月中尋。","盡欲居巖室，如何不住心。"]', '["开门风雪頂，上徹困飞禽。","猿戲青冥裏，人行紫閣陰。","臘泉冰下出，夜磬月中尋。","尽欲居巖室，如何不住心。"]', '诗', 'shi', '', NULL, '題雲際寺 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23b6c370-2632-4abd-9b15-df6c3b68079f', '山寺老僧', '山寺老僧', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["雲際衆僧裏，獨攢眉似愁。","護茶高夏臘，愛火老春秋。","海浪南曾病，河冰北苦遊。","歸來諸弟子，白徧後生頭。"]', '["云際衆僧裏，独攢眉似愁。","護茶高夏臘，愛火老春秋。","海浪南曾病，河冰北苦游。","归来諸弟子，白徧後生头。"]', '诗', 'shi', '', NULL, '山寺老僧 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df3a7185-1a73-43d5-845a-ec90ffea8d2a', '同僧宿道者院', '同僧宿道者院', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["攜文過水宿，拂席四廊塵。","墜果敲樓瓦，高螢暎鶴身。","點燈吹葉火，談佛悟山人。","盡有棲霞志，好謀三教鄰。"]', '["携文過水宿，拂席四廊塵。","墜果敲楼瓦，高螢暎鹤身。","点灯吹葉火，談佛悟山人。","尽有棲霞志，好謀三教鄰。"]', '诗', 'shi', '', NULL, '同僧宿道者院 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8582267f-f885-4180-9db3-5eb53f5eeb68', '古栢', '古栢', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["手植知何代，年齊偃蓋松。","結根生別樹，吹子落鄰峰。","古榦經龍嗅，高煙過雁衝。","可佳繁葉盡，聲不礙秋鐘。"]', '["手植知何代，年齊偃蓋松。","結根生別樹，吹子落鄰峰。","古榦經龙嗅，高煙過雁衝。","可佳繁葉尽，声不礙秋鐘。"]', '诗', 'shi', '', NULL, '古栢 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a70a6053-647e-4820-bb38-469574cc23d9', '贈王鳳二山人', '贈王鳳二山人', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["山兄望鶴信，山弟聽烏占。","養藥同開鼎，休棊各枕奩。","相逢九江底，共到五峰尖。","願許爲三友，羞將白髮撏。"]', '["山兄望鹤信，山弟听烏占。","養藥同开鼎，休棊各枕奩。","相逢九江底，共到五峰尖。","願許爲三友，羞將白髮撏。"]', '诗', 'shi', '', NULL, '贈王鳳二山人 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89c72bd8-2294-46de-9d7f-34391e8b6daf', '避地冬夜與二三禪侶吟集茅齋', '避地冬夜與二三禪侶吟集茅斋', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["四海通禪客，搜吟會草亭。","撚髭孤燭白，閉目衆山青。","松挂敲冰杖，罏溫注月缾。","獨愁懸舊斾，笏冷立殘星。"]', '["四海通禪客，搜吟會草亭。","撚髭孤燭白，閉目衆山青。","松挂敲冰杖，罏溫注月缾。","独愁懸旧斾，笏冷立殘星。"]', '诗', 'shi', '', NULL, '避地冬夜與二三禪侶吟集茅齋 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c777b9b0-bb9f-4726-8308-e28cfd16b014', '贈道微禪師', '贈道微禪師', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["銅缾澀瀉水，出磧躡蓮層。","猛虎降低鼠，盤鵰望小蠅。","通禪五天日，照祖幾朝燈。","短髮歸林白，何妨剃未能。"]', '["銅缾澀瀉水，出磧躡蓮層。","猛虎降低鼠，盤鵰望小蠅。","通禪五天日，照祖幾朝灯。","短髮归林白，何妨剃未能。"]', '诗', 'shi', '', NULL, '贈道微禪師 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1556fc7-e7f6-40d4-a2a5-fc62fd7720b7', '弔草堂禪師', '弔草堂禪師', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["杖屨疑師在，房關四壁蛬。","貯缾經臘水，響塔隔山鐘。","乳鴿沿苔井，齋猿散雪峰。","如何不見性，倚徧寺前松。"]', '["杖屨疑師在，房关四壁蛬。","貯缾經臘水，响塔隔山鐘。","乳鴿沿苔井，斋猿散雪峰。","如何不见性，倚徧寺前松。"]', '诗', 'shi', '', NULL, '弔草堂禪師 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4829580-dddf-4cec-8191-e08d9bc3b17d', '宿長安蘇雍主簿廳', '宿长安蘇雍主簿廳', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["縣對數峰雲，官清主簿貧。","聽更池上鶴，伴值岳陽人。","井鎖煎茶水，廳關擣藥塵。","往來多屣步，同舍即諸鄰。"]', '["縣对數峰云，官清主簿貧。","听更池上鹤，伴值岳陽人。","井鎖煎茶水，廳关擣藥塵。","往来多屣步，同舍即諸鄰。"]', '诗', 'shi', '', NULL, '宿長安蘇雍主簿廳 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94f119dd-4200-4f1e-b881-53c7ece90744', '秋宿潤州劉處士江亭', '秋宿潤州劉处士江亭', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["北夢風吹斷，江邊處士亭。","吟生萬井月，見盡一天星。","浪靜魚衝鎖，窗高鶴聽經。","東西渺無際，世界半滄溟。"]', '["北梦风吹斷，江邊处士亭。","吟生万井月，见尽一天星。","浪静鱼衝鎖，窗高鹤听經。","东西渺無際，世界半滄溟。"]', '诗', 'shi', '', NULL, '秋宿潤州劉處士江亭 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2acb8579-dd39-4dd4-b10c-40e543e01d43', '秋日曲江書事', '秋日曲江书事', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["門搖枯葦影，落日共鷗歸。","園近鹿來熟，江寒人到稀。","片雲穿塔過，枯葉入城飛。","翻怕賓鴻至，無才動禮闈。"]', '["门搖枯葦影，落日共鷗归。","园近鹿来熟，江寒人到稀。","片云穿塔過，枯葉入城飞。","翻怕賓鴻至，無才动禮闈。"]', '诗', 'shi', '', NULL, '秋日曲江書事 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('065f277f-9101-4a32-bb53-1707e1d645f8', '秋宿經上人房', '秋宿經上人房', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["江房無葉落，松影帶山高。","滿寺中秋月，孤窗入夜濤。","舊真懸石壁，衰髮落銅刀。","臥聽曉耕者，與師知苦勞。"]', '["江房無葉落，松影带山高。","满寺中秋月，孤窗入夜濤。","旧真懸石壁，衰髮落銅刀。","臥听晓耕者，與師知苦勞。"]', '诗', 'shi', '', NULL, '秋宿經上人房 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a45b118-e85d-4ce0-add0-278bcd03e410', '冬日題覺公牛頭蘭若', '冬日題覺公牛头蘭若', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["天寒高木靜，一磬隔川聞。","鼎水看山汲，臺香埽雪焚。","鶴歸惟認剎，僧步不離雲。","石室開禪後，輪珠謝聖君。"]', '["天寒高木静，一磬隔川闻。","鼎水看山汲，台香埽雪焚。","鹤归惟認剎，僧步不離云。","石室开禪後，輪珠謝聖君。"]', '诗', 'shi', '', NULL, '冬日題覺公牛頭蘭若 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8d06c55-e532-4ffe-9b70-a9dcdaf4a26a', '送皇甫校書自蜀下峽歸覲襄陽', '送皇甫校书自蜀下峽归覲襄陽', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["蜀道波不竭，巢烏出浪痕。","松陰蓋巫峽，雨色徹荆門。","宿寺青山盡，歸林綵服翻。","苦吟懷凍餒，爲弔浩然魂。"]', '["蜀道波不竭，巢烏出浪痕。","松陰蓋巫峽，雨色徹荆门。","宿寺青山尽，归林綵服翻。","苦吟懷凍餒，爲弔浩然魂。"]', '诗', 'shi', '', NULL, '送皇甫校書自蜀下峽歸覲襄陽 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28e73374-417f-47d0-b8c8-f3b625bacdac', '題西明寺攻文僧林復上人房', '題西明寺攻文僧林复上人房', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["誰寄湘南信，陰窗硯起津。","燒痕碑入集，海角寺留真。","樓憩長空鳥，鐘驚半闕人。","御溝圓月會，似在草堂身。"]', '["誰寄湘南信，陰窗硯起津。","燒痕碑入集，海角寺留真。","楼憩长空鸟，鐘驚半闕人。","御溝圓月會，似在草堂身。"]', '诗', 'shi', '', NULL, '題西明寺攻文僧林復上人房 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be9ade49-49c4-45d9-9de9-3108b177d077', '寄翠微無可上人', '寄翠微無可上人', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["遠近衆心歸，居然占翠微。","展經猿識字，聽法虎知非。","泉注城池夢，霞生侍衛衣。","玄機不可學，何似總無機。"]', '["远近衆心归，居然占翠微。","展經猿識字，听法虎知非。","泉注城池梦，霞生侍衛衣。","玄機不可学，何似總無機。"]', '诗', 'shi', '', NULL, '寄翠微無可上人 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6273b28e-8b6c-4b08-9302-885586d9ba97', '喜鸞公自蜀歸', '喜鸾公自蜀归', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["禁院對生臺，尋師到綠槐。","寺高猿看講，鐘動鳥知齋。","埽石月盈箒，濾泉花滿篩。","歸來逢聖節，吟步上堯階。"]', '["禁院对生台，尋師到綠槐。","寺高猿看講，鐘动鸟知斋。","埽石月盈箒，濾泉花满篩。","归来逢聖節，吟步上堯階。"]', '诗', 'shi', '', NULL, '喜鸞公自蜀歸 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13d229d0-4297-4936-bf0a-bb367ad0ddc9', '題新安國寺', '題新安国寺', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["佛亦遇艱難，重興疊廢壇。","偃松枝舊折，畫竹粉新乾。","開講宮娃聽，拋生禁鳥餐。","鐘聲入帝夢，天竺化長安。"]', '["佛亦遇艱难，重兴叠廢壇。","偃松枝旧折，畫竹粉新乾。","开講宮娃听，拋生禁鸟餐。","鐘声入帝梦，天竺化长安。"]', '诗', 'shi', '', NULL, '題新安國寺 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ef9d355-5660-432b-8830-15a93ceaeccf', '蕃寇侵逼南歸道中', '蕃寇侵逼南归道中', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["雲州三萬騎，南走疾飛鷹。","迴磧星低雁，孤城月伴僧。","敲關通漢節，傾府守河冰。","無處論邊事，歸溪夜結罾。"]', '["云州三万騎，南走疾飞鷹。","迴磧星低雁，孤城月伴僧。","敲关通漢節，傾府守河冰。","無处論邊事，归溪夜結罾。"]', '诗', 'shi', '', NULL, '蕃寇侵逼南歸道中 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2f44a78-837b-4c98-b408-ae2b4d390986', '送東宮賈正字之蜀', '送东宮賈正字之蜀', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["南朝獻晉史，東蜀瞰巴樓。","長棧懷宮樹，疎峰露劒州。","半空飛雪化，一道白雲流。","若次江邊邑，宗詩爲徧搜。"]', '["南朝獻晉史，东蜀瞰巴楼。","长棧懷宮樹，疎峰露劒州。","半空飞雪化，一道白云流。","若次江邊邑，宗诗爲徧搜。"]', '诗', 'shi', '', NULL, '送東宮賈正字之蜀 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7677e92d-b452-4be4-b832-f1955446dd23', '弔侯圭常侍', '弔侯圭常侍', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["我重君能賦，君褒我解詩。","三堂一拜遇，四海兩心知。","影挂僧挑燭，名傳鶴拂碑。","涪江弔孤塚，片月下峨嵋。"]', '["我重君能賦，君褒我解诗。","三堂一拜遇，四海兩心知。","影挂僧挑燭，名傳鹤拂碑。","涪江弔孤塚，片月下峨嵋。"]', '诗', 'shi', '', NULL, '弔侯圭常侍 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1173c565-dccf-4130-af5d-d3cf435e1950', '顏上人房', '顏上人房', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["御溝臨岸行，遠岫見雲生。","松下度三伏，磬中銷五更。","雨淋經閣白，日閃剃刀明。","海畔終須去，燒燈老國清。"]', '["御溝臨岸行，远岫见云生。","松下度三伏，磬中銷五更。","雨淋經閣白，日閃剃刀明。","海畔終須去，燒灯老国清。"]', '诗', 'shi', '', NULL, '顏上人房 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d497fa6-0750-471d-b66a-25ecffb4931f', '題薛少府莊', '題薛少府莊', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["何須鑿井飲，門占古溪居。","寂寞苔牀臥，寒虛玉柄書。","有期登白閣，又得賞紅蕖。","清淺蒲根水，時看鷺啄魚。"]', '["何須鑿井饮，门占古溪居。","寂寞苔牀臥，寒虛玉柄书。","有期登白閣，又得賞紅蕖。","清淺蒲根水，时看鷺啄鱼。"]', '诗', 'shi', '', NULL, '題薛少府莊 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c180b32-7be1-49fa-b26e-fc184487b4e5', '寄太白隱者', '寄太白隐者', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["開闢已來雪，爲山長欠春。","高遮辭磧雁，寒噤入川人。","棧閣交冰柱，耕樵隔日輪。","此中棲息者，不識兩京塵。"]', '["开闢已来雪，爲山长欠春。","高遮辞磧雁，寒噤入川人。","棧閣交冰柱，耕樵隔日輪。","此中棲息者，不識兩京塵。"]', '诗', 'shi', '', NULL, '寄太白隱者 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('070c44d2-e6e2-4040-83c2-5f6c18123917', '秋宿青龍禪閣', '秋宿青龙禪閣', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["前山不可望，暮色漸沉規。","日轉須彌北，蟾來渤海西。","風鈴亂僧語，霜枿欠猿啼。","閣外千家月，分明見裏迷。"]', '["前山不可望，暮色漸沉規。","日轉須彌北，蟾来渤海西。","风鈴亂僧語，霜枿欠猿啼。","閣外千家月，分明见裏迷。"]', '诗', 'shi', '', NULL, '秋宿青龍禪閣 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61df8469-edba-4292-852e-8d743861e055', '登圭峰舊隱寄薦福棲白上人', '登圭峰旧隐寄薦福棲白上人', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["返照塔輪邊，殘霖滴幾懸。","夜寒吟病甚，秋健講聲圓。","粟穗乾燈焰，苔根濁水泉。","西峰埋蘚石，秋月即師禪。"]', '["返照塔輪邊，殘霖滴幾懸。","夜寒吟病甚，秋健講声圓。","粟穗乾灯焰，苔根濁水泉。","西峰埋蘚石，秋月即師禪。"]', '诗', 'shi', '', NULL, '登圭峰舊隱寄薦福棲白上人 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b827bdb6-d44d-485f-8f39-7d7e6bb1384b', '將之蜀別友人', '將之蜀別友人', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["嘉陵雨色青，澹別酌參苓。","到蜀高諸嶽，窺天合四溟。","書來應隔雪，夢覺已無星。","若遇多吟友，何妨勘竺經。"]', '["嘉陵雨色青，澹別酌參苓。","到蜀高諸嶽，窺天合四溟。","书来應隔雪，梦覺已無星。","若遇多吟友，何妨勘竺經。"]', '诗', 'shi', '', NULL, '將之蜀別友人 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aaaf4ca3-6213-4e85-833e-ae6758078cd1', '弔膳曹從叔郎中', '弔膳曹從叔郎中', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["華省支殘俸，寒蔬辦祭稀。","安墳對白閣，買石折朱衣。","蜀客彈琴哭，江鷗入宅飛。","帆吹佳句遠，不獨徧王畿。"]', '["华省支殘俸，寒蔬辦祭稀。","安墳对白閣，買石折朱衣。","蜀客彈琴哭，江鷗入宅飞。","帆吹佳句远，不独徧王畿。"]', '诗', 'shi', '', NULL, '弔膳曹從叔郎中 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('766f02dc-0b86-4d47-8575-1ba6c4f0c0a5', '亂後龍州送鄭郎中兼寄鄭侍御', '亂後龙州送鄭郎中兼寄鄭侍御', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["待車登疊嶂，經亂集鴒原。","省壞蘭終潔，臺寒栢有根。","縣清江入峽，樓靜雪連村。","莫隱匡山社，機雲受晉恩。"]', '["待车登叠嶂，經亂集鴒原。","省壞蘭終潔，台寒栢有根。","縣清江入峽，楼静雪連村。","莫隐匡山社，機云受晉恩。"]', '诗', 'shi', '', NULL, '亂後龍州送鄭郎中兼寄鄭侍御 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e75e0fc-0852-401a-9f09-4365e037e481', '段秀才溪居送從弟遊涇隴', '段秀才溪居送從弟游涇隴', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["抱疾寒溪臥，因循草木青。","相留開夏蜜，辭去見秋螢。","朔雪痕侵雍，邊烽焰照涇。","煙沈隴山色，西望涕交零。"]', '["抱疾寒溪臥，因循草木青。","相留开夏蜜，辞去见秋螢。","朔雪痕侵雍，邊烽焰照涇。","煙沈隴山色，西望涕交零。"]', '诗', 'shi', '', NULL, '段秀才溪居送從弟遊涇隴 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dff982ae-5bd7-437a-868d-02accbf13d5f', '題劉相公光德里新搆茅亭', '題劉相公光德里新搆茅亭', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["野色迷亭曉，龍墀待押班。","帶涎移海木，兼雪寫湖山。","月白吟牀冷，河清直印閑。","唐封三萬里，人偃翠微間。"]', '["野色迷亭晓，龙墀待押班。","带涎移海木，兼雪寫湖山。","月白吟牀冷，河清直印闲。","唐封三万里，人偃翠微间。"]', '诗', 'shi', '', NULL, '題劉相公光德里新搆茅亭 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b84c0775-9833-4cdb-b343-72ffcf86a65d', '江峽寇亂寄懷吟僧', '江峽寇亂寄懷吟僧', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["半錫探寒流，別師猿鶴洲。","二三更後雨，四十字邊秋。","立塞吟霞石，敲鼙看雪樓。","扶親何處隱，驚夢入嵩丘。"]', '["半錫探寒流，別師猿鹤洲。","二三更後雨，四十字邊秋。","立塞吟霞石，敲鼙看雪楼。","扶親何处隐，驚梦入嵩丘。"]', '诗', 'shi', '', NULL, '江峽寇亂寄懷吟僧 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cd02cdc-e770-4791-ba47-6c81e32d600e', '賀昭國從叔員外轉本曹郎中', '賀昭国從叔員外轉本曹郎中', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["苔砌塔陰濃，朝回尚叫蛬。","粟徴山縣欠，官轉水曹重。","燈照樓中雨，書求海上峰。","詩家無驟顯，一一古人蹤。"]', '["苔砌塔陰濃，朝回尚叫蛬。","粟徴山縣欠，官轉水曹重。","灯照楼中雨，书求海上峰。","诗家無驟显，一一古人蹤。"]', '诗', 'shi', '', NULL, '賀昭國從叔員外轉本曹郎中 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b34d928-9b89-4465-8381-77ba57d561a1', '贈宋校書', '贈宋校书', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["曾伴元戎獵，寒來夢北軍。","閑身不計日，病鶴放歸[雲]。","石上鋪碁勢，船中賭酒分。","長言買天姥，高臥謝人羣。"]', '["曾伴元戎獵，寒来梦北軍。","闲身不計日，病鹤放归[云]。","石上鋪碁勢，船中賭酒分。","长言買天姥，高臥謝人羣。"]', '诗', 'shi', '', NULL, '贈宋校書 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0b8de07-28a5-44c2-8fb1-a70c701ba2a0', '越公上人洛中歸寄南孟家兄弟', '越公上人洛中归寄南孟家兄弟', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["洛下因歸去，官西憶二龍。","笠漫河岸雪，衣着虢城鍾。","睡鴨浮寒水，樵人出遠峰。","賀當化閭俗，護取草堂松。"]', '["洛下因归去，官西憶二龙。","笠漫河岸雪，衣着虢城鍾。","睡鴨浮寒水，樵人出远峰。","賀當化閭俗，護取草堂松。"]', '诗', 'shi', '', NULL, '越公上人洛中歸寄南孟家兄弟 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a58cbe0-fba9-40a3-a18e-061ca501090b', '龍州送裴秀才', '龙州送裴秀才', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["違拜斾旗前，松陰路半千。","樓衝高雪會，驛閉亂雲眠。","牓挂臨江省，名題赴宅筵。","人求新蜀賦，應貴浣花牋。"]', '["違拜斾旗前，松陰路半千。","楼衝高雪會，驛閉亂云眠。","牓挂臨江省，名題赴宅筵。","人求新蜀賦，應貴浣花牋。"]', '诗', 'shi', '', NULL, '龍州送裴秀才 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37cfad11-da30-423f-9224-6c221edf8cf7', '題慈恩友人房', '題慈恩友人房', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["賈生耽此寺，勝事入詩多。","鶴宿星千樹，僧歸燒一坡。","塔稜垂雪水，江色暎茶鍋。","長久堪棲息，休言憶鏡波。"]', '["賈生耽此寺，勝事入诗多。","鹤宿星千樹，僧归燒一坡。","塔稜垂雪水，江色暎茶鍋。","长久堪棲息，休言憶镜波。"]', '诗', 'shi', '', NULL, '題慈恩友人房 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a805bb5-b15f-4ea5-aa59-b2b16557c22d', '寄竇禪山薛秀才', '寄竇禪山薛秀才', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["竇嶺吟招隱，新詩滿集賢。","白衫春絮暖，紅紙夏雲鮮。","琴纏江絲細，棊分海石圓。","因知醉公子，虛寫世人傳。"]', '["竇嶺吟招隐，新诗满集賢。","白衫春絮暖，紅紙夏云鲜。","琴纏江絲細，棊分海石圓。","因知醉公子，虛寫世人傳。"]', '诗', 'shi', '', NULL, '寄竇禪山薛秀才 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9d564dd-0a6a-423e-b98d-3fd45bea0193', '西蜀與崔先生話東洛舊遊', '西蜀與崔先生話东洛旧游', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["王屋峭難名，三刀夢四更。","日升當地缺，星盡未天明。","度雪雲林濕，穿松角韻清。","崔家開錦浪，憶着水窗聲。"]', '["王屋峭难名，三刀梦四更。","日升當地缺，星尽未天明。","度雪云林濕，穿松角韻清。","崔家开錦浪，憶着水窗声。"]', '诗', 'shi', '', NULL, '西蜀與崔先生話東洛舊遊 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4dda8e3-7ac1-462e-ab9e-4593596eecc2', '上昭國水部從叔郎中', '上昭国水部從叔郎中', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["極南極北游，東汎復西流。","行匝中華地，魂銷四海秋。","題詩在瓊府，附舶出青州。","不遇一公子，彈琴弔古丘。"]', '["極南極北游，东汎复西流。","行匝中华地，魂銷四海秋。","題诗在瓊府，附舶出青州。","不遇一公子，彈琴弔古丘。"]', '诗', 'shi', '', NULL, '上昭國水部從叔郎中 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b37e3f31-0c0c-478f-aaba-c943468ba8ab', '題玉芝趙尊師院', '題玉芝趙尊師院', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["曉起磬房前，真經誦百篇。","漱流星入齒，照鏡石差肩。","靜閉街西觀，存思海上仙。","閑聽說五嶽，窮徧一根蓮。"]', '["晓起磬房前，真經誦百篇。","漱流星入齒，照镜石差肩。","静閉街西观，存思海上仙。","闲听说五嶽，窮徧一根蓮。"]', '诗', 'shi', '', NULL, '題玉芝趙尊師院 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05a2426e-5d9f-4885-9377-136bcea01baa', '送盧少府之任鞏洛', '送盧少府之任鞏洛', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["從知東甸尉，銓注似恩除。","帶土移嵩朮，和泉送尹魚。","印牀寒鷺宿，壁記醉僧書。","堂下諸昆在，無妨候起居。"]', '["從知东甸尉，銓注似恩除。","带土移嵩朮，和泉送尹鱼。","印牀寒鷺宿，壁記醉僧书。","堂下諸昆在，無妨候起居。"]', '诗', 'shi', '', NULL, '送盧少府之任鞏洛 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('196421be-d298-4d04-9a42-4fee18aa0bf5', '送人歸覲河中', '送人归覲河中', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["青門塚前別，道路武關西。","有寺雲連石，無僧葉滿溪。","河長隨鳥盡，山遠與人齊。","覲省波濤縣，寒窗響曙雞。"]', '["青门塚前別，道路武关西。","有寺云連石，無僧葉满溪。","河长隨鸟尽，山远與人齊。","覲省波濤縣，寒窗响曙雞。"]', '诗', 'shi', '', NULL, '送人歸覲河中 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49ecf9e9-21e3-43cc-9ba1-bc6ecdc511cc', '錦城秋寄懷弘播上人', '錦城秋寄懷弘播上人', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["極頂雲兼凍，孤城露洗初。","共辭嵩少雪，久絕貝多書。","遠照雁行細，寒條狖挂虛。","分泉煎月色，憶就茗林居。"]', '["極頂云兼凍，孤城露洗初。","共辞嵩少雪，久絕貝多书。","远照雁行細，寒條狖挂虛。","分泉煎月色，憶就茗林居。"]', '诗', 'shi', '', NULL, '錦城秋寄懷弘播上人 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c0c647e-a20a-4e77-8cd5-cde9dcb5ad0a', '圭峰溪居寄懷韋曲曹秀才', '圭峰溪居寄懷韋曲曹秀才', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["南北飛山雪，萬片寄相思。","東西曲流水，千聲瀉別離。","巴猿學導引，隴鳥解吟詩。","翻羨家林賞，世人那得知。"]', '["南北飞山雪，万片寄相思。","东西曲流水，千声瀉別離。","巴猿学導引，隴鸟解吟诗。","翻羨家林賞，世人那得知。"]', '诗', 'shi', '', NULL, '圭峰溪居寄懷韋曲曹秀才 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed485855-5eae-4ebd-8ea4-33bfbb77161a', '送舍弟之山南', '送舍弟之山南', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["南山入谷遊，去徹山南州。","下馬雲未盡，聽猿星正稠。","印茶泉遶石，封國角吹樓。","遠宦有何興，貧兄無計留。"]', '["南山入谷游，去徹山南州。","下马云未尽，听猿星正稠。","印茶泉遶石，封国角吹楼。","远宦有何兴，貧兄無計留。"]', '诗', 'shi', '', NULL, '送舍弟之山南 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('821466f3-94f7-4479-9bab-43ed2e50618a', '題南鑒公山房', '題南鑒公山房', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["竹房開處峭，迥挂半山燈。","石磬敲來穴，不知何代僧。","講歸雙袖雪，禪起一盂冰。","唯說黃桑屐，當時着秣陵。"]', '["竹房开处峭，迥挂半山灯。","石磬敲来穴，不知何代僧。","講归雙袖雪，禪起一盂冰。","唯说黄桑屐，當时着秣陵。"]', '诗', 'shi', '', NULL, '題南鑒公山房 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e245793-b89f-4f6c-af9b-e4ebae04d43b', '送知己', '送知己', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["郡清官舍冷，枕席濺山泉。","藥氣來人外，燈光到鶴邊。","夢秦書印斗，思越畫漁船。","擲笏南歸去，波濤路幾千。"]', '["郡清官舍冷，枕席濺山泉。","藥氣来人外，灯光到鹤邊。","梦秦书印斗，思越畫漁船。","擲笏南归去，波濤路幾千。"]', '诗', 'shi', '', NULL, '送知己 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b34a812-5f3e-491d-a5c0-afb8c1a056e3', '送人赴職湘潭', '送人赴職湘潭', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["南征雖赴辟，其奈負高科。","水合湘潭住，山分越國多。","梅花雪共下，文□□相和。","白髮陪官宴，紅旗影裏歌。"]', '["南征雖赴辟，其奈負高科。","水合湘潭住，山分越国多。","梅花雪共下，文□□相和。","白髮陪官宴，紅旗影裏歌。"]', '诗', 'shi', '', NULL, '送人赴職湘潭 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0d33584-1e67-430c-81be-254464c30f9b', '過野叟居', '過野叟居', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["野人居止處，竹色與山光。","留客羞蔬飯，灑泉開草堂。","雨餘松子落，風過朮苗香。","盡日無炎暑，眠君青石牀。"]', '["野人居止处，竹色與山光。","留客羞蔬飯，灑泉开草堂。","雨餘松子落，风過朮苗香。","尽日無炎暑，眠君青石牀。"]', '诗', 'shi', '', NULL, '過野叟居 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8224cdc5-7b60-453b-91df-39acf303ef5f', '弔鄭賓客', '弔鄭賓客', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["朝行喪名節，嶽色慘天風。","待漏秋吟斷，焚香夜直空。","骨寒依壠草，家盡逐邊鴻。","一弔知音後，歸來碎嶧桐。"]', '["朝行喪名節，嶽色慘天风。","待漏秋吟斷，焚香夜直空。","骨寒依壠草，家尽逐邊鴻。","一弔知音後，归来碎嶧桐。"]', '诗', 'shi', '', NULL, '弔鄭賓客 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d407782-78ed-452d-86b6-868500553a1f', '送從叔書記山陰隱居', '送從叔书記山陰隐居', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["山頂絕茅居，雲泉遶枕虛。","燒移僧影瘦，風展鷺行疎。","卷箔清江月，敲松紫閣書。","由來簪組貴，不信教猿鋤。"]', '["山頂絕茅居，云泉遶枕虛。","燒移僧影瘦，风展鷺行疎。","卷箔清江月，敲松紫閣书。","由来簪組貴，不信教猿鋤。"]', '诗', 'shi', '', NULL, '送從叔書記山陰隱居 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71761812-4214-4b3c-ada0-9a14e823b1ef', '避暑莊嚴禪院', '避暑莊嚴禪院', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["定裏無煩熱，吟中達性情。","入林逢客話，上塔接僧行。","八水皆知味，諸翁盡得名。","常論冰井近，莫便厭浮生。"]', '["定裏無煩熱，吟中達性情。","入林逢客話，上塔接僧行。","八水皆知味，諸翁尽得名。","常論冰井近，莫便厭浮生。"]', '诗', 'shi', '', NULL, '避暑莊嚴禪院 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7022a1b5-a280-47d9-a8ff-b1516c7bad5a', '寄清演', '寄清演', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["忽聞清演病，可料苦吟身。","不見近詩久，徒言華髮新。","別來山已破，住處月爲鄰。","幾遶庭前樹，于今四十春。"]', '["忽闻清演病，可料苦吟身。","不见近诗久，徒言华髮新。","別来山已破，住处月爲鄰。","幾遶庭前樹，于今四十春。"]', '诗', 'shi', '', NULL, '寄清演 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9097e41b-17a5-4c09-b333-9b151c31dec8', '遷村居二首 一', '遷村居二首 一', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["移居入村宇，樹闕見城隍。","雲水雖堪畫，恩私不可忘。","猿涎滴鶴氅，麈尾拂僧牀。","棄逐隨樵牧，何由報稻粱。"]', '["移居入村宇，樹闕见城隍。","云水雖堪畫，恩私不可忘。","猿涎滴鹤氅，麈尾拂僧牀。","棄逐隨樵牧，何由報稻粱。"]', '诗', 'shi', '', NULL, '遷村居二首 一 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a6939fb-2fee-4449-b77c-92a68aa8a848', '遷村居二首 二', '遷村居二首 二', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["歌樂聽常稀，茅亭靜掩扉。","槎來垂釣次，月落問安歸。","遠客傳燒研，幽禽看衲衣。","眼前無俗事，松雨蜀山輝。"]', '["歌乐听常稀，茅亭静掩扉。","槎来垂釣次，月落问安归。","远客傳燒研，幽禽看衲衣。","眼前無俗事，松雨蜀山輝。"]', '诗', 'shi', '', NULL, '遷村居二首 二 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('faadd68b-ac78-4c56-a848-b81d2ef186e4', '出山覩春牓', '出山覩春牓', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["未老鬢毛焦，心歸向石橋。","指霞辭二紀，吟雪遇三朝。","連席頻登相，分廊尚祝堯。","迴眸舊行侶，免使負嵩樵。"]', '["未老鬢毛焦，心归向石橋。","指霞辞二紀，吟雪遇三朝。","連席頻登相，分廊尚祝堯。","迴眸旧行侶，免使負嵩樵。"]', '诗', 'shi', '', NULL, '出山覩春牓 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('716ef179-df7b-43dd-84f5-c94c2eef8350', '賈島墓', '賈島墓', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["一第人皆得，先生豈不銷。","位卑終蜀士，詩絕占唐朝。","旅葬新墳小，魂歸故國遙。","我來因奠灑，立石用爲標。"]', '["一第人皆得，先生豈不銷。","位卑終蜀士，诗絕占唐朝。","旅葬新墳小，魂归故国遙。","我来因奠灑，立石用爲標。"]', '诗', 'shi', '', NULL, '賈島墓 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3ac6a86-084d-41b6-9da2-008ddffddc02', '觀水墨障子', '观水墨障子', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["若非神助筆，硯水恐藏龍。","研盡一寸墨，埽成千仞峰。","壁根堆亂石，牀罅插枯松。","嶽麓穿因鼠，湘江綻爲蛬。","挂衣嵐氣濕，夢枕浪頭舂。","只爲少顏色，時人著意慵。"]', '["若非神助笔，硯水恐藏龙。","研尽一寸墨，埽成千仞峰。","壁根堆亂石，牀罅插枯松。","嶽麓穿因鼠，湘江綻爲蛬。","挂衣嵐氣濕，梦枕浪头舂。","只爲少顏色，时人著意慵。"]', '诗', 'shi', '', NULL, '觀水墨障子 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('495f3de9-f8db-4adf-8d96-e063aa4b1183', '對棊', '对棊', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["小檻明高雪，幽人鬬智棊。","日斜拋作劫，月午蹙成遲。","倚杖湘僧筭，翹松野鶴窺。","側楸敲醒睡，片石夾吟詩。","雨點匳中漬，燈花局上吹。","秋濤寒竹寺，此興謝公知。"]', '["小檻明高雪，幽人鬬智棊。","日斜拋作劫，月午蹙成遲。","倚杖湘僧筭，翹松野鹤窺。","側楸敲醒睡，片石夾吟诗。","雨点匳中漬，灯花局上吹。","秋濤寒竹寺，此兴謝公知。"]', '诗', 'shi', '', NULL, '對棊 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4259dda-feda-45e3-ae62-a291f46b45e4', '題竹溪禪院', '題竹溪禪院', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["溪邊山一色，水擁竹千竿。","鳥觸翠微濕，人居酷暑寒。","風搖缾影碎，沙陷履痕端。","爽極青崖樹，平流綠峽灘。","閑來披衲數，漲後卷經看。","三境通禪寂，囂塵染著難。"]', '["溪邊山一色，水擁竹千竿。","鸟觸翠微濕，人居酷暑寒。","风搖缾影碎，沙陷履痕端。","爽極青崖樹，平流綠峽灘。","闲来披衲數，漲後卷經看。","三境通禪寂，囂塵染著难。"]', '诗', 'shi', '', NULL, '題竹溪禪院 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7408843f-9a6a-4493-9cf9-6a5ad62727cf', '投獻吏部張侍郎十韻', '投獻吏部張侍郎十韻', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["苔染馬蹄青，何曾似在城。","不於僧院宿，多傍御溝行。","隱岫侵巴疊，租田帶渭平。","肩囊尋省寺，袖軸徧公卿。","夢入連濤郡，書來積雪營。","淚隨邊雁墮，魂逐夜蟬驚。","發憤巡江塔，無眠數縣更。","玄都一病客，興善幾回鶯。","貢藝披沙細，酬恩戴嶽輕。","心期公子念，滴酒在雕楹。"]', '["苔染马蹄青，何曾似在城。","不於僧院宿，多傍御溝行。","隐岫侵巴叠，租田带渭平。","肩囊尋省寺，袖軸徧公卿。","梦入連濤郡，书来積雪營。","泪隨邊雁墮，魂逐夜蟬驚。","發憤巡江塔，無眠數縣更。","玄都一病客，兴善幾回鶯。","貢藝披沙細，酬恩戴嶽轻。","心期公子念，滴酒在雕楹。"]', '诗', 'shi', '', NULL, '投獻吏部張侍郎十韻 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89ae4258-c461-4233-a056-15791abd415a', '終南山二十韻', '終南山二十韻', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["關內平田窄，東西截杳冥。","雨侵諸縣黑，雲破九門青。","暫看猶無暇，長棲信有靈。","古苔秋漬斗，積霧夜昏螢。","怒恐撞天漏，深疑隱地形。","盤根連北嶽，轉影落南溟。","窮穴何山出，遮蠻上國寧。","殘陽高照蜀，敗葉遠浮涇。","斸竹煙嵐凍，偷湫雨雹腥。","閑房僧灌頂，浴澗鶴遺翎。","梯滑危緣索，雲深靜唱經。","放泉驚鹿睡，聞磬得人醒。","踏著神仙宅，敲開洞府扃。","棊殘秦士局，字缺晉公銘。","一谷勢當午，孤峰聳起丁。","遠平丹鳳闕，冷射五侯廳。","萬丈冰聲折，千尋樹影停。","望中仙島動，行處月輪馨。","疊石移臨砌，研膠潑上屏。","明時獻君壽，不假老人星。"]', '["关內平田窄，东西截杳冥。","雨侵諸縣黑，云破九门青。","暫看猶無暇，长棲信有靈。","古苔秋漬斗，積霧夜昏螢。","怒恐撞天漏，深疑隐地形。","盤根連北嶽，轉影落南溟。","窮穴何山出，遮蠻上国寧。","殘陽高照蜀，敗葉远浮涇。","斸竹煙嵐凍，偷湫雨雹腥。","闲房僧灌頂，浴澗鹤遺翎。","梯滑危緣索，云深静唱經。","放泉驚鹿睡，闻磬得人醒。","踏著神仙宅，敲开洞府扃。","棊殘秦士局，字缺晉公銘。","一谷勢當午，孤峰聳起丁。","远平丹鳳闕，冷射五侯廳。","万丈冰声折，千尋樹影停。","望中仙島动，行处月輪馨。","叠石移臨砌，研膠潑上屏。","明时獻君壽，不假老人星。"]', '诗', 'shi', '', NULL, '終南山二十韻 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('216c4a17-acf7-4d0e-ab84-84390a7a84fc', '秋日同覺公上人眺慈恩塔六韻', '秋日同覺公上人眺慈恩塔六韻', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["九級聳蓮宮，晴登袖拂虹。","房廊窺井底，世界出籠中。","照牖三山火，吹鈴八極風。","細聞槎客語，遙辨海魚沖。","禁靜聲連北，江寒影在東。","謁師開秘鎖，塵日閉虛空。"]', '["九級聳蓮宮，晴登袖拂虹。","房廊窺井底，世界出籠中。","照牖三山火，吹鈴八極风。","細闻槎客語，遙辨海鱼沖。","禁静声連北，江寒影在东。","謁師开秘鎖，塵日閉虛空。"]', '诗', 'shi', '', NULL, '秋日同覺公上人眺慈恩塔六韻 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d9e6808-2ce1-426f-ba0c-ad22b0c403db', '感知上刑部鄭侍郎', '感知上刑部鄭侍郎', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["寄掩白雲司，蜀都高臥時。","鄰僧照寒竹，宿鳥動秋池。","帝誦嘉蓮表，人吟寶劒詩。","石渠流月斷，畫角截江吹。","閑出黃金勒，前飛白鷺鶿。","公心外國說，重望兩朝推。","靜蘚斜圭影，孤窗響錫枝。","興幽松雪見，心苦硯冰知。","緣杖蟲聲切，過門馬足遲。","漏殘終卷讀，日下大名垂。","平磧容鵰上，仙山許狖窺。","數聯金口出，死免愧丘爲。"]', '["寄掩白云司，蜀都高臥时。","鄰僧照寒竹，宿鸟动秋池。","帝誦嘉蓮表，人吟寶劒诗。","石渠流月斷，畫角截江吹。","闲出黄金勒，前飞白鷺鶿。","公心外国说，重望兩朝推。","静蘚斜圭影，孤窗响錫枝。","兴幽松雪见，心苦硯冰知。","緣杖蟲声切，過门马足遲。","漏殘終卷读，日下大名垂。","平磧容鵰上，仙山許狖窺。","數聯金口出，死免愧丘爲。"]', '诗', 'shi', '', NULL, '感知上刑部鄭侍郎 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f84a4f0-2c45-4e99-85a9-dcb7eb6ffcad', '敘事寄薦福栖白', '敘事寄薦福栖白', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["險倚石屏風，秋濤夢越中。","前朝吟會散，故國講流終。","北地聞巴狖，南山見磧鴻。","樓高驚雨闊，木落覺城空。","兔滿期姚監，蟬稀別楚公。","淨缾光照客，拄杖朽生蟲。","平地塔千尺，半空燈一籠。","祝堯談幾句，旋瀉海濤東。"]', '["險倚石屏风，秋濤梦越中。","前朝吟會散，故国講流終。","北地闻巴狖，南山见磧鴻。","楼高驚雨闊，木落覺城空。","兔满期姚監，蟬稀別楚公。","淨缾光照客，拄杖朽生蟲。","平地塔千尺，半空灯一籠。","祝堯談幾句，旋瀉海濤东。"]', '诗', 'shi', '', NULL, '敘事寄薦福栖白 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16056a74-0783-4a8a-a0bb-7f1ae4b63231', '送龍州田使君舊詩家', '送龙州田使君旧诗家', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["御札軫西陲，龍州出牧時。","度關雲作雪，挂棧水成澌。","劒淬號猿岸，弓懸宿鶴枝。","江燈混星斗，山木亂槍旗。","鎖庫休秤藥，開樓又見詩。","無心陪宴集，吟苦憶京師。"]', '["御札軫西陲，龙州出牧时。","度关云作雪，挂棧水成澌。","劒淬號猿岸，弓懸宿鹤枝。","江灯混星斗，山木亂槍旗。","鎖庫休秤藥，开楼又见诗。","無心陪宴集，吟苦憶京師。"]', '诗', 'shi', '', NULL, '送龍州田使君舊詩家 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b14afa9-99b9-4d28-a344-f5278fd4de26', '和知己赴任華州', '和知己赴任华州', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["東門罷相郡，此拜動京華。","落日開宵印，初燈見早麻。","鶴身紅斾拂，仙掌白雲遮。","塞色侵三縣，河聲聒兩衙。","松根醒客酒，蓮座隱僧家。","一道帆飛直，中筵嶽影斜。","書名尋雪石，澄鼎露金沙。","鎖合眠關吏，杯寒啄廟鴉。","分臺話嵩洛，賽雨戀煙霞。","樹谷期招隱，吟詩煮栢茶。"]', '["东门罷相郡，此拜动京华。","落日开宵印，初灯见早麻。","鹤身紅斾拂，仙掌白云遮。","塞色侵三縣，河声聒兩衙。","松根醒客酒，蓮座隐僧家。","一道帆飞直，中筵嶽影斜。","书名尋雪石，澄鼎露金沙。","鎖合眠关吏，杯寒啄廟鴉。","分台話嵩洛，賽雨戀煙霞。","樹谷期招隐，吟诗煮栢茶。"]', '诗', 'shi', '', NULL, '和知己赴任華州 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e6623bd-1282-4089-806f-990b5060dca5', '題咸陽樓', '題咸陽楼', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["晚亞古城門，憑高黯客魂。","塞侵秦舊國，河浸漢荒村。","客路颺書燼，人家帶水痕。","獵頻虛塚穴，耕苦露松根。","牆外峰黏漢，冰中日晃原。","斷碑移作砌，廣第灌成園。","北馬疑眠磧，南人憶釣湓。","橋閑野鹿過，街靜禁鴉翻。","灘鼓城隍動，雲衝太白昏。","標衣多呂裔，荷鍤或劉孫。","弔問難知主，登攀強滴罇。","不能扶壯勢，冠劒惜乾坤。"]', '["晚亞古城门，憑高黯客魂。","塞侵秦旧国，河浸漢荒村。","客路颺书燼，人家带水痕。","獵頻虛塚穴，耕苦露松根。","牆外峰黏漢，冰中日晃原。","斷碑移作砌，廣第灌成园。","北马疑眠磧，南人憶釣湓。","橋闲野鹿過，街静禁鴉翻。","灘鼓城隍动，云衝太白昏。","標衣多呂裔，荷鍤或劉孫。","弔问难知主，登攀強滴罇。","不能扶壯勢，冠劒惜乾坤。"]', '诗', 'shi', '', NULL, '題咸陽樓 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('825c52dd-8429-49ad-bfb8-c392320d4765', '贈興善徹公上人', '贈兴善徹公上人', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["師資懷劒外，徒步管街東。","九里山橫燒，三條木落風。","古池曾看鶴，新塔未吟蟲。","夜久龍髯冷，年多麈尾空。","心宗本無礙，問學豈難同。"]', '["師資懷劒外，徒步管街东。","九里山橫燒，三條木落风。","古池曾看鹤，新塔未吟蟲。","夜久龙髯冷，年多麈尾空。","心宗本無礙，问学豈难同。"]', '诗', 'shi', '', NULL, '贈興善徹公上人 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a48e607f-f9e9-414c-b9f8-ef456d4a0fa6', '龍池春草', '龙池春草', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["龍池清禁裏，芳草傍池春。","旋長方遮岸，全生不染塵。","和風輕動色，湛露靜流津。","淺得承天步，深疑遶御輪。","魚尋倒影沒，花帶濕光新。","肯學長河畔，綿綿思遠人。"]', '["龙池清禁裏，芳草傍池春。","旋长方遮岸，全生不染塵。","和风轻动色，湛露静流津。","淺得承天步，深疑遶御輪。","鱼尋倒影沒，花带濕光新。","肯学长河畔，綿綿思远人。"]', '诗', 'shi', '', NULL, '龍池春草 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6edb679-6cf8-406b-bc7a-83015607e0cd', '秋宿梓州牛頭寺', '秋宿梓州牛头寺', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["月去簷三尺，川雲入寺樓。","靈山頓離衆，列宿不多稠。","篆字焚初缺，翻經誦若流。","窗閑二江冷，簾卷半空秋。","詔散松梢別，棊終竹節收。","靜增雙闕念，高並五翁遊。","鶴夢生紅日，雲閑鎖梓州。","望空工部眼，搔亂廣文頭。","石室僧調馬，銀河客問牛。","曉樓歸下界，大地一浮漚。"]', '["月去簷三尺，川云入寺楼。","靈山頓離衆，列宿不多稠。","篆字焚初缺，翻經誦若流。","窗闲二江冷，簾卷半空秋。","詔散松梢別，棊終竹節收。","静增雙闕念，高並五翁游。","鹤梦生紅日，云闲鎖梓州。","望空工部眼，搔亂廣文头。","石室僧調马，銀河客问牛。","晓楼归下界，大地一浮漚。"]', '诗', 'shi', '', NULL, '秋宿梓州牛頭寺 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ace05bd-36ee-4de0-b802-33393cdea931', '送韋太尉自坤維除廣陵', '送韋太尉自坤維除廣陵', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["全蜀拜揚州，征東輟武侯。","直來萬里月，旁到五峰秋。","幢冷遮高雪，旗閑卓亂流。","謝朝明主喜，登省舊寮愁。","隔海城通舶，連河市響樓。","千官倚元老，虛夢法雲遊。"]', '["全蜀拜揚州，征东輟武侯。","直来万里月，旁到五峰秋。","幢冷遮高雪，旗闲卓亂流。","謝朝明主喜，登省旧寮愁。","隔海城通舶，連河市响楼。","千官倚元老，虛梦法云游。"]', '诗', 'shi', '', NULL, '送韋太尉自坤維除廣陵 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25ce9f0c-a1d0-4e39-bd2b-c4f5165cc5d1', '贈曹郎中崇賢所居', '贈曹郎中崇賢所居', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["閑坊宅枕穿宮水，聽水分衾蓋蜀繒。","藥杵聲中擣殘夢，茶鐺影裏煮孤燈。","刑曹樹蔭千年井，華嶽樓開萬仞冰。","詩句變風官漸緊，夜濤舂斷海邊藤。"]', '["闲坊宅枕穿宮水，听水分衾蓋蜀繒。","藥杵声中擣殘梦，茶鐺影裏煮孤灯。","刑曹樹蔭千年井，华嶽楼开万仞冰。","诗句变风官漸緊，夜濤舂斷海邊藤。"]', '诗', 'shi', '', NULL, '贈曹郎中崇賢所居 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbda892d-7948-48f7-8ffe-3e9414389a00', '贈昭應沈少府', '贈昭應沈少府', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["行宮接縣判雲泉，袍色雖青骨且仙。","鄠杜憶過梨栗墅，瀟湘曾棹雪霜天。","華山僧別留茶鼎，渭水人來鎖釣船。","東送西迎終幾考，新詩覓得兩三聯。"]', '["行宮接縣判云泉，袍色雖青骨且仙。","鄠杜憶過梨栗墅，瀟湘曾棹雪霜天。","华山僧別留茶鼎，渭水人来鎖釣船。","东送西迎終幾考，新诗覓得兩三聯。"]', '诗', 'shi', '', NULL, '贈昭應沈少府 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ed6b88f-5f36-488a-94e9-7bf067da6a56', '上司空員外', '上司空員外', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["禪心高臥似疎慵，詩客經過不厭重。","藤杖幾攜量磧雪，玉鞭曾把數嵩峰。","夜眠古巷當城月，秋直清曹入省鐘。","禹鑿故山歸未得，河聲暗老兩三松。"]', '["禪心高臥似疎慵，诗客經過不厭重。","藤杖幾携量磧雪，玉鞭曾把數嵩峰。","夜眠古巷當城月，秋直清曹入省鐘。","禹鑿故山归未得，河声暗老兩三松。"]', '诗', 'shi', '', NULL, '上司空員外 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28d46479-8ac0-44cf-befa-8d8c7ac61307', '敘舊遊寄栖白', '敘旧游寄栖白', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["老着重袍坐石房，竺經休講白眉長。","省衝鼉沒投江島，曾看魚飛倚海檣。","曉炙凍盂原日氣，夜挑蓮椀禁燈光。","吟詩五嶺尋無可，倏忽如今四十霜。"]', '["老着重袍坐石房，竺經休講白眉长。","省衝鼉沒投江島，曾看鱼飞倚海檣。","晓炙凍盂原日氣，夜挑蓮椀禁灯光。","吟诗五嶺尋無可，倏忽如今四十霜。"]', '诗', 'shi', '', NULL, '敘舊遊寄栖白 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1eeb7ca0-1fc0-4dfa-94ca-f496d5f3eab6', '哭栖白供奉', '哭栖白供奉', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["聞說孤窗坐化時，白莎蘿雨滴空池。","吟詩堂裏秋關影，禮佛燈前夜照碑。","賀雪已成金殿夢，看濤終負石橋期。","逢山對月還惆悵，爭得無言似祖師。"]', '["闻说孤窗坐化时，白莎蘿雨滴空池。","吟诗堂裏秋关影，禮佛灯前夜照碑。","賀雪已成金殿梦，看濤終負石橋期。","逢山对月還惆悵，爭得無言似祖師。"]', '诗', 'shi', '', NULL, '哭栖白供奉 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91082a1f-75d5-48ca-b617-9fcfbe53434c', '贈入內供奉僧', '贈入內供奉僧', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["內殿談經愜帝懷，沃州歸隱計全乖。","數條雀尾來南海，一道蟬聲噪御街。","石枕紋含山裏葉，銅缾口塞井中柴。","因逢夏日西明講，不覺宮人拔鳳釵。"]', '["內殿談經愜帝懷，沃州归隐計全乖。","數條雀尾来南海，一道蟬声噪御街。","石枕紋含山裏葉，銅缾口塞井中柴。","因逢夏日西明講，不覺宮人拔鳳釵。"]', '诗', 'shi', '', NULL, '贈入內供奉僧 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93b94e5a-79fe-4be1-ad71-75734f27c984', '感恩書事寄上集義司徒相公', '感恩书事寄上集義司徒相公', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["積雪峰西遇獎稱，半家寒骨起溝塍。","鎮時賢相回人鏡，報德慈親點佛燈。","授鉞已聞諸國靜，坐籌重見大河澄。","功居第一圖烟閣，依舊終南滿杜陵。"]', '["積雪峰西遇獎稱，半家寒骨起溝塍。","鎮时賢相回人镜，報德慈親点佛灯。","授鉞已闻諸国静，坐籌重见大河澄。","功居第一圖烟閣，依旧終南满杜陵。"]', '诗', 'shi', '', NULL, '感恩書事寄上集義司徒相公 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bdfd85c-9868-42a1-9e01-301eb9283f63', '贈永崇李將軍充襄陽制置使', '贈永崇李將軍充襄陽制置使', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["拜官門外發輝光，宿衛陰符注幾行。","行處近天龍尾滑，獵時陪帝馬鬃香。","九城王氣生旗隊，萬里寒風入箭瘡。","從此浩然聲價歇，武中還有李襄陽。"]', '["拜官门外發輝光，宿衛陰符注幾行。","行处近天龙尾滑，獵时陪帝马鬃香。","九城王氣生旗隊，万里寒风入箭瘡。","從此浩然声價歇，武中還有李襄陽。"]', '诗', 'shi', '', NULL, '贈永崇李將軍充襄陽制置使 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b5a02f7-f098-4c6a-bd23-7065bb9b627c', '寄淮海惠澤上人', '寄淮海惠澤上人', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["海濤痕滿舊征衣，長憶初程宿翠微。","竹裏橋鳴知馬過，塔中燈露見鴻飛。","眉毫別後應盈尺，嵒木居來定幾圍。","他日願師容一榻，煎茶埽地學忘機。"]', '["海濤痕满旧征衣，长憶初程宿翠微。","竹裏橋鳴知马過，塔中灯露见鴻飞。","眉毫別後應盈尺，嵒木居来定幾圍。","他日願師容一榻，煎茶埽地学忘機。"]', '诗', 'shi', '', NULL, '寄淮海惠澤上人 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7a14e8d-7e63-48c7-8369-64b727157def', '春日隱居官舍感懷', '春日隐居官舍感懷', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["風吹燒燼雜汀沙，還似青溪舊寄家。","入戶竹生牀下葉，隔窗蓮謝鏡中花。","苔房毳客論三學，雪嶺巢禽看兩衙。","銷得人間無限事，江亭月白誦南華。"]', '["风吹燒燼杂汀沙，還似青溪旧寄家。","入戶竹生牀下葉，隔窗蓮謝镜中花。","苔房毳客論三学，雪嶺巢禽看兩衙。","銷得人间無限事，江亭月白誦南华。"]', '诗', 'shi', '', NULL, '春日隱居官舍感懷 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b7a378e-2e3e-4703-9c05-dd92295c2453', '春日即事寄一二知己', '春日即事寄一二知己', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["浴馬池西一帶泉，開門景物似樊川。","朱衣暎水人歸縣，白羽遺泥鶴上天。","索米夜燒風折木，無車春養雪藏鞭。","縉紳處士知章句，忍使孤窗枕淚眠。"]', '["浴马池西一带泉，开门景物似樊川。","朱衣暎水人归縣，白羽遺泥鹤上天。","索米夜燒风折木，無车春養雪藏鞭。","縉紳处士知章句，忍使孤窗枕泪眠。"]', '诗', 'shi', '', NULL, '春日即事寄一二知己 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed88beca-d778-42ee-82f5-cfbaa3bc0e3b', '廢寺閑居寄懷一二罷舉知己', '廢寺闲居寄懷一二罷舉知己', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["病居廢廟冷吟煙，無力爭飛類病蟬。","槐省老郎蒙主棄，月陂孤客望誰憐。","稅房兼得調猿石，租地仍分浴鶴泉。","處世堪驚又堪媿，一坡山色不論錢。"]', '["病居廢廟冷吟煙，無力爭飞類病蟬。","槐省老郎蒙主棄，月陂孤客望誰怜。","稅房兼得調猿石，租地仍分浴鹤泉。","处世堪驚又堪媿，一坡山色不論錢。"]', '诗', 'shi', '', NULL, '廢寺閑居寄懷一二罷舉知己 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db0e4213-7be3-4785-9958-3d482f3ec4e3', '題尼大德院', '題尼大德院', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["雲鬟早歲斷金刀，戒律曾持五百條。","臺上燈紅蓮葉密，眉間毫白黛痕銷。","繡成佛國銀爲地，畫出王城雪覆橋。","清淨高樓松檜寺，世雄翻媿自低腰。"]', '["云鬟早歲斷金刀，戒律曾持五百條。","台上灯紅蓮葉密，眉间毫白黛痕銷。","繡成佛国銀爲地，畫出王城雪覆橋。","清淨高楼松檜寺，世雄翻媿自低腰。"]', '诗', 'shi', '', NULL, '題尼大德院 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('704294cd-98b8-40fc-a4bf-8603d87e6bea', '懷張喬張霞', '懷張喬張霞', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["西風吹雨葉還飄，憶我同袍隔海濤。","江塔眺山青入佛，邊城履雪白連鵰。","身離世界歸天竺，影挂虛空度石橋。","應念無成獨流轉，嬾磨銅片鬢毛焦。"]', '["西风吹雨葉還飄，憶我同袍隔海濤。","江塔眺山青入佛，邊城履雪白連鵰。","身離世界归天竺，影挂虛空度石橋。","應念無成独流轉，嬾磨銅片鬢毛焦。"]', '诗', 'shi', '', NULL, '懷張喬張霞 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5db6190c-5a02-426f-882e-68c044218069', '贈徐山人', '贈徐山人', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["徐生何代降坤維，曾伴園公採紫芝。","瓦礫變黃憂世換，髭鬚放白怕人疑。","山房古竹麄於樹，海島靈童壽等龜。","知歎有唐三百載，光陰未抵一先棊。"]', '["徐生何代降坤維，曾伴园公採紫芝。","瓦礫变黄憂世換，髭鬚放白怕人疑。","山房古竹麄於樹，海島靈童壽等龟。","知歎有唐三百載，光陰未抵一先棊。"]', '诗', 'shi', '', NULL, '贈徐山人 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a35c5025-4e0f-45f4-a0f8-c496a2b717a5', '寄南嶽僧', '寄南嶽僧', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["新秋日後曬書天，白日當松影却圓。","五字句求方寸佛，一條街擘兩行蟬。","不曾著事於機內，長合教山在眼前。","花落儔公房外石，調猿弄虎歎無緣。"]', '["新秋日後曬书天，白日當松影却圓。","五字句求方寸佛，一條街擘兩行蟬。","不曾著事於機內，长合教山在眼前。","花落儔公房外石，調猿弄虎歎無緣。"]', '诗', 'shi', '', NULL, '寄南嶽僧 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7c7b8e9-5cfc-4c0a-9ad3-bfcb665712c1', '華山', '华山', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["碧山長凍地長秋，日夕泉源聒華州。","萬戶煙侵關令宅，四時雲在使君樓。","風驅雷電臨河震，鶴引神仙出月遊。","峰頂高眠靈藥熟，自無霜雪上人頭。"]', '["碧山长凍地长秋，日夕泉源聒华州。","万戶煙侵关令宅，四时云在使君楼。","风驱雷電臨河震，鹤引神仙出月游。","峰頂高眠靈藥熟，自無霜雪上人头。"]', '诗', 'shi', '', NULL, '華山 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1322dfff-9b67-47ed-aeea-0081c50a596b', '和曹監春晴見寄', '和曹監春晴见寄', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["竺廟鄰鐘震曉鴉，春陰蓋石似仙家。","蘭臺架列排書目，顧渚香浮瀹茗花。","膠溜石松粘鶴氅，泉離冰井熨僧牙。","功成名著扁舟去，愁覩前題罩碧紗。"]', '["竺廟鄰鐘震晓鴉，春陰蓋石似仙家。","蘭台架列排书目，顧渚香浮瀹茗花。","膠溜石松粘鹤氅，泉離冰井熨僧牙。","功成名著扁舟去，愁覩前題罩碧紗。"]', '诗', 'shi', '', NULL, '和曹監春晴見寄 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2db05d4a-a627-4bbd-b852-c3e8a94bbfce', '贈三惠大師', '贈三惠大師', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["楓猿嶠角別多時，二教兼修內學師。","藥樹影中頻綴偈，蓮峰朵下幾窺棊。","遊歸筍長齊童子，病起巢成露鶴兒。","詔落五天開夏講，兩街人競禮長眉。"]', '["楓猿嶠角別多时，二教兼修內学師。","藥樹影中頻綴偈，蓮峰朵下幾窺棊。","游归筍长齊童子，病起巢成露鹤兒。","詔落五天开夏講，兩街人競禮长眉。"]', '诗', 'shi', '', NULL, '贈三惠大師 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('657d4c9f-abdc-42b4-a9c0-de4e41151adf', '送醉畫王處士', '送醉畫王处士', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["幾年乘興住南吳，狂醉蘭舟夜落湖。","別後鶴毛描轉細，近來牛角飲還麄。","同餐夏果山何處，共釣秋濤石在無。","關下相逢怪予老，篇章役思繞寰區。"]', '["幾年乘兴住南吳，狂醉蘭舟夜落湖。","別後鹤毛描轉細，近来牛角饮還麄。","同餐夏果山何处，共釣秋濤石在無。","关下相逢怪予老，篇章役思繞寰區。"]', '诗', 'shi', '', NULL, '送醉畫王處士 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c721b230-ed06-4ca6-9eb7-59d5fd1e0955', '聞杜鵑', '闻杜鵑', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["萬古瀟湘波上雲，化爲流血杜鵑身。","長疑啄破青山色，秪恐啼穿白日輪。","花落玄宗迴蜀道，雨收工部宿江津。","聲聲猶得到君耳，不見千秋一甑塵。"]', '["万古瀟湘波上云，化爲流血杜鵑身。","长疑啄破青山色，秪恐啼穿白日輪。","花落玄宗迴蜀道，雨收工部宿江津。","声声猶得到君耳，不见千秋一甑塵。"]', '诗', 'shi', '', NULL, '聞杜鵑 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a36c47a8-15ee-41bc-8593-8b7887144bce', '賦得送軒轅先生歸羅浮山', '賦得送軒轅先生归羅浮山', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["舊山歸隱浪搖青，綠鬢山童一帙經。","詩帖布帆猿鳥看，藥煎金鼎鬼神聽。","洞深頭上聆仙語，船靜鼻中聞海腥。","此處先生應不住，吾君南望漫勞形。"]', '["旧山归隐浪搖青，綠鬢山童一帙經。","诗帖布帆猿鸟看，藥煎金鼎鬼神听。","洞深头上聆仙語，船静鼻中闻海腥。","此处先生應不住，吾君南望漫勞形。"]', '诗', 'shi', '', NULL, '賦得送軒轅先生歸羅浮山 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe6b29e6-4c01-42e2-9674-ece98049ba4e', '送包處士', '送包处士', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["秋思枕月臥瀟湘，寄宿慈恩竹裏房。","性急却於棊上慢，身閑未免藥中忙。","休拋手網驚龍睡，曾挂頭巾拂鳥行。","聞說石門君舊隱，寒峰濺瀑壞書堂。"]', '["秋思枕月臥瀟湘，寄宿慈恩竹裏房。","性急却於棊上慢，身闲未免藥中忙。","休拋手網驚龙睡，曾挂头巾拂鸟行。","闻说石门君旧隐，寒峰濺瀑壞书堂。"]', '诗', 'shi', '', NULL, '送包處士 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9047879-30dc-496e-95fc-ccf2264c6adc', '贈龐鍊師', '贈龐鍊師', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["家住涪江漢語嬌，一聲歌戛玉樓簫。","睡融春日柔金縷，妝發秋霞戰翠翹。","兩臉酒醺紅杏妬，半胸酥嫩白雲饒。","若能攜手隨仙令，皎皎銀河渡鵲橋。"]', '["家住涪江漢語嬌，一声歌戛玉楼簫。","睡融春日柔金縷，妝發秋霞戰翠翹。","兩臉酒醺紅杏妬，半胸酥嫩白云饒。","若能携手隨仙令，皎皎銀河渡鵲橋。"]', '诗', 'shi', '', NULL, '贈龐鍊師 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e7da502-6168-406e-ade2-441de4fb5a16', '送友罷舉赴邊職', '送友罷舉赴邊職', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["出剡篇章入洛文，無人細讀歎俱焚。","莫辭秉笏隨紅斾，便好攜家住白雲。","過水象浮蠻境見，隔江猿呌漢州聞。","高談闊略陳從事，盟誓邊庭壯我軍。"]', '["出剡篇章入洛文，無人細读歎俱焚。","莫辞秉笏隨紅斾，便好携家住白云。","過水象浮蠻境见，隔江猿呌漢州闻。","高談闊略陳從事，盟誓邊庭壯我軍。"]', '诗', 'shi', '', NULL, '送友罷舉赴邊職 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26e2b407-6cf6-47be-aa10-efd2af622d72', '病猿', '病猿', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["瘦纏金鎖惹朱樓，一別巫山樹幾秋。","寒想蜀門清露滴，暖懷湘岸白雲流。","罷拋簷果沉僧井，休拗崖冰濺客舟。","啼過三聲應有淚，畫堂深不徹王侯。"]', '["瘦纏金鎖惹朱楼，一別巫山樹幾秋。","寒想蜀门清露滴，暖懷湘岸白云流。","罷拋簷果沉僧井，休拗崖冰濺客舟。","啼過三声應有泪，畫堂深不徹王侯。"]', '诗', 'shi', '', NULL, '病猿 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd2def7f-4ef3-43d5-990f-18061c5c2df7', '斃驢', '斃驢', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["蹇驢秋斃瘞荒田，忍把敲吟舊竹鞭。","三尺焦桐背殘月，一條藜杖卓寒煙。","通吳白浪寬圍果，倚蜀青山峭入天。","如畫海門搘肘望，阿誰家賣釣魚船。"]', '["蹇驢秋斃瘞荒田，忍把敲吟旧竹鞭。","三尺焦桐背殘月，一條藜杖卓寒煙。","通吳白浪寬圍果，倚蜀青山峭入天。","如畫海门搘肘望，阿誰家賣釣鱼船。"]', '诗', 'shi', '', NULL, '斃驢 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0eaf80f5-5cbe-4075-9e50-793cfa66c8f5', '宿葉公棋閣', '宿葉公棋閣', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["帶風棊閣竹相敲，局瑩無塵拂樹梢。","日到長天征未斷，鐘來嶽頂劫須拋。","挑燈雪客棲寒店，供茗溪僧爇廢巢。","因悟修身試貪教，不須焚火向三茅。"]', '["带风棊閣竹相敲，局瑩無塵拂樹梢。","日到长天征未斷，鐘来嶽頂劫須拋。","挑灯雪客棲寒店，供茗溪僧爇廢巢。","因悟修身試貪教，不須焚火向三茅。"]', '诗', 'shi', '', NULL, '宿葉公棋閣 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6ae71b0-28e1-4c6e-9c94-f5eec4b3e3c2', '送郄先輩歸覲華陰', '送郄先輩归覲华陰', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["桂枝博得鳳棲枝，歡覲家僮舞翠微。","僧向瀑泉聲裏賀，鳥穿仙掌指間飛。","休停硯筆吟荒廟，永別燈籠赴鎖闈。","騷雅近來頹喪甚，送君傍覺有光輝。"]', '["桂枝博得鳳棲枝，歡覲家僮舞翠微。","僧向瀑泉声裏賀，鸟穿仙掌指间飞。","休停硯笔吟荒廟，永別灯籠赴鎖闈。","騷雅近来頹喪甚，送君傍覺有光輝。"]', '诗', 'shi', '', NULL, '送郄先輩歸覲華陰 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ec6188a-cfae-416e-b48f-5906b2877810', '贈可上人', '贈可上人', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["寺門和鶴倚香杉，月吐秋光到思嚵。","將法傳來穿泱漭，把詩吟去入嵌巖。","糢糊書卷煙嵐滴，狼籍衣裳瀑布緘。","不斷清風牙底嚼，無因內殿得名銜。"]', '["寺门和鹤倚香杉，月吐秋光到思嚵。","將法傳来穿泱漭，把诗吟去入嵌巖。","糢糊书卷煙嵐滴，狼籍衣裳瀑布緘。","不斷清风牙底嚼，無因內殿得名銜。"]', '诗', 'shi', '', NULL, '贈可上人 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d6d5d10-d845-48d1-9500-17dc436a889b', '東川高僕射', '东川高僕射', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["油幢影裏拜清風，十里貔貅一片雄。","三印鎖開霜滿地，四門關定月當空。","泉浮山葉人家過，詔惹罏香鳥道通。","新起畫樓攜客上，絃歌筵內海榴紅。"]', '["油幢影裏拜清风，十里貔貅一片雄。","三印鎖开霜满地，四门关定月當空。","泉浮山葉人家過，詔惹罏香鸟道通。","新起畫楼携客上，絃歌筵內海榴紅。"]', '诗', 'shi', '', NULL, '東川高僕射 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f414440-934e-4b25-88db-4459ca7bcd36', '宿成都松溪院', '宿成都松溪院', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["松持節操溪澄性，一炷煙嵐壓寺隅。","翡翠鳥飛人不見，琉璃缾貯水疑無。","夜聞子落真山雨，曉汲波圓入畫圖。","塵擁蜀城抽鎖後，此中猶夢在江湖。"]', '["松持節操溪澄性，一炷煙嵐壓寺隅。","翡翠鸟飞人不见，琉璃缾貯水疑無。","夜闻子落真山雨，晓汲波圓入畫圖。","塵擁蜀城抽鎖後，此中猶梦在江湖。"]', '诗', 'shi', '', NULL, '宿成都松溪院 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c160c462-c0bb-4878-8a4b-758c79f0d692', '弔曹監', '弔曹監', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["宅上愁雲吹不散，桂林詩骨葬雲根。","滿樓山色供鄰里，一洞松聲付子孫。","甘露施衣封淚點，秘書取集印苔痕。","吟魂醉魄歸何處，御水嗚嗚夜遶門。"]', '["宅上愁云吹不散，桂林诗骨葬云根。","满楼山色供鄰里，一洞松声付子孫。","甘露施衣封泪点，秘书取集印苔痕。","吟魂醉魄归何处，御水嗚嗚夜遶门。"]', '诗', 'shi', '', NULL, '弔曹監 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee20475d-7930-43dd-9451-d3afdb00910b', '贈長安畢郎中', '贈长安畢郎中', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["高門寒沼水連雲，鷺識朱衣傍主人。","地肺半邊晴帶雪，天街一面靜無塵。","朝迴座客酬琴價，衙退留僧寫鶴真。","從此幾遷爲計相，蓬萊三刻奏東巡。"]', '["高门寒沼水連云，鷺識朱衣傍主人。","地肺半邊晴带雪，天街一面静無塵。","朝迴座客酬琴價，衙退留僧寫鹤真。","從此幾遷爲計相，蓬萊三刻奏东巡。"]', '诗', 'shi', '', NULL, '贈長安畢郎中 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('865ff86d-2470-48ad-998e-180aff28b34f', '寄東蜀幕中友', '寄东蜀幕中友', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["官亭池碧海榴殷，遙想清才倚畫欄。","柳絮漲天籠地暖，角聲經雨透雲寒。","曉侵台座香煙濕，夜草軍書蠟炬乾。","爲話門人吟太苦，風摧蘭秀一枝殘。"]', '["官亭池碧海榴殷，遙想清才倚畫欄。","柳絮漲天籠地暖，角声經雨透云寒。","晓侵台座香煙濕，夜草軍书蠟炬乾。","爲話门人吟太苦，风摧蘭秀一枝殘。"]', '诗', 'shi', '', NULL, '寄東蜀幕中友 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0919bd54-20f4-4c8d-8c8b-f162de3dac9a', '曲江漁父', '曲江漁父', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["兒孫閑弄雪霜髯，浪颭南山影入簷。","臥穩篷舟龜作枕，病來茅舍網爲簾。","值春游子憐蓴滑，通蜀行人說鱠甜。","數尺寒絲一竿竹，豈知浮世有猜嫌。"]', '["兒孫闲弄雪霜髯，浪颭南山影入簷。","臥穩篷舟龟作枕，病来茅舍網爲簾。","值春游子怜蓴滑，通蜀行人说鱠甜。","數尺寒絲一竿竹，豈知浮世有猜嫌。"]', '诗', 'shi', '', NULL, '曲江漁父 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72c6bbb1-6ff5-43ee-b640-14f107c6275e', '和劉駕博士贈莊嚴律禪師', '和劉駕博士贈莊嚴律禪師', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["人言紫綬有光輝，不二心觀似草衣。","塵劫自營還自壞，禪門無住亦無歸。","松根穴蟻通山遠，塔頂巢禽見海微。","每話南遊偏起念，五峰波上入船扉。"]', '["人言紫綬有光輝，不二心观似草衣。","塵劫自營還自壞，禪门無住亦無归。","松根穴蟻通山远，塔頂巢禽见海微。","每話南游偏起念，五峰波上入船扉。"]', '诗', 'shi', '', NULL, '和劉駕博士贈莊嚴律禪師 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5431302-07b4-4def-b5ff-e5b1ffd70fcb', '智新上人話舊', '智新上人話旧', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["蟋蟀燈前話舊遊，師經幾夏我經秋。","金陵市合月光裏，甘露門開峰朵頭。","晴眺遠帆飛入海，夜禪陰火吐當樓。","相看未得東歸去，滿壁寒濤瀉白鷗。"]', '["蟋蟀灯前話旧游，師經幾夏我經秋。","金陵市合月光裏，甘露门开峰朵头。","晴眺远帆飞入海，夜禪陰火吐當楼。","相看未得东归去，满壁寒濤瀉白鷗。"]', '诗', 'shi', '', NULL, '智新上人話舊 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3463f4dd-2477-4bc7-ab5c-1f0f2c24590a', '和淮南太尉留題鳳州王氏別業', '和淮南太尉留題鳳州王氏別業', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["清秋看長鷺雛成，說向湘僧亦動情。","節屋折將松上影，印龕移鎖月中聲。","野人陪賞增詩價，太尉因居著谷名。","閑想此中遺勝事，宿齋吟遶鳳池行。"]', '["清秋看长鷺雛成，说向湘僧亦动情。","節屋折將松上影，印龕移鎖月中声。","野人陪賞增诗價，太尉因居著谷名。","闲想此中遺勝事，宿斋吟遶鳳池行。"]', '诗', 'shi', '', NULL, '和淮南太尉留題鳳州王氏別業 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ad567e3-9d83-4272-8e32-fb4d0bc41ff3', '乙酉歲自蜀隨計趂試不及', '乙酉歲自蜀隨計趂試不及', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["客臥涪江蘸月廳，知音喚起進趨生。","寒梅折後方離蜀，臘月圓前未到京。","風卷壞亭羸僕病，雪糊危棧蹇驢行。","文昌一試應關分，豈校褒斜兩日程。"]', '["客臥涪江蘸月廳，知音喚起進趨生。","寒梅折後方離蜀，臘月圓前未到京。","风卷壞亭羸僕病，雪糊危棧蹇驢行。","文昌一試應关分，豈校褒斜兩日程。"]', '诗', 'shi', '', NULL, '乙酉歲自蜀隨計趂試不及 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('591954e3-94ae-41f0-a2b1-5dbad55e951f', '龍州韋郎中先夢六赤後因打葉子以詩上', '龙州韋郎中先梦六赤後因打葉子以诗上', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["紅蠟香煙撲畫楹，梅花落盡庾樓清。","光輝圓魄銜山冷，彩鏤方牙着腕輕。","寶帖牽來獅子鎮，金盆引出鳳凰傾。","微黃喜兆莊周夢，六赤重新擲印成。"]', '["紅蠟香煙撲畫楹，梅花落尽庾楼清。","光輝圓魄銜山冷，彩鏤方牙着腕轻。","寶帖牽来獅子鎮，金盆引出鳳凰傾。","微黄喜兆莊周梦，六赤重新擲印成。"]', '诗', 'shi', '', NULL, '龍州韋郎中先夢六赤後因打葉子以詩上 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da446e03-8b8b-4974-acbe-a962685e4264', '和壽中丞傷猿', '和壽中丞傷猿', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["遺挂朱欄鎖半尋，清聲難買恨黃金。","懸崖接果今何在，淺井窺星影已沉。","歸宅葉鋪曾睡石，入朝燈照舊啼林。","小山罷遶隨湘客，高樹休升對嶽禽。","天竺省憐傷倍切，親知寬和思難任。","相門恩重無由報，竟託仙郎日夜吟。"]', '["遺挂朱欄鎖半尋，清声难買恨黄金。","懸崖接果今何在，淺井窺星影已沉。","归宅葉鋪曾睡石，入朝灯照旧啼林。","小山罷遶隨湘客，高樹休升对嶽禽。","天竺省怜傷倍切，親知寬和思难任。","相门恩重無由報，竟託仙郎日夜吟。"]', '诗', 'shi', '', NULL, '和壽中丞傷猿 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0555091-c336-42f6-98e6-8b5103b2a298', '上靈州令狐相公', '上靈州令狐相公', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["征蠻破虜漢功臣，提劒歸來萬里身。","笑倚凌煙金柱看，形容憔悴老於真。"]', '["征蠻破虜漢功臣，提劒归来万里身。","笑倚凌煙金柱看，形容憔悴老於真。"]', '诗', 'shi', '', NULL, '上靈州令狐相公 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59d55f22-70af-4c9f-b208-2899ca9220fd', '寓言', '寓言', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["三千宮女露蛾眉，笑煮黃金日月遲。","麟鳳隔雲攀不及，空山惆悵夕陽時。"]', '["三千宮女露蛾眉，笑煮黄金日月遲。","麟鳳隔云攀不及，空山惆悵夕陽时。"]', '诗', 'shi', '', NULL, '寓言 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad66e2cd-4bd3-4ca9-ac5b-4b6b69892d50', '客亭對月', '客亭对月', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["游子離魂隴上花，風飄浪卷遶天涯。","一年十二度圓月，十一回圓不在家。"]', '["游子離魂隴上花，风飄浪卷遶天涯。","一年十二度圓月，十一回圓不在家。"]', '诗', 'shi', '', NULL, '客亭對月 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f10da4e2-dc93-4c65-931e-6adb79f74a33', '宿鄠郊贈羅處士', '宿鄠郊贈羅处士', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["川靜星高櫟已枯，南山落石水聲麤。","白雲釣客窗中宿，臥數嵩峰聽五湖。"]', '["川静星高櫟已枯，南山落石水声麤。","白云釣客窗中宿，臥數嵩峰听五湖。"]', '诗', 'shi', '', NULL, '宿鄠郊贈羅處士 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e072d5d0-8b78-4177-aa34-7d566dd63cdf', '有寄', '有寄', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["愛酒耽棊田處士，彈琴詠史賈先生。","御溝臨岸有雲石，不見鶴來何處行。"]', '["愛酒耽棊田处士，彈琴詠史賈先生。","御溝臨岸有云石，不见鹤来何处行。"]', '诗', 'shi', '', NULL, '有寄 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c89f910-3c30-4728-b5d6-48b2bf980932', '送三藏歸西天國', '送三藏归西天国', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["十萬里程多少磧，沙中彈舌授降龍。","五天到日應頭白，月落長安半夜鐘。"]', '["十万里程多少磧，沙中彈舌授降龙。","五天到日應头白，月落长安半夜鐘。"]', '诗', 'shi', '', NULL, '送三藏歸西天國 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a51bce6a-da65-43b3-9841-65a5e81830de', '金陵懷古', '金陵懷古', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["古來無此戰爭功，日日戈船卷海風。","一遇靈鼇開睡眼，六朝灰盡九江空。"]', '["古来無此戰爭功，日日戈船卷海风。","一遇靈鼇开睡眼，六朝灰尽九江空。"]', '诗', 'shi', '', NULL, '金陵懷古 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e11a4613-541f-4ace-8c40-7fe47dbf1776', '長安縣廳', '长安縣廳', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["主人寂寞客屯邅，愁絕終南滿案前。","乞取中庭藤五尺，爲君高斸扣青天。"]', '["主人寂寞客屯邅，愁絕終南满案前。","乞取中庭藤五尺，爲君高斸扣青天。"]', '诗', 'shi', '', NULL, '長安縣廳 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('883ca947-bb8a-4579-a191-bb51bff9852d', '題晰上人賈島詩卷', '題晰上人賈島诗卷', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["賈生詩卷惠休裝，百葉蓮花萬里香。","供得半年吟不足，長須字字頂司倉。"]', '["賈生诗卷惠休裝，百葉蓮花万里香。","供得半年吟不足，长須字字頂司倉。"]', '诗', 'shi', '', NULL, '題晰上人賈島詩卷 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('841b15a6-0553-49ee-8de6-37ec9419c3b3', '送僧清演歸山', '送僧清演归山', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["毛褐斜肩背負經，曉思吟入竇山青。","峰前野水橫官道，踏着秋天三四星。"]', '["毛褐斜肩背負經，晓思吟入竇山青。","峰前野水橫官道，踏着秋天三四星。"]', '诗', 'shi', '', NULL, '送僧清演歸山 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cd09c7f-80bc-432a-a690-bdb4a5b8f0d8', '贈僧', '贈僧', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["不羨王公與貴人，唯將雲鶴自相親。","閑來石上觀流水，欲洗禪衣未有塵。"]', '["不羨王公與貴人，唯將云鹤自相親。","闲来石上观流水，欲洗禪衣未有塵。"]', '诗', 'shi', '', NULL, '贈僧 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f7b0eca-4f32-4451-a153-6dc5f2290b37', '題學公院池蓮', '題学公院池蓮', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["竹引山泉玉甃池，栽蓮莫怪藕生絲。","如何不似麻衣客，坐對秋風待一枝。"]', '["竹引山泉玉甃池，栽蓮莫怪藕生絲。","如何不似麻衣客，坐对秋风待一枝。"]', '诗', 'shi', '', NULL, '題學公院池蓮 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1775fa41-f1d8-4845-8168-a6cda90bbd80', '山居喜友人見訪', '山居喜友人见訪', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["入雲晴斸茯苓還，日暮逢迎木石間。","看待詩人無別物，半潭秋水一房山。"]', '["入云晴斸茯苓還，日暮逢迎木石间。","看待诗人無別物，半潭秋水一房山。"]', '诗', 'shi', '', NULL, '山居喜友人見訪 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b82a19f-8596-4c4f-b3f3-276667cfc0cb', '秋宿長安韋主簿廳', '秋宿长安韋主簿廳', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["水木清涼夜直廳，愁人樓上唱寒更。","坐勞同步簾前月，鼠動牀頭印鎖聲。"]', '["水木清涼夜直廳，愁人楼上唱寒更。","坐勞同步簾前月，鼠动牀头印鎖声。"]', '诗', 'shi', '', NULL, '秋宿長安韋主簿廳 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3516a20-be76-4d2d-81ca-15d285deadfc', '冬憶友人', '冬憶友人', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["吟上山前數竹枝，葉翻似雪落霏霏。","枕前明月誰動影，睡裏驚來不覺歸。"]', '["吟上山前數竹枝，葉翻似雪落霏霏。","枕前明月誰动影，睡裏驚来不覺归。"]', '诗', 'shi', '', NULL, '冬憶友人 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79f8e0a1-fe11-48fa-aa8b-136fdddfde1d', '懷圭峰影林泉', '懷圭峰影林泉', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["吾家舊物賈生傳，入內遙分錫杖泉。","鶴去帝移宮女散，更堪嗚咽過樓前。"]', '["吾家旧物賈生傳，入內遙分錫杖泉。","鹤去帝移宮女散，更堪嗚咽過楼前。"]', '诗', 'shi', '', NULL, '懷圭峰影林泉 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f05eec46-29b3-4290-a899-96502ec548d6', '贈青龍印禪師', '贈青龙印禪師', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["雨澀秋刀剃雪時，菴前曾禮草堂師。","居人昨日相過說，鶴已生孫竹滿池。"]', '["雨澀秋刀剃雪时，菴前曾禮草堂師。","居人昨日相過说，鹤已生孫竹满池。"]', '诗', 'shi', '', NULL, '贈青龍印禪師 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2266386d-8617-44b2-8cd4-49beb4d97e32', '戲贈侯常侍', '戲贈侯常侍', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["葛洪卷與江淹賦，名動天邊傲石居。","兩蜀詞人多載後，同君諱却馬相如。"]', '["葛洪卷與江淹賦，名动天邊傲石居。","兩蜀词人多載後，同君諱却马相如。"]', '诗', 'shi', '', NULL, '戲贈侯常侍 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f03d934-3eb3-430b-8055-d524ced4af8f', '繡嶺宮詞', '繡嶺宮词', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["春日遲遲春草綠，野棠開盡飄香玉。","繡嶺宮前鶴髮翁，猶唱開元太平曲。"]', '["春日遲遲春草綠，野棠开尽飄香玉。","繡嶺宮前鹤髮翁，猶唱开元太平曲。"]', '诗', 'shi', '', NULL, '繡嶺宮詞 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('129c374f-2356-421c-b215-784c679d24e2', '中秋月', '中秋月', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["九十日秋色，今秋已半分。","孤光吞列宿，四面絕微雲。","衆木排疎影，寒流疊細紋。","遙遙望丹桂，心緒更紛紛。"]', '["九十日秋色，今秋已半分。","孤光吞列宿，四面絕微云。","衆木排疎影，寒流叠細紋。","遙遙望丹桂，心緒更紛紛。"]', '诗', 'shi', '', NULL, '中秋月 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f928988-ac03-47bf-9505-ee5a41067cba', '宿書僧院', '宿书僧院', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["夜水筆前澄，時推外學能。","書成百箇字，庭轉幾遭燈。","寄墨大壇吏，分牋蜀國僧。","爲題江寺塔，牌挂入雲層。"]', '["夜水笔前澄，时推外学能。","书成百箇字，庭轉幾遭灯。","寄墨大壇吏，分牋蜀国僧。","爲題江寺塔，牌挂入云層。"]', '诗', 'shi', '', NULL, '宿書僧院 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('513d8869-5c70-4ca0-9c0f-ff0a0c3931b1', '雪', '雪', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["迢迢來極塞，連闕謂風吹。","禪客呵金錫，征人擘凍旗。","細填蟲穴滿，重壓鶴巢欹。","有影晴飄野，無聲夜落池。","正繁秦甸暖，漸厚楚宮飢。","凍挹分泉澀，光凝二閣癡。","踏遺蘭署跡，聽起石門思。","用表豐年瑞，無令埽玉墀。"]', '["迢迢来極塞，連闕謂风吹。","禪客呵金錫，征人擘凍旗。","細填蟲穴满，重壓鹤巢欹。","有影晴飄野，無声夜落池。","正繁秦甸暖，漸厚楚宮飢。","凍挹分泉澀，光凝二閣癡。","踏遺蘭署跡，听起石门思。","用表豐年瑞，無令埽玉墀。"]', '诗', 'shi', '', NULL, '雪 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd38d815-9052-4066-a9a8-315a93d7a5fe', '述懷二十韻獻覃懷相公', '述懷二十韻獻覃懷相公', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["帝夢求良弼，生申屬聖明。","青雲縣器業，白日貫忠貞。","靄靄隨春動，忻忻共物榮。","靜宜浮競息，坐覺好風生。","萬國聞應躍，千門望盡傾。","瑞含楊柳色，氣變管絃聲。","百辟尋知度，三階正有程。","魯儒規蘊藉，周誥美和平。","碧水遺幽抱，朱絲寄遠情。","風流秦印綬，儀表漢公卿。","忠讜期登用，回邪自震驚。","雲開長劒倚，路絕一峰橫。","九野方無事，滄溟本不爭。","國將身共計，心與衆爲城。","早晚中條下，紅塵一顧清。","南潭容伴鶴，西笑忽遷鶯。","折樹恩難報，懷仁命甚輕。","二年猶困辱，百口望經營。","未在英侯選，空勞短羽征。","知音初相國，從此免長鳴。"]', '["帝梦求良弼，生申屬聖明。","青云縣器業，白日貫忠貞。","靄靄隨春动，忻忻共物榮。","静宜浮競息，坐覺好风生。","万国闻應躍，千门望尽傾。","瑞含楊柳色，氣变管絃声。","百辟尋知度，三階正有程。","魯儒規蘊藉，周誥美和平。","碧水遺幽抱，朱絲寄远情。","风流秦印綬，儀表漢公卿。","忠讜期登用，回邪自震驚。","云开长劒倚，路絕一峰橫。","九野方無事，滄溟本不爭。","国將身共計，心與衆爲城。","早晚中條下，紅塵一顧清。","南潭容伴鹤，西笑忽遷鶯。","折樹恩难報，懷仁命甚轻。","二年猶困辱，百口望經營。","未在英侯選，空勞短羽征。","知音初相国，從此免长鳴。"]', '诗', 'shi', '', NULL, '述懷二十韻獻覃懷相公 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6dddcac1-5920-40e9-a837-02894ac12e86', '歲暮自廣江至新興往復中題峽山寺', '歲暮自廣江至新兴往复中題峽山寺', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["薄暮緣西峽，停橈一訪僧。","鷺巢行臥柳，猿飲倒垂藤。","水曲巖千疊，雲深樹百層。","山風寒殿磬，溪雨夜船燈。","灘漲危槎沒，泉衝怪石崩。","中臺一襟淚，歲杪別良朋。"]', '["薄暮緣西峽，停橈一訪僧。","鷺巢行臥柳，猿饮倒垂藤。","水曲巖千叠，云深樹百層。","山风寒殿磬，溪雨夜船灯。","灘漲危槎沒，泉衝怪石崩。","中台一襟泪，歲杪別良朋。"]', '诗', 'shi', '', NULL, '歲暮自廣江至新興往復中題峽山寺 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04a08d2f-b83b-4599-9954-49a7162b9f15', '冬日送涼州刺史', '冬日送涼州刺史', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["寵餞西門外，雙旌出漢陵。","未辭金殿日，已夢雪山燈。","地遠終峰盡，天寒朔氣凝。","新年行已到，舊典聽難勝。","吏掃盤雕影，人遮散馬乘。","移軍駝馱角，下塞掾河冰。","獵近崑崙獸，吟招磧石僧。","重輸右藏實，方見左車能。","兵聚邊風急，城寬夜月澄。","連營煙火嶺，望詔幾迴登。"]', '["寵餞西门外，雙旌出漢陵。","未辞金殿日，已梦雪山灯。","地远終峰尽，天寒朔氣凝。","新年行已到，旧典听难勝。","吏掃盤雕影，人遮散马乘。","移軍駝馱角，下塞掾河冰。","獵近崑崙獸，吟招磧石僧。","重輸右藏實，方见左车能。","兵聚邊风急，城寬夜月澄。","連營煙火嶺，望詔幾迴登。"]', '诗', 'shi', '', NULL, '冬日送涼州刺史 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('196eb93d-e3f5-4537-8efd-da5f8f6b03a1', '過賈浪仙舊地', '過賈浪仙旧地', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["鶴外唐來有謫星，長江東注冷滄溟。","境搜松雪仙人島，吟歇林泉主簿廳。","片月已能臨榜黑，遙天何益抱墳青。","年年誰不登高第，未勝騎驢入畫屏。"]', '["鹤外唐来有謫星，长江东注冷滄溟。","境搜松雪仙人島，吟歇林泉主簿廳。","片月已能臨榜黑，遙天何益抱墳青。","年年誰不登高第，未勝騎驢入畫屏。"]', '诗', 'shi', '', NULL, '過賈浪仙舊地 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc3945f6-f7a7-434c-adc5-fe0b2043d17d', '句', '句', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["公道此時如不得，昭陵慟哭一生休。"]', '["公道此时如不得，昭陵慟哭一生休。"]', '诗', 'shi', '', NULL, '句 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0aace3b-defb-4eb2-98bd-bc2dcb6968af', '酬友生早秋', '酬友生早秋', '29517e7f-a2d9-44bc-beed-612087da2f5d', '唐', '["彤雲將欲罷，蟬柳響如秋。","霧散九霄近，日程三伏愁。","殘陽宿雨霽，高浪碎沙漚。","袪足餘旬後，分襟任自由。"]', '["彤云將欲罷，蟬柳响如秋。","霧散九霄近，日程三伏愁。","殘陽宿雨霽，高浪碎沙漚。","袪足餘旬後，分襟任自由。"]', '诗', 'shi', '', NULL, '酬友生早秋 唐求 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df9e4ccc-8781-44b8-8346-5af01a82a612', '曉發', '晓發', '29517e7f-a2d9-44bc-beed-612087da2f5d', '唐', '["旅館候天曙，整車趨遠程。","幾處曉鐘斷，半橋殘月明。","沙上鳥猶在，渡頭人未行。","去去古時道，馬嘶三兩聲。"]', '["旅館候天曙，整车趨远程。","幾处晓鐘斷，半橋殘月明。","沙上鸟猶在，渡头人未行。","去去古时道，马嘶三兩声。"]', '诗', 'shi', '', NULL, '曉發 唐求 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed0f4a06-37b2-4b14-9e6b-d06d6a0b9c5e', '客行', '客行', '29517e7f-a2d9-44bc-beed-612087da2f5d', '唐', '["上山下山去，千里萬里愁。","樹色野橋暝，雨聲孤館秋。","南北眼前道，東西江畔舟。","世人重金玉，無金徒遠游。"]', '["上山下山去，千里万里愁。","樹色野橋暝，雨声孤館秋。","南北眼前道，东西江畔舟。","世人重金玉，無金徒远游。"]', '诗', 'shi', '', NULL, '客行 唐求 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9478951f-94ad-4e93-b43e-295eb8ae6055', '題鄭處士隱居', '題鄭处士隐居', '29517e7f-a2d9-44bc-beed-612087da2f5d', '唐', '["不信最清曠，及來愁已空。","數點石泉雨，一溪霜葉風。","業在有山處，道成無事中。","酌盡一尊酒，病夫顏亦紅。"]', '["不信最清曠，及来愁已空。","數点石泉雨，一溪霜葉风。","業在有山处，道成無事中。","酌尽一尊酒，病夫顏亦紅。"]', '诗', 'shi', '', NULL, '題鄭處士隱居 唐求 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ab353c5-7e72-4011-9a4e-00d35924ed0d', '古寺', '古寺', '29517e7f-a2d9-44bc-beed-612087da2f5d', '唐', '["路傍古時寺，寥落藏金容。","破塔有寒草，壞樓無曉鐘。","亂紙失經偈，斷碑分篆蹤。","日暮月光吐，繞門千樹松。"]', '["路傍古时寺，寥落藏金容。","破塔有寒草，壞楼無晓鐘。","亂紙失經偈，斷碑分篆蹤。","日暮月光吐，繞门千樹松。"]', '诗', 'shi', '', NULL, '古寺 唐求 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b2b0bee-cf55-40d5-a60b-917ed2b4e52f', '贈著上人', '贈著上人', '29517e7f-a2d9-44bc-beed-612087da2f5d', '唐', '["掩門江上住，盡日更無爲。","古木坐禪處，殘星鳴磬時。","水澆冰滴滴，珠數落纍纍。","自有閑行伴，青藤杖一枝。"]', '["掩门江上住，尽日更無爲。","古木坐禪处，殘星鳴磬时。","水澆冰滴滴，珠數落纍纍。","自有闲行伴，青藤杖一枝。"]', '诗', 'shi', '', NULL, '贈著上人 唐求 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f12e4d4-7d21-47f0-9ce9-469675b1da62', '馬嵬感事', '马嵬感事', '29517e7f-a2d9-44bc-beed-612087da2f5d', '唐', '["冷氣生深殿，狼星渡遠關。","九城鼙鼓內，千騎道途間。","鳳髻隨秋草，鑾輿入暮山。","恨多留不得，悲淚滿龍顏。"]', '["冷氣生深殿，狼星渡远关。","九城鼙鼓內，千騎道途间。","鳳髻隨秋草，鑾輿入暮山。","恨多留不得，悲泪满龙顏。"]', '诗', 'shi', '', NULL, '馬嵬感事 唐求 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf3c2ed5-3fa1-4d06-bdcd-86062190682b', '贈行如上人', '贈行如上人', '29517e7f-a2d9-44bc-beed-612087da2f5d', '唐', '["不知名利苦，念佛老岷峨。","衲補雲千片，香燒印一窠。","戀山人事少，怜客道心多。","日日齋鐘後，高懸濾水羅。"]', '["不知名利苦，念佛老岷峨。","衲補云千片，香燒印一窠。","戀山人事少，怜客道心多。","日日斋鐘後，高懸濾水羅。"]', '诗', 'shi', '', NULL, '贈行如上人 唐求 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1dba4a6-d331-4bb1-8deb-5dd1b487eb0e', '送友人歸邛州', '送友人归邛州', '29517e7f-a2d9-44bc-beed-612087da2f5d', '唐', '["鶴鳴山下去，滿篋荷瑤琨。","放馬荒田草，看碑古寺門。","漸寒沙上雨，欲暝水邊村。","莫忘分襟處，梅花撲酒尊。"]', '["鹤鳴山下去，满篋荷瑤琨。","放马荒田草，看碑古寺门。","漸寒沙上雨，欲暝水邊村。","莫忘分襟处，梅花撲酒尊。"]', '诗', 'shi', '', NULL, '送友人歸邛州 唐求 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60714e33-f2d6-4f05-a705-304eb3714f4e', '和舒上人山居即事', '和舒上人山居即事', '29517e7f-a2d9-44bc-beed-612087da2f5d', '唐', '["敗葉填溪路，殘陽過野亭。","仍彈一滴水，更讀兩張經。","暝鳥煙中見，寒鐘竹裏聽。","不多山下去，人世盡羶腥。"]', '["敗葉填溪路，殘陽過野亭。","仍彈一滴水，更读兩張經。","暝鸟煙中见，寒鐘竹裏听。","不多山下去，人世尽羶腥。"]', '诗', 'shi', '', NULL, '和舒上人山居即事 唐求 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('639970cc-320d-4252-992d-a1790f0ed448', '發邛州寄友人', '發邛州寄友人', '29517e7f-a2d9-44bc-beed-612087da2f5d', '唐', '["茫茫驅一馬，自歎又何之。","出郭見山處，待船逢雨時。","曉雞鳴野店，寒葉墮秋枝。","寂寞前程去，閑吟欲共誰。"]', '["茫茫驱一马，自歎又何之。","出郭见山处，待船逢雨时。","晓雞鳴野店，寒葉墮秋枝。","寂寞前程去，闲吟欲共誰。"]', '诗', 'shi', '', NULL, '發邛州寄友人 唐求 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0640d467-2c30-4a7f-8400-28be62286f70', '舟行夜泊夔州', '舟行夜泊夔州', '29517e7f-a2d9-44bc-beed-612087da2f5d', '唐', '["維舟鏡面中，迴對白鹽峰。","夜靜沙堤月，天寒水寺鐘。","故園何日到，舊友幾時逢。","欲作還家夢，青山一萬重。"]', '["維舟镜面中，迴对白鹽峰。","夜静沙堤月，天寒水寺鐘。","故园何日到，旧友幾时逢。","欲作還家梦，青山一万重。"]', '诗', 'shi', '', NULL, '舟行夜泊夔州 唐求 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b13138e-e63e-4232-89a9-552ad6f21002', '山東蘭若遇靜公夜歸', '山东蘭若遇静公夜归', '29517e7f-a2d9-44bc-beed-612087da2f5d', '唐', '["松門一徑微，苔滑往來稀。","半夜聞鐘後，渾身帶雪歸。","問寒僧接杖，辨語犬銜衣。","又是安禪去，呼童閉竹扉。"]', '["松门一徑微，苔滑往来稀。","半夜闻鐘後，渾身带雪归。","问寒僧接杖，辨語犬銜衣。","又是安禪去，呼童閉竹扉。"]', '诗', 'shi', '', NULL, '山東蘭若遇靜公夜歸 唐求 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4c53bc0-79f1-4f7c-a189-45489569ff54', '邊將', '邊將', '29517e7f-a2d9-44bc-beed-612087da2f5d', '唐', '["三千護塞兒，獨自滯邊陲。","老向二毛見，秋從一葉知。","地寒鄉思苦，天暮角聲悲。","却被交親笑，封侯未有期。"]', '["三千護塞兒，独自滯邊陲。","老向二毛见，秋從一葉知。","地寒乡思苦，天暮角声悲。","却被交親笑，封侯未有期。"]', '诗', 'shi', '', NULL, '邊將 唐求 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38af662c-3fbd-4372-945c-8dfbdff6f2a8', '秋寄□江舒公', '秋寄□江舒公', '29517e7f-a2d9-44bc-beed-612087da2f5d', '唐', '["故人何處望，秋色滿江濆。","入水溪蟲亂，過橋山路分。","鶴歸松上月，僧入竹間雲。","莫惜中宵磬，從教夢裏聞。"]', '["故人何处望，秋色满江濆。","入水溪蟲亂，過橋山路分。","鹤归松上月，僧入竹间云。","莫惜中宵磬，從教梦裏闻。"]', '诗', 'shi', '', NULL, '秋寄□江舒公 唐求 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e44bb14d-46c6-48ac-9dc6-e719d770d922', '題楊山人隱居', '題楊山人隐居', '29517e7f-a2d9-44bc-beed-612087da2f5d', '唐', '["深山道者家，門戶帶煙霞。","綠綴沿巖草，紅飄落水花。","半庭栽小樹，一徑掃平沙。","往往溪邊坐，持竿到日斜。"]', '["深山道者家，门戶带煙霞。","綠綴沿巖草，紅飄落水花。","半庭栽小樹，一徑掃平沙。","往往溪邊坐，持竿到日斜。"]', '诗', 'shi', '', NULL, '題楊山人隱居 唐求 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b9648ad-db50-4e4d-a427-fe43c1362e88', '夜上隱居寺', '夜上隐居寺', '29517e7f-a2d9-44bc-beed-612087da2f5d', '唐', '["尋師擬學空，空住虎磎東。","千里照山月，一枝驚鶴風。","年如流去水，山似轉來蓬。","盡日都無事，安禪石窟中。"]', '["尋師擬学空，空住虎磎东。","千里照山月，一枝驚鹤风。","年如流去水，山似轉来蓬。","尽日都無事，安禪石窟中。"]', '诗', 'shi', '', NULL, '夜上隱居寺 唐求 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1613ad5-4202-4972-9131-47bc15f4f193', '友人見訪不值因寄', '友人见訪不值因寄', '29517e7f-a2d9-44bc-beed-612087da2f5d', '唐', '["門戶寒江近，籬墻野樹深。","晚風搖竹影，斜日轉山陰。","砌覺披秋草，牀驚倒古琴。","更聞鄰舍說，一隻鶴來尋。"]', '["门戶寒江近，籬墻野樹深。","晚风搖竹影，斜日轉山陰。","砌覺披秋草，牀驚倒古琴。","更闻鄰舍说，一隻鹤来尋。"]', '诗', 'shi', '', NULL, '友人見訪不值因寄 唐求 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5de5982f-4328-46d5-bab3-2752a284ae23', '塗次偶作', '塗次偶作', '29517e7f-a2d9-44bc-beed-612087da2f5d', '唐', '["歲月客中銷，崎嶇力自招。","問人尋野寺，牽馬渡危橋。","爲雨疑天晚，因山覺路遙。","前程何處是，一望又迢迢。"]', '["歲月客中銷，崎嶇力自招。","问人尋野寺，牽马渡危橋。","爲雨疑天晚，因山覺路遙。","前程何处是，一望又迢迢。"]', '诗', 'shi', '', NULL, '塗次偶作 唐求 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c5d1f75-a00a-493d-9be7-458f96e36061', '送友人江行之廬山肄業', '送友人江行之廬山肄業', '29517e7f-a2d9-44bc-beed-612087da2f5d', '唐', '["蜀國初開棹，廬峰擬拾螢。","獸皮裁褥暖，蓮葉製衣馨。","楚水秋來碧，巫山雨後青。","莫教銜鳳詔，三度到中庭。"]', '["蜀国初开棹，廬峰擬拾螢。","獸皮裁褥暖，蓮葉製衣馨。","楚水秋来碧，巫山雨後青。","莫教銜鳳詔，三度到中庭。"]', '诗', 'shi', '', NULL, '送友人江行之廬山肄業 唐求 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d8ea906-f518-4a22-b35f-6b05155b8b32', '山居偶作', '山居偶作', '29517e7f-a2d9-44bc-beed-612087da2f5d', '唐', '["趨名逐利身，終日走風塵。","還到水邊宅，却爲山下人。","僧教開竹戶，客許戴紗巾。","且喜琴書在，蘇生未厭貧。"]', '["趨名逐利身，終日走风塵。","還到水邊宅，却爲山下人。","僧教开竹戶，客許戴紗巾。","且喜琴书在，蘇生未厭貧。"]', '诗', 'shi', '', NULL, '山居偶作 唐求 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4381aa2a-5c16-405f-aa6b-9f367b9beffc', '贈道者', '贈道者', '29517e7f-a2d9-44bc-beed-612087da2f5d', '唐', '["披霞戴鹿胎，歲月不能催。","飯把琪花煮，衣將藕葉裁。","鶴從歸日養，松是小時栽。","往往樵人見，溪邊洗藥來。"]', '["披霞戴鹿胎，歲月不能催。","飯把琪花煮，衣將藕葉裁。","鹤從归日養，松是小时栽。","往往樵人见，溪邊洗藥来。"]', '诗', 'shi', '', NULL, '贈道者 唐求 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bc3ca14-757d-4be9-9d52-ade66aa3d912', '邛州水亭夜讌送顧非熊之官', '邛州水亭夜讌送顧非熊之官', '29517e7f-a2d9-44bc-beed-612087da2f5d', '唐', '["寂寞邛城夜，寒塘對庾樓。","蜀關蟬已噪，秦樹葉應秋。","道路連天遠，笙歌到曉愁。","不堪分袂後，殘月正如鈎。"]', '["寂寞邛城夜，寒塘对庾楼。","蜀关蟬已噪，秦樹葉應秋。","道路連天远，笙歌到晓愁。","不堪分袂後，殘月正如鈎。"]', '诗', 'shi', '', NULL, '邛州水亭夜讌送顧非熊之官 唐求 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b964993-047d-4618-b4af-6b8e02b65592', '題青城山范賢觀', '題青城山范賢观', '29517e7f-a2d9-44bc-beed-612087da2f5d', '唐', '["數里緣山不厭難，爲尋真訣問黃冠。","苔鋪翠點仙橋滑，松織香梢古道寒。","晝傍綠畦薅嫩玉，夜開紅竈撚新丹。","鐘聲已斷泉聲在，風動茅花月滿壇。"]', '["數里緣山不厭难，爲尋真訣问黄冠。","苔鋪翠点仙橋滑，松织香梢古道寒。","晝傍綠畦薅嫩玉，夜开紅竈撚新丹。","鐘声已斷泉声在，风动茅花月满壇。"]', '诗', 'shi', '', NULL, '題青城山范賢觀 唐求 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cf12d7e-93e6-4c0e-ac47-fc7ccdfd4109', '送僧講罷歸山', '送僧講罷归山', '29517e7f-a2d9-44bc-beed-612087da2f5d', '唐', '["休將如意辯真空，吹盡天花任曉風。","共看玉蟾三皎潔，獨懸金錫一玲瓏。","巖間松桂秋煙白，江上樓臺晚日紅。","依舊曹溪念經處，野泉聲在草堂東。"]', '["休將如意辯真空，吹尽天花任晓风。","共看玉蟾三皎潔，独懸金錫一玲瓏。","巖间松桂秋煙白，江上楼台晚日紅。","依旧曹溪念經处，野泉声在草堂东。"]', '诗', 'shi', '', NULL, '送僧講罷歸山 唐求 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16a1792d-8510-4f93-9a39-984a2975787b', '題友人寓居', '題友人寓居', '29517e7f-a2d9-44bc-beed-612087da2f5d', '唐', '["寓居無不在天涯，莫恨秦關道路賒。","繚繞城邊山是蜀，彎環門外水名巴。","黃頭卷席賓初散，白鼻嘶風日欲斜。","何處一聲金磬發，古松南畔有僧家。"]', '["寓居無不在天涯，莫恨秦关道路賒。","繚繞城邊山是蜀，彎环门外水名巴。","黄头卷席賓初散，白鼻嘶风日欲斜。","何处一声金磬發，古松南畔有僧家。"]', '诗', 'shi', '', NULL, '題友人寓居 唐求 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44e606c8-7d4a-40c4-807e-5fd3a8bd2898', '傷張玖秀才', '傷張玖秀才', '29517e7f-a2d9-44bc-beed-612087da2f5d', '唐', '["銅梁劍閣幾區區，十上探珠不見珠。","卞玉影沈沙草闇，驊騮聲斷隴城孤。","入關詞客秋懷友，出戶孀妻曉望夫。","吳水楚山千萬里，旅魂歸到故鄉無。"]', '["銅梁劍閣幾區區，十上探珠不见珠。","卞玉影沈沙草闇，驊騮声斷隴城孤。","入关词客秋懷友，出戶孀妻晓望夫。","吳水楚山千万里，旅魂归到故乡無。"]', '诗', 'shi', '', NULL, '傷張玖秀才 唐求 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36bd761d-5aeb-4b12-8d6e-cc17a2e04da1', '題李少府別業', '題李少府別業', '29517e7f-a2d9-44bc-beed-612087da2f5d', '唐', '["尋得仙家不姓梅，馬嘶人語出塵埃。","竹和庭上春煙動，花帶溪頭曉露開。","繞岸白雲終日在，傍松黃鶴有時來。","何年亦作圍碁伴，一到松間醉一回。"]', '["尋得仙家不姓梅，马嘶人語出塵埃。","竹和庭上春煙动，花带溪头晓露开。","繞岸白云終日在，傍松黄鹤有时来。","何年亦作圍碁伴，一到松间醉一回。"]', '诗', 'shi', '', NULL, '題李少府別業 唐求 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('756e60ee-feb6-421e-8b8c-e6c3aa133259', '贈楚公', '贈楚公', '29517e7f-a2d9-44bc-beed-612087da2f5d', '唐', '["曾聞半偈雪山中，貝葉飜時理盡通。","般若恆添持戒力，落叉誰算念經功。","雲間曉月應難染，海上虛舟自信風。","長說滿庭花色好，一枝紅是一枝空。"]', '["曾闻半偈雪山中，貝葉飜时理尽通。","般若恆添持戒力，落叉誰算念經功。","云间晓月應难染，海上虛舟自信风。","长说满庭花色好，一枝紅是一枝空。"]', '诗', 'shi', '', NULL, '贈楚公 唐求 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b57dbe7f-df79-4b24-8517-500f231091c3', '贈王山人', '贈王山人', '29517e7f-a2d9-44bc-beed-612087da2f5d', '唐', '["紅藤一柱腳常輕，日日緣溪入谷行。","山下有家身未老，竈前無火藥初成。","經秋少見閑人說，帶雨多聞野鶴鳴。","知到蓬萊難再訪，問何方法得長生。"]', '["紅藤一柱腳常轻，日日緣溪入谷行。","山下有家身未老，竈前無火藥初成。","經秋少见闲人说，带雨多闻野鹤鳴。","知到蓬萊难再訪，问何方法得长生。"]', '诗', 'shi', '', NULL, '贈王山人 唐求 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b811b8d4-1290-4f1f-bdfa-2afe33279cc1', '庭竹', '庭竹', '29517e7f-a2d9-44bc-beed-612087da2f5d', '唐', '["月籠翠葉秋承露，風亞繁梢暝掃煙。","知道雪霜終不變，永留寒色在庭前。"]', '["月籠翠葉秋承露，风亞繁梢暝掃煙。","知道雪霜終不变，永留寒色在庭前。"]', '诗', 'shi', '', NULL, '庭竹 唐求 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66f32008-c660-498a-a325-a26f59bf6122', '題常樂寺', '題常乐寺', '29517e7f-a2d9-44bc-beed-612087da2f5d', '唐', '["桂冷香聞十里間，殿臺渾不似人寰。","日斜回首江頭望，一片晴雲落後山。"]', '["桂冷香闻十里间，殿台渾不似人寰。","日斜回首江头望，一片晴云落後山。"]', '诗', 'shi', '', NULL, '題常樂寺 唐求 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c87c1927-03e4-4104-97e5-f5fb54de3345', '題劉鍊師歸山', '題劉鍊師归山', '29517e7f-a2d9-44bc-beed-612087da2f5d', '唐', '["風急雲輕鶴背寒，洞天誰道却歸難。","千山萬水瀛洲路，何處煙飛是醮壇。"]', '["风急云轻鹤背寒，洞天誰道却归难。","千山万水瀛洲路，何处煙飞是醮壇。"]', '诗', 'shi', '', NULL, '題劉鍊師歸山 唐求 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9bfee45f-5958-4cfa-a8fb-42536c22acaa', '酬舒公見寄', '酬舒公见寄', '29517e7f-a2d9-44bc-beed-612087da2f5d', '唐', '["無客不言雲外見，爲文長遣世間知。","一聲松徑寒吟後，正是前山雪下時。"]', '["無客不言云外见，爲文长遣世间知。","一声松徑寒吟後，正是前山雪下时。"]', '诗', 'shi', '', NULL, '酬舒公見寄 唐求 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f643e194-522c-4420-8fe8-7f0c0e96fc81', '巫山下作', '巫山下作', '29517e7f-a2d9-44bc-beed-612087da2f5d', '唐', '["細腰宮盡舊城摧，神女歸山更不來。","唯有楚江斜日裏，至今猶自繞陽臺。"]', '["細腰宮尽旧城摧，神女归山更不来。","唯有楚江斜日裏，至今猶自繞陽台。"]', '诗', 'shi', '', NULL, '巫山下作 唐求 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19bd9a22-3b09-4240-95dd-f774dfaa08ca', '句', '句', '29517e7f-a2d9-44bc-beed-612087da2f5d', '唐', '["恰似有龍深處臥，被人驚起黑雲生。"]', '["恰似有龙深处臥，被人驚起黑云生。"]', '诗', 'shi', '', NULL, '句 唐求 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9dc6a94-5846-4660-97ee-eee857c53cb2', '書懷', '书懷', 'd3968247-e8a3-4d0d-a343-f27e74407e96', '唐', '["長安多路岐，西去欲何依。","浮世祗如此，舊山長憶歸。","自離京國久，應已故人稀。","好與孤雲住，孤雲無是非。"]', '["长安多路岐，西去欲何依。","浮世祗如此，旧山长憶归。","自離京国久，應已故人稀。","好與孤云住，孤云無是非。"]', '诗', 'shi', '', NULL, '書懷 于鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3e1fe8f-735e-4bc9-a7b6-074982db7da9', '書情', '书情', 'd3968247-e8a3-4d0d-a343-f27e74407e96', '唐', '["負郭有田在，年年長廢耕。","欲磨秋鏡淨，恐見白頭生。","未作一旬別，已過千里程。","不知書與劒，十載兩無成。"]', '["負郭有田在，年年长廢耕。","欲磨秋镜淨，恐见白头生。","未作一旬別，已過千里程。","不知书與劒，十載兩無成。"]', '诗', 'shi', '', NULL, '書情 于鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da487c90-ee19-4010-88f8-bbc55c179fa6', '塗中作', '塗中作', 'd3968247-e8a3-4d0d-a343-f27e74407e96', '唐', '["西南千里程，處處有車聲。","若使地無利，始應人不營。","天涯猶馬到，石跡尚塵生。","如此未曾息，蜀山終冀平。"]', '["西南千里程，处处有车声。","若使地無利，始應人不營。","天涯猶马到，石跡尚塵生。","如此未曾息，蜀山終冀平。"]', '诗', 'shi', '', NULL, '塗中作 于鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63cdd33b-74f3-464a-b3f4-50d562835157', '春過函谷關', '春過函谷关', 'd3968247-e8a3-4d0d-a343-f27e74407e96', '唐', '["幾度作遊客，客行長苦辛。","愁看函谷路，老盡布衣人。","歲遠關猶固，時移草亦春。","何當名利息，遣此絕征輪。"]', '["幾度作游客，客行长苦辛。","愁看函谷路，老尽布衣人。","歲远关猶固，时移草亦春。","何當名利息，遣此絕征輪。"]', '诗', 'shi', '', NULL, '春過函谷關 于鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65a46783-81db-43d0-94c8-5770f102008a', '褒中即事', '褒中即事', 'd3968247-e8a3-4d0d-a343-f27e74407e96', '唐', '["風吹殘雨歇，雲去有煙霞。","南浦足遊女，綠蘋應發花。","遠鐘當半夜，明月入千家。","不作故鄉夢，始知京洛賒。"]', '["风吹殘雨歇，云去有煙霞。","南浦足游女，綠蘋應發花。","远鐘當半夜，明月入千家。","不作故乡梦，始知京洛賒。"]', '诗', 'shi', '', NULL, '褒中即事 于鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf891f5f-857e-404c-8297-42cfbd109ff2', '歲暮還家', '歲暮還家', 'd3968247-e8a3-4d0d-a343-f27e74407e96', '唐', '["東西流不駐，白日與車輪。","殘雪半成水，微風應欲春。","幾經他國歲，已減故鄉人。","回首長安道，十年空苦辛。"]', '["东西流不駐，白日與车輪。","殘雪半成水，微风應欲春。","幾經他国歲，已減故乡人。","回首长安道，十年空苦辛。"]', '诗', 'shi', '', NULL, '歲暮還家 于鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c167e959-59e2-47cd-bfa5-b7f9eed944b1', '還家', '還家', 'd3968247-e8a3-4d0d-a343-f27e74407e96', '唐', '["爲客憶歸舍，歸來還寂寥。","壯時看欲過，白首固非遙。","獨酌幾回醉，此愁終不銷。","猶殘雞與犬，驅去住山椒。"]', '["爲客憶归舍，归来還寂寥。","壯时看欲過，白首固非遙。","独酌幾回醉，此愁終不銷。","猶殘雞與犬，驱去住山椒。"]', '诗', 'shi', '', NULL, '還家 于鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd822f79-420b-419a-83f3-54785afa28a6', '題華山麻處士所居', '題华山麻处士所居', 'd3968247-e8a3-4d0d-a343-f27e74407e96', '唐', '["貴賤各擾擾，皆逢朝市間。","到此馬無迹，始知君獨閑。","冰破聽敷水，雪晴看華山。","西風寂寥地，唯我坐忘還。"]', '["貴賤各擾擾，皆逢朝市间。","到此马無迹，始知君独闲。","冰破听敷水，雪晴看华山。","西风寂寥地，唯我坐忘還。"]', '诗', 'shi', '', NULL, '題華山麻處士所居 于鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b666abe-efd8-453c-81f2-b0f5ddddd494', '天南懷故人', '天南懷故人', 'd3968247-e8a3-4d0d-a343-f27e74407e96', '唐', '["獨行千里塵，軋軋轉征輪。","一別已多日，總看成老人。","洞庭雪不下，故國草應春。","三月煙波暖，南風生綠蘋。"]', '["独行千里塵，軋軋轉征輪。","一別已多日，總看成老人。","洞庭雪不下，故国草應春。","三月煙波暖，南风生綠蘋。"]', '诗', 'shi', '', NULL, '天南懷故人 于鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abbb3831-df36-49dc-aa97-6e01f3f6f08c', '路傍草', '路傍草', 'd3968247-e8a3-4d0d-a343-f27e74407e96', '唐', '["春至始青青，香車碾已平。","不知山下處，來向路傍生。","每歲有人在，何時無馬行。","應隨塵與土，吹滿洛陽城。"]', '["春至始青青，香车碾已平。","不知山下处，来向路傍生。","每歲有人在，何时無马行。","應隨塵與土，吹满洛陽城。"]', '诗', 'shi', '', NULL, '路傍草 于鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6b0d091-4682-4647-bca2-d21d33a57502', '秋夕聞雁', '秋夕闻雁', 'd3968247-e8a3-4d0d-a343-f27e74407e96', '唐', '["星漢欲沈盡，誰家砧未休。","忽聞梁雁至，如報杜陵秋。","千樹又黃葉，幾人新白頭。","洞庭今夜客，一半却登舟。"]', '["星漢欲沈尽，誰家砧未休。","忽闻梁雁至，如報杜陵秋。","千樹又黄葉，幾人新白头。","洞庭今夜客，一半却登舟。"]', '诗', 'shi', '', NULL, '秋夕聞雁 于鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b24b34e-734d-4d15-8790-40fc09cbe238', '洛中有懷', '洛中有懷', 'd3968247-e8a3-4d0d-a343-f27e74407e96', '唐', '["潺潺伊洛河，寂寞少恩波。","鑾駕久不幸，洛陽春草多。"]', '["潺潺伊洛河，寂寞少恩波。","鑾駕久不幸，洛陽春草多。"]', '诗', 'shi', '', NULL, '洛中有懷 于鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04ba30d8-a51c-4479-b40b-4c88c8d72071', '送魏山韋處士', '送魏山韋处士', 'd3968247-e8a3-4d0d-a343-f27e74407e96', '唐', '["陰陰亭際間，相顧慘離顏。","一片雲飛去，嵯峨空魏山。"]', '["陰陰亭際间，相顧慘離顏。","一片云飞去，嵯峨空魏山。"]', '诗', 'shi', '', NULL, '送魏山韋處士 于鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ceddbc9d-6574-4028-9469-dcb81df4092a', '白櫻桃', '白櫻桃', 'd3968247-e8a3-4d0d-a343-f27e74407e96', '唐', '["王母階前種幾株，水晶簾內看如無。","只應漢武金盤上，瀉得珊珊白露珠。"]', '["王母階前種幾株，水晶簾內看如無。","只應漢武金盤上，瀉得珊珊白露珠。"]', '诗', 'shi', '', NULL, '白櫻桃 于鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2eada0df-407f-438f-a37d-e61c50d3c0dc', '白櫻樹', '白櫻樹', 'd3968247-e8a3-4d0d-a343-f27e74407e96', '唐', '["記得花開雪滿枝，和蜂和蝶帶花移。","如今花落遊蜂去，空作主人惆悵詩。"]', '["記得花开雪满枝，和蜂和蝶带花移。","如今花落游蜂去，空作主人惆悵诗。"]', '诗', 'shi', '', NULL, '白櫻樹 于鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('588784ae-fa8a-41af-acbe-0cd53327aeaf', '下第不勝其忿題路左佛廟', '下第不勝其忿題路左佛廟', 'd3968247-e8a3-4d0d-a343-f27e74407e96', '唐', '["雀兒未逐颺風高，下視鷹鸇意氣豪。","自謂能生千里足，黃昏依舊委蓬蒿。"]', '["雀兒未逐颺风高，下視鷹鸇意氣豪。","自謂能生千里足，黄昏依旧委蓬蒿。"]', '诗', 'shi', '', NULL, '下第不勝其忿題路左佛廟 于鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1853651-08d4-40fa-b598-18f316d63cbb', '感懷', '感懷', 'd3968247-e8a3-4d0d-a343-f27e74407e96', '唐', '["東風吹草色，空使客蹉跎。","不設太平險，更應遊子多。","幾傷行處淚，一曲醉中歌。","盡向青門外，東隨渭水波。"]', '["东风吹草色，空使客蹉跎。","不設太平險，更應游子多。","幾傷行处泪，一曲醉中歌。","尽向青门外，东隨渭水波。"]', '诗', 'shi', '', NULL, '感懷 于鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddc3beab-051a-4dae-9f5b-3304bc310423', '遊中梁山', '游中梁山', 'd3968247-e8a3-4d0d-a343-f27e74407e96', '唐', '["僻地好泉石，何人曾陸沈。","不知青嶂外，更有白雲深。","因此見喬木，幾回思舊林。","殷勤猨與鳥，唯我獨何心。"]', '["僻地好泉石，何人曾陸沈。","不知青嶂外，更有白云深。","因此见喬木，幾回思旧林。","殷勤猨與鸟，唯我独何心。"]', '诗', 'shi', '', NULL, '遊中梁山 于鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08193479-272f-47bb-957a-6f74a4fb7e7a', '尋山', '尋山', 'd3968247-e8a3-4d0d-a343-f27e74407e96', '唐', '["到此絕車輪，萋萋草樹春。","青山如有利，白石亦成塵。","水闊應無路，松深不見人。","如知巢與許，千載迹猶新。"]', '["到此絕车輪，萋萋草樹春。","青山如有利，白石亦成塵。","水闊應無路，松深不见人。","如知巢與許，千載迹猶新。"]', '诗', 'shi', '', NULL, '尋山 于鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa9fa888-1dfd-4b78-93e3-cd155dddf3e9', '宿江口', '宿江口', 'd3968247-e8a3-4d0d-a343-f27e74407e96', '唐', '["南渡人來絕，喧喧雁滿沙。","自生江上月，長有客思家。","半夜下霜岸，北風吹荻花。","自驚歸夢斷，不得到天涯。"]', '["南渡人来絕，喧喧雁满沙。","自生江上月，长有客思家。","半夜下霜岸，北风吹荻花。","自驚归梦斷，不得到天涯。"]', '诗', 'shi', '', NULL, '宿江口 于鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26899957-16a6-43b4-b70e-7bfbb254b686', '秋夜達蕭關', '秋夜達蕭关', 'd3968247-e8a3-4d0d-a343-f27e74407e96', '唐', '["擾擾浮梁路，人忙月自閑。","去年爲塞客，今夜宿蕭關。","辭國幾經歲，望鄉空見山。","不知江葉下，又作布衣還。"]', '["擾擾浮梁路，人忙月自闲。","去年爲塞客，今夜宿蕭关。","辞国幾經歲，望乡空见山。","不知江葉下，又作布衣還。"]', '诗', 'shi', '', NULL, '秋夜達蕭關 于鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68b97b04-7b2d-4e1f-a271-f0b0ac137f13', '斜谷道', '斜谷道', 'd3968247-e8a3-4d0d-a343-f27e74407e96', '唐', '["亂峰連疊嶂，千里綠峨峨。","蜀國路如此，遊人車亦過。","遠煙當驛歛，驟雨逐風多。","獨憶紫芝叟，臨風歌舊歌。"]', '["亂峰連叠嶂，千里綠峨峨。","蜀国路如此，游人车亦過。","远煙當驛歛，驟雨逐风多。","独憶紫芝叟，臨风歌旧歌。"]', '诗', 'shi', '', NULL, '斜谷道 于鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59d82cdd-7383-472a-bf5d-936e788aa9ee', '過百牢關貽舟中者', '過百牢关貽舟中者', 'd3968247-e8a3-4d0d-a343-f27e74407e96', '唐', '["蜀國少平地，方思京洛間。","遠爲千里客，來度百牢關。","帆影清江水，鈴聲碧草山。","不因名與利，爾我各應閑。"]', '["蜀国少平地，方思京洛间。","远爲千里客，来度百牢关。","帆影清江水，鈴声碧草山。","不因名與利，爾我各應闲。"]', '诗', 'shi', '', NULL, '過百牢關貽舟中者 于鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fd9a554-119c-456a-8d4e-b52a5b460163', '客中覽鏡', '客中覽镜', 'd3968247-e8a3-4d0d-a343-f27e74407e96', '唐', '["何當開此鏡，即見髮如絲。","白日急於水，少年能幾時。","每逢芳草處，長返故園遲。","所以多爲客，蹉跎欲怨誰。"]', '["何當开此镜，即见髮如絲。","白日急於水，少年能幾时。","每逢芳草处，长返故园遲。","所以多爲客，蹉跎欲怨誰。"]', '诗', 'shi', '', NULL, '客中覽鏡 于鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc66f4d6-2055-40bf-9904-97b02c59ff9c', '長安逢隱者', '长安逢隐者', 'd3968247-e8a3-4d0d-a343-f27e74407e96', '唐', '["征車千里至，碾遍六街塵。","向此有營地，忽逢無事人。","昔時顏未改，浮世路多新。","且脫衣沽酒，終南山欲春。"]', '["征车千里至，碾遍六街塵。","向此有營地，忽逢無事人。","昔时顏未改，浮世路多新。","且脫衣沽酒，終南山欲春。"]', '诗', 'shi', '', NULL, '長安逢隱者 于鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93b4e474-c248-4da8-a1c1-e02c989b0d19', '與僧話舊', '與僧話旧', 'd3968247-e8a3-4d0d-a343-f27e74407e96', '唐', '["草堂前有山，一見一相寬。","處世貴僧靜，青松因歲寒。","他山逢舊侶，盡日話長安。","所以閑行迹，千回繞藥欄。"]', '["草堂前有山，一见一相寬。","处世貴僧静，青松因歲寒。","他山逢旧侶，尽日話长安。","所以闲行迹，千回繞藥欄。"]', '诗', 'shi', '', NULL, '與僧話舊 于鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8ac4222-39b9-48fe-9538-8556c1b08b37', '贈王道士', '贈王道士', 'd3968247-e8a3-4d0d-a343-f27e74407e96', '唐', '["日日市朝路，何時無苦辛。","不隨丹竈客，終作白頭人。","浮世度千載，桃源方一春。","歸來華表上，應笑北邙塵。"]', '["日日市朝路，何时無苦辛。","不隨丹竈客，終作白头人。","浮世度千載，桃源方一春。","归来华表上，應笑北邙塵。"]', '诗', 'shi', '', NULL, '贈王道士 于鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55fd32fd-5072-4a24-8ca1-f51307259da7', '匣中琴', '匣中琴', 'd3968247-e8a3-4d0d-a343-f27e74407e96', '唐', '["世人無正心，蟲網匣中琴。","何以經時廢，非爲娛耳音。","獨令高韻在，誰感隙塵深。","應是南風曲，聲聲不合今。"]', '["世人無正心，蟲網匣中琴。","何以經时廢，非爲娛耳音。","独令高韻在，誰感隙塵深。","應是南风曲，声声不合今。"]', '诗', 'shi', '', NULL, '匣中琴 于鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('183ffb29-cb99-4eb4-b349-db564ff8bd07', '友人亭松', '友人亭松', 'd3968247-e8a3-4d0d-a343-f27e74407e96', '唐', '["俛仰不能去，如逢舊友同。","曾因春雪散，見在華山中。","何處有明月，訪君聽遠風。","相將歸未得，各占石巖東。"]', '["俛仰不能去，如逢旧友同。","曾因春雪散，见在华山中。","何处有明月，訪君听远风。","相將归未得，各占石巖东。"]', '诗', 'shi', '', NULL, '友人亭松 于鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('099c09a3-9bb4-46ac-b077-d3a47d03535d', '過洛陽城', '過洛陽城', 'd3968247-e8a3-4d0d-a343-f27e74407e96', '唐', '["古來利與名，俱在洛陽城。","九陌鼓初起，萬車輪已行。","周秦時幾變，伊洛水猶清。","二月中橋路，鳥啼春草生。"]', '["古来利與名，俱在洛陽城。","九陌鼓初起，万车輪已行。","周秦时幾变，伊洛水猶清。","二月中橋路，鸟啼春草生。"]', '诗', 'shi', '', NULL, '過洛陽城 于鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('639fd58e-c0f9-4265-9fd9-2cd235fbd687', '客中月', '客中月', 'd3968247-e8a3-4d0d-a343-f27e74407e96', '唐', '["離家凡幾宵，一望一寥寥。","新魄又將滿，故鄉應漸遙。","獨臨彭蠡水，遠憶洛陽橋。","更有乘舟客，悽然亦駐橈。"]', '["離家凡幾宵，一望一寥寥。","新魄又將满，故乡應漸遙。","独臨彭蠡水，远憶洛陽橋。","更有乘舟客，悽然亦駐橈。"]', '诗', 'shi', '', NULL, '客中月 于鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67e13b0a-1a45-46d7-a52f-78a8aaf58fe6', '王將軍宅夜聽歌', '王將軍宅夜听歌', 'd3968247-e8a3-4d0d-a343-f27e74407e96', '唐', '["朱檻滿明月，美人歌落梅。","忽驚塵起處，疑有鳳飛來。","一曲聽初徹，幾年愁暫開。","東南正雲雨，不得見陽臺。"]', '["朱檻满明月，美人歌落梅。","忽驚塵起处，疑有鳳飞来。","一曲听初徹，幾年愁暫开。","东南正云雨，不得见陽台。"]', '诗', 'shi', '', NULL, '王將軍宅夜聽歌 于鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9dc949de-547f-45b8-a234-65c047ecdc85', '長信宮', '长信宮', 'd3968247-e8a3-4d0d-a343-f27e74407e96', '唐', '["莫問古宮名，古宮空有城。","惟應東去水，不改舊時聲。"]', '["莫问古宮名，古宮空有城。","惟應东去水，不改旧时声。"]', '诗', 'shi', '', NULL, '長信宮 于鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e19c7d1-484a-4a7f-b9d0-9ff2e278aa15', '高樓', '高楼', 'd3968247-e8a3-4d0d-a343-f27e74407e96', '唐', '["遠天明月出，照此誰家樓。","上有羅衣裳，涼風吹不休。"]', '["远天明月出，照此誰家楼。","上有羅衣裳，涼风吹不休。"]', '诗', 'shi', '', NULL, '高樓 于鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad3af8c3-05b7-4885-a66b-41699c3ebd5c', '和三鄉詩', '和三乡诗', '9486f5e2-1790-409d-b82b-333e1b4959db', '唐', '["惆悵殘花怨暮春，孤鸞舞鏡倍傷神。","清詞好箇干人事，疑是文姬第二身。"]', '["惆悵殘花怨暮春，孤鸾舞镜倍傷神。","清词好箇干人事，疑是文姬第二身。"]', '诗', 'shi', '', NULL, '和三鄉詩 陸貞洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95491a87-d014-4d63-860e-5c1d2a5b11d7', '和三鄉詩', '和三乡诗', '161e961e-1cac-44d3-b244-4cd0e1844fec', '唐', '["蘭蕙芬香見玉姿，路傍花笑景遲遲。","苧蘿山下無窮意，併在三鄉惜別時。"]', '["蘭蕙芬香见玉姿，路傍花笑景遲遲。","苧蘿山下無窮意，併在三乡惜別时。"]', '诗', 'shi', '', NULL, '和三鄉詩 劉谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7ae520d-6134-4fb8-9385-702c5c2a2797', '和三鄉詩', '和三乡诗', 'd76a75b8-a7a5-4053-a7de-edc122f22328', '唐', '["女几山前嵐氣低，佳人留恨此中題。","不知雲雨歸何處，空使王孫見即迷。"]', '["女几山前嵐氣低，佳人留恨此中題。","不知云雨归何处，空使王孫见即迷。"]', '诗', 'shi', '', NULL, '和三鄉詩 王祝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('829abc29-6788-44e0-86b8-31e772fe877e', '和三鄉詩', '和三乡诗', '661fd5de-df6f-42f7-aeea-2153f0d62c1e', '唐', '["浣紗游女出關東，舊跡新詞一夢中。","槐陌柳亭何限事，年年迴首向春風。"]', '["浣紗游女出关东，旧跡新词一梦中。","槐陌柳亭何限事，年年迴首向春风。"]', '诗', 'shi', '', NULL, '和三鄉詩 王滌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83a8c92c-5c97-469b-a2aa-e1c411934cf0', '和三鄉詩', '和三乡诗', 'e2c4492c-a496-4767-b192-e9a2df3da1a9', '唐', '["來時歡笑去時哀，家國迢迢向越臺。","待寫百年幽思盡，故宮流水莫相催。"]', '["来时歡笑去时哀，家国迢迢向越台。","待寫百年幽思尽，故宮流水莫相催。"]', '诗', 'shi', '', NULL, '和三鄉詩 韋冰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69cd0bcd-9e58-4660-a48e-e5ee47e62232', '和三鄉詩', '和三乡诗', 'c87cc1be-1302-4211-8adc-5514b8b1eb91', '唐', '["紅粉蕭娘手自題，分明幽怨發雲閨。","不應更學文君去，泣向殘花歸剡溪。"]', '["紅粉蕭娘手自題，分明幽怨發云閨。","不應更学文君去，泣向殘花归剡溪。"]', '诗', 'shi', '', NULL, '和三鄉詩 李昌鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10ddafb1-fd9a-42a2-82c4-16e28862cde8', '和三鄉詩', '和三乡诗', 'a2c7761f-ee57-4e36-9c5c-e3936bafccf7', '唐', '["無姓無名越水濱，芳詞空怨路傍人。","莫教才子偏惆悵，宋玉東家是舊鄰。"]', '["無姓無名越水濱，芳词空怨路傍人。","莫教才子偏惆悵，宋玉东家是旧鄰。"]', '诗', 'shi', '', NULL, '和三鄉詩 王碩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b91a62c4-c64c-47c6-8793-7d6f63b042d0', '和三鄉詩', '和三乡诗', '96bb618a-6d33-49a8-8704-b78095607c1f', '唐', '["會稽王謝兩風流，王子沉淪謝女愁。","歸思若隨文字在，路傍空爲感千秋。"]', '["會稽王謝兩风流，王子沉淪謝女愁。","归思若隨文字在，路傍空爲感千秋。"]', '诗', 'shi', '', NULL, '和三鄉詩 李縞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36bdfe34-1016-4b81-98fe-865c009ace28', '和三鄉詩', '和三乡诗', '5336a9e9-56c5-4596-83c1-a067f647d112', '唐', '["洛川依舊好風光，蓮帳無因見女郎。","雲雨散來音信斷，此生遺恨寄三鄉。"]', '["洛川依旧好风光，蓮帳無因见女郎。","云雨散来音信斷，此生遺恨寄三乡。"]', '诗', 'shi', '', NULL, '和三鄉詩 張綺 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f65d3d26-cc34-49cd-b3c4-ac2fa4b23d30', '和三鄉詩', '和三乡诗', '9d7714fc-0717-4706-9c4e-86023dcaa745', '唐', '["南北千山與萬山，軒車誰不思鄉關。","獨留芳翰悲前跡，陌上恐傷桃李顏。"]', '["南北千山與万山，軒车誰不思乡关。","独留芳翰悲前跡，陌上恐傷桃李顏。"]', '诗', 'shi', '', NULL, '和三鄉詩 高衢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93b3e72f-b22b-45ef-bd9c-0132e993f46a', '復覩三鄉題處留贈', '复覩三乡題处留贈', 'd93add19-48bd-4978-b27c-0501386290fb', '唐', '["壁古字未滅，聲長響不絕。","蕙質本如雲，松心應耐雪。","耿耿離幽谷，悠悠望甌越。","杞婦哭夫時，城崩無此說。"]', '["壁古字未滅，声长响不絕。","蕙質本如云，松心應耐雪。","耿耿離幽谷，悠悠望甌越。","杞婦哭夫时，城崩無此说。"]', '诗', 'shi', '', NULL, '復覩三鄉題處留贈 賈馳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3665e325-1fcd-40f3-961d-b7c7b68c4c33', '秋入關', '秋入关', 'd93add19-48bd-4978-b27c-0501386290fb', '唐', '["河上微風來，關頭樹初濕。","今朝關城吏，又見孤客入。","上國誰與期，西來徒自急。"]', '["河上微风来，关头樹初濕。","今朝关城吏，又见孤客入。","上国誰與期，西来徒自急。"]', '诗', 'shi', '', NULL, '秋入關 賈馳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bef7931-3bf4-446d-b637-f6049fae28d3', '詠手二首 一', '詠手二首 一', '951a13ee-0997-4944-b538-47c7eac1e896', '唐', '["妝成皓腕洗凝脂，背接紅巾掬水時。","薄霧袖中拈玉斝，斜陽屏上撚青絲。","喚人急拍臨前檻，摘杏高揎近曲池。","好是琵琶弦畔見，細圓無節玉參差。"]', '["妝成皓腕洗凝脂，背接紅巾掬水时。","薄霧袖中拈玉斝，斜陽屏上撚青絲。","喚人急拍臨前檻，摘杏高揎近曲池。","好是琵琶弦畔见，細圓無節玉參差。"]', '诗', 'shi', '', NULL, '詠手二首 一 趙光遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a774e867-f248-4c5f-a140-df0b32839c61', '詠手二首 二', '詠手二首 二', '951a13ee-0997-4944-b538-47c7eac1e896', '唐', '["撚玉搓瓊軟復圓，綠窗誰見上琴弦。","慢籠彩筆閑書字，斜指瑤階笑打錢。","爐面試香添麝炷，舌頭輕點貼金鈿。","象床珍簟宮棊處，拈定文楸占角邊。"]', '["撚玉搓瓊軟复圓，綠窗誰见上琴弦。","慢籠彩笔闲书字，斜指瑤階笑打錢。","爐面試香添麝炷，舌头轻点貼金鈿。","象床珍簟宮棊处，拈定文楸占角邊。"]', '诗', 'shi', '', NULL, '詠手二首 二 趙光遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4578241-d9e5-4888-ab93-c6fa3ec86431', '題妓萊兒壁', '題妓萊兒壁', '951a13ee-0997-4944-b538-47c7eac1e896', '唐', '["魚鑰獸環斜掩門，萋萋芳草憶王孫。","醉凭青瑣窺韓壽，閑擲金梭惱謝鯤。","不夜珠光連玉匣，辟寒釵影落瑤尊。","欲知腸斷相思處，役盡江淹別後魂。"]', '["鱼鑰獸环斜掩门，萋萋芳草憶王孫。","醉凭青瑣窺韓壽，闲擲金梭惱謝鯤。","不夜珠光連玉匣，辟寒釵影落瑤尊。","欲知腸斷相思处，役尽江淹別後魂。"]', '诗', 'shi', '', NULL, '題妓萊兒壁 趙光遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51e55e97-cc29-4408-9fd9-0b20e8c54581', '題興化高田院橋亭', '題兴化高田院橋亭', '25fd2674-536c-4882-90f3-2399d34f940e', '唐', '["到此溪亭上，浮生始覺非。","野僧還惜別，遊客亦忘歸。","月滿千巖靜，風清一磬微。","何時脫塵役，杖履願相依。"]', '["到此溪亭上，浮生始覺非。","野僧還惜別，游客亦忘归。","月满千巖静，风清一磬微。","何时脫塵役，杖履願相依。"]', '诗', 'shi', '', NULL, '題興化高田院橋亭 鄭良士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0bd4e597-795c-45a5-8258-72651344594d', '遊九鯉湖', '游九鯉湖', '25fd2674-536c-4882-90f3-2399d34f940e', '唐', '["仄徑傾崖不可通，湖嵐林靄共溟濛。","九溪瀑影飛花外，萬樹春聲細雨中。","覆石雲閑丹竈冷，採芝人去洞門空。","我來不乞邯鄲夢，取醉聊乘鄭國風。"]', '["仄徑傾崖不可通，湖嵐林靄共溟濛。","九溪瀑影飞花外，万樹春声細雨中。","覆石云闲丹竈冷，採芝人去洞门空。","我来不乞邯鄲梦，取醉聊乘鄭国风。"]', '诗', 'shi', '', NULL, '遊九鯉湖 鄭良士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a29a695-ed4c-4f31-969e-065c44a57532', '寄富洋院禪者', '寄富洋院禪者', '25fd2674-536c-4882-90f3-2399d34f940e', '唐', '["畫破青山路一條，走鞭飛蓋去何遙。","礙天巖樹春先冷，鎖院溪雲晝不銷。","霅上茗芽因客煮，海南沈屑爲齋燒。","誰能學得空門士，冷却心灰守寂寥。"]', '["畫破青山路一條，走鞭飞蓋去何遙。","礙天巖樹春先冷，鎖院溪云晝不銷。","霅上茗芽因客煮，海南沈屑爲斋燒。","誰能学得空门士，冷却心灰守寂寥。"]', '诗', 'shi', '', NULL, '寄富洋院禪者 鄭良士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('495ddb3b-e0bf-4f23-bf28-10a78951b1ce', '贈翁承贊漆林書堂詩', '贈翁承贊漆林书堂诗', 'd8031b0a-fc44-4829-b850-5fa55e0a046c', '唐', '["軺車故國世應稀，昔日書堂二紀歸。","手植松筠同茂盛，身榮金紫倍光輝。","入門鄰里喧迎接，列坐兒童見等威。","却對芸窗勤苦處，舉頭全是錦爲衣。"]', '["軺车故国世應稀，昔日书堂二紀归。","手植松筠同茂盛，身榮金紫倍光輝。","入门鄰里喧迎接，列坐兒童见等威。","却对芸窗勤苦处，舉头全是錦爲衣。"]', '诗', 'shi', '', NULL, '贈翁承贊漆林書堂詩 蕭項 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e916c79a-369a-4b15-b5d6-ed208f445ed6', '喜韓少府見訪', '喜韓少府见訪', '75ee7d1c-5555-401f-9f15-9b993a0c4531', '唐', '["忽聞梅福來相訪，笑著荷衣出草堂。","兒童不慣見車馬，走入蘆花深處藏。"]', '["忽闻梅福来相訪，笑著荷衣出草堂。","兒童不慣见车马，走入蘆花深处藏。"]', '诗', 'shi', '', NULL, '喜韓少府見訪 胡令能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c740ff6c-2a8d-4d11-9a7e-9e699c7c7998', '觀鄭州崔郎中諸妓繡樣', '观鄭州崔郎中諸妓繡樣', '75ee7d1c-5555-401f-9f15-9b993a0c4531', '唐', '["日暮堂前花蘂嬌，爭拈小筆上牀描。","繡成安向春園裏，引得黃鶯下柳條。"]', '["日暮堂前花蘂嬌，爭拈小笔上牀描。","繡成安向春园裏，引得黄鶯下柳條。"]', '诗', 'shi', '', NULL, '觀鄭州崔郎中諸妓繡樣 胡令能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('055f52cc-4e4b-4ee3-8e4b-737805cb3d6e', '小兒垂釣', '小兒垂釣', '75ee7d1c-5555-401f-9f15-9b993a0c4531', '唐', '["蓬頭穉子學垂綸，側坐莓苔草映身。","路人借問遙招手，怕得魚驚不應人。"]', '["蓬头穉子学垂綸，側坐莓苔草映身。","路人借问遙招手，怕得鱼驚不應人。"]', '诗', 'shi', '', NULL, '小兒垂釣 胡令能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cea26d6c-4b88-4982-a31b-f01aead537e6', '王昭君', '王昭君', '75ee7d1c-5555-401f-9f15-9b993a0c4531', '唐', '["胡風似劒鎪人骨，漢月如鉤釣胃腸。","魂夢不知身在路，夜來猶自到昭陽。"]', '["胡风似劒鎪人骨，漢月如鉤釣胃腸。","魂梦不知身在路，夜来猶自到昭陽。"]', '诗', 'shi', '', NULL, '王昭君 胡令能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5aebf25-2856-431d-9897-3aff171a421d', '望夫石', '望夫石', 'c7dc7050-cf3e-48dd-9a67-2881f80c8cf0', '唐', '["何代提戈去不還，獨留形影白雲間。","肌膚銷盡雪霜色，羅綺點成苔蘚斑。","江燕不能傳遠信，野花空解妬愁顏。","近來豈少征人婦，笑採蘼蕪上北山。"]', '["何代提戈去不還，独留形影白云间。","肌膚銷尽雪霜色，羅綺点成苔蘚斑。","江燕不能傳远信，野花空解妬愁顏。","近来豈少征人婦，笑採蘼蕪上北山。"]', '诗', 'shi', '', NULL, '望夫石 嚴郾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c08a4113-c425-410f-9e0c-a7c3711d167a', '賦百舌鳥', '賦百舌鸟', 'c7dc7050-cf3e-48dd-9a67-2881f80c8cf0', '唐', '["此禽輕巧少同倫，我聽長疑舌滿身。","星未沒河先報曉，柳猶黏雪便迎春。","頻嫌海燕巢難定，却訝林鶯語不真。","莫倚春風便多事，玉樓還有晏眠人。"]', '["此禽轻巧少同倫，我听长疑舌满身。","星未沒河先報晓，柳猶黏雪便迎春。","頻嫌海燕巢难定，却訝林鶯語不真。","莫倚春风便多事，玉楼還有晏眠人。"]', '诗', 'shi', '', NULL, '賦百舌鳥 嚴郾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0579224a-aac4-430f-be7e-2067f8718d03', '永州陪鄭太守登舟夜宴席上各賦詩', '永州陪鄭太守登舟夜宴席上各賦诗', '76e2ba6b-6a1e-4967-9dbc-9e1b49c1311f', '唐', '["江頭朱紱間青衿，豈是仙舟不可尋。","誰敢強登徐稚榻，自憐還學謝安吟。","月凝蘭櫂輕風起，妓勸金罍盡醉斟。","剪盡蠟紅人未覺，歸時城郭曉煙深。"]', '["江头朱紱间青衿，豈是仙舟不可尋。","誰敢強登徐稚榻，自怜還学謝安吟。","月凝蘭櫂轻风起，妓勸金罍尽醉斟。","剪尽蠟紅人未覺，归时城郭晓煙深。"]', '诗', 'shi', '', NULL, '永州陪鄭太守登舟夜宴席上各賦詩 蔣肱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f251a6c0-e594-4095-8c07-9ce9024a2bf6', '寄遠', '寄远', '15d72ce1-b187-45bc-8786-5e337bce9a24', '唐', '["錦字憑誰達，閑庭草又枯。","夜長燈影滅，天遠雁聲孤。","蟬鬢凋將盡，虬髯白也無。","幾回愁不語，因看朔方圖。"]', '["錦字憑誰達，闲庭草又枯。","夜长灯影滅，天远雁声孤。","蟬鬢凋將尽，虬髯白也無。","幾回愁不語，因看朔方圖。"]', '诗', 'shi', '', NULL, '寄遠 張逈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bd75875-20ad-4b0c-8e73-948d5f282e4b', '春草凝露', '春草凝露', 'f8397495-6732-48a6-9545-c3daac1197c0', '唐', '["蒼蒼芳草色，含露對青春。","已賴陽和長，仍慙潤澤頻。","日臨殘未滴，風度欲成津。","蕙葉垂偏重，蘭叢洗轉新。","將行愁裛逕，欲采畏濡身。","獨愛池塘畔，清華遠襲人。"]', '["蒼蒼芳草色，含露对青春。","已賴陽和长，仍慙潤澤頻。","日臨殘未滴，风度欲成津。","蕙葉垂偏重，蘭叢洗轉新。","將行愁裛逕，欲采畏濡身。","独愛池塘畔，清华远襲人。"]', '诗', 'shi', '', NULL, '春草凝露 張友正 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8162fe87-00b8-44fc-b2f4-1d27e0019246', '錦帶佩吳鉤', '錦带佩吳鉤', 'f8397495-6732-48a6-9545-c3daac1197c0', '唐', '["帶劒誰家子，春朝紫陌遊。","結邊霞聚錦，懸處月隨鉤。","綵縷迴文出，雄芒練影浮。","葉依花裏豔，霜向鍔中秋。","的皪宜驄馬，斕斒映綺裘。","應須待報國，一刎月支頭。"]', '["带劒誰家子，春朝紫陌游。","結邊霞聚錦，懸处月隨鉤。","綵縷迴文出，雄芒練影浮。","葉依花裏豔，霜向鍔中秋。","的皪宜驄马，斕斒映綺裘。","應須待報国，一刎月支头。"]', '诗', 'shi', '', NULL, '錦帶佩吳鉤 張友正 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b3cb41e-72c6-4d91-af6a-cbc0c2e32d4d', '山中臥寄盧郎中', '山中臥寄盧郎中', '31d17fc6-d9bd-4226-a85b-398e638010d1', '唐', '["十年耕釣水雲間，住僻家貧少往還。","一徑綠苔凝曉露，滿頭白髮對青山。","野僧採藥來醫病，樵客攜觴爲解顏。","空戀舊時恩獎地，無因匍匐出柴關。"]', '["十年耕釣水云间，住僻家貧少往還。","一徑綠苔凝晓露，满头白髮对青山。","野僧採藥来醫病，樵客携觴爲解顏。","空戀旧时恩獎地，無因匍匐出柴关。"]', '诗', 'shi', '', NULL, '山中臥寄盧郎中 伍唐珪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6163908f-5c01-47d1-b46c-0f61a2b28717', '寒食日獻郡守', '寒食日獻郡守', '31d17fc6-d9bd-4226-a85b-398e638010d1', '唐', '["入門堪笑復堪憐，三徑苔荒一釣船。","慙愧四隣教斷火，不知廚裏久無煙。"]', '["入门堪笑复堪怜，三徑苔荒一釣船。","慙愧四隣教斷火，不知廚裏久無煙。"]', '诗', 'shi', '', NULL, '寒食日獻郡守 伍唐珪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2b0119e-9bd7-4b5b-b453-2fdf81f79c77', '上蘇使君', '上蘇使君', '31d17fc6-d9bd-4226-a85b-398e638010d1', '唐', '["江西昔日推韓注，袁水今朝數趙祥。","縱使文翁能待客，終栽桃李不成行。"]', '["江西昔日推韓注，袁水今朝數趙祥。","縱使文翁能待客，終栽桃李不成行。"]', '诗', 'shi', '', NULL, '上蘇使君 伍唐珪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4219be47-4add-40a6-9eff-bd78b2d028e0', '贈妓人王福娘', '贈妓人王福娘', 'f3d7fa26-3950-4615-9d8b-5482a32e4fe9', '唐', '["綵翠仙衣紅玉膚，輕盈年在破瓜初。","霞杯醉勸劉郎賭，雲髻慵邀阿母梳。","不怕寒侵緣帶寶，每憂風舉倩持裾。","謾圖西子晨粧樣，西子元來未得如。"]', '["綵翠仙衣紅玉膚，轻盈年在破瓜初。","霞杯醉勸劉郎賭，云髻慵邀阿母梳。","不怕寒侵緣带寶，每憂风舉倩持裾。","謾圖西子晨粧樣，西子元来未得如。"]', '诗', 'shi', '', NULL, '贈妓人王福娘 孫棨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67690f1a-568e-4837-be62-689fdb9cb58c', '題妓王福娘墻 一', '題妓王福娘墻 一', 'f3d7fa26-3950-4615-9d8b-5482a32e4fe9', '唐', '["移壁迴窗費幾朝，指鐶偷解博紅椒。","無端鬬草輸鄰女，更被拈將玉步搖。"]', '["移壁迴窗費幾朝，指鐶偷解博紅椒。","無端鬬草輸鄰女，更被拈將玉步搖。"]', '诗', 'shi', '', NULL, '題妓王福娘墻 一 孫棨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a55c2233-1ef7-4b7c-bd37-20f801d512b9', '題妓王福娘墻 二', '題妓王福娘墻 二', 'f3d7fa26-3950-4615-9d8b-5482a32e4fe9', '唐', '["寒繡衣裳餉阿嬌，新團香獸不禁燒。","東鄰起樣裙腰闊，剩蹙黃金線幾條。"]', '["寒繡衣裳餉阿嬌，新團香獸不禁燒。","东鄰起樣裙腰闊，剩蹙黄金線幾條。"]', '诗', 'shi', '', NULL, '題妓王福娘墻 二 孫棨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9858abdb-024f-4c4d-819a-722b227e8a1f', '題妓王福娘墻 三', '題妓王福娘墻 三', 'f3d7fa26-3950-4615-9d8b-5482a32e4fe9', '唐', '["試共卿卿語笑初，畫堂連遣侍兒呼。","寒肌不耐金如意，白獺爲膏郎有無。"]', '["試共卿卿語笑初，畫堂連遣侍兒呼。","寒肌不耐金如意，白獺爲膏郎有無。"]', '诗', 'shi', '', NULL, '題妓王福娘墻 三 孫棨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b58bfa5-9a3a-4d93-aa01-1a3a7f2e6d0e', '戲李文遠', '戲李文远', 'f3d7fa26-3950-4615-9d8b-5482a32e4fe9', '唐', '["引君來訪洞中仙，新月如眉拂戶前。","領取嫦娥攀取桂，便從陵谷一時遷。"]', '["引君来訪洞中仙，新月如眉拂戶前。","領取嫦娥攀取桂，便從陵谷一时遷。"]', '诗', 'shi', '', NULL, '戲李文遠 孫棨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57d46fc4-2e0f-453d-86fc-5b23af5b4497', '題劉泰娘舍', '題劉泰娘舍', 'f3d7fa26-3950-4615-9d8b-5482a32e4fe9', '唐', '["尋常凡木最輕樗，今日尋樗桂不如。","漢高新破咸陽後，英俊奔波遂喫虛。"]', '["尋常凡木最轻樗，今日尋樗桂不如。","漢高新破咸陽後，英俊奔波遂喫虛。"]', '诗', 'shi', '', NULL, '題劉泰娘舍 孫棨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dafcc512-e764-422d-9b9a-e6f12ef1b23b', '戲張道人不飲酒', '戲張道人不饮酒', '4db1b283-739c-47bb-af2e-f339ae18568d', '唐', '["言自雲山訪我來，每聞奇秘覺叨陪。","吾師不飲人間酒，應待流霞即舉杯。"]', '["言自云山訪我来，每闻奇秘覺叨陪。","吾師不饮人间酒，應待流霞即舉杯。"]', '诗', 'shi', '', NULL, '戲張道人不飲酒 顏蕘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e32e0433-911d-4e9e-b834-0102f4fc02b5', '句', '句', '4db1b283-739c-47bb-af2e-f339ae18568d', '唐', '["爽籟盡成鳴鳳曲，遊人多是弄珠仙。"]', '["爽籟尽成鳴鳳曲，游人多是弄珠仙。"]', '诗', 'shi', '', NULL, '句 顏蕘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88ee9037-f145-4538-8397-f1e8b1cce4c5', '秋醉歌', '秋醉歌', 'd482da05-63a3-40a5-b2f7-918501a6ae86', '唐', '["金風颯已起，還是招漁翁。","攜酒天姥岑，自彈嶧陽桐。","脫却登山履，赤脚翹青筇。","泉聲掃殘暑，猨臂攀長松。","翠微泛罇綠，苔蘚分煙紅。","造化處術內，相對數壺空。","醉眠嶺上草，不覺夜露濃。","一夢到天曉，始覺一醉中。","皎然夢中路，直到瀛洲東。","初平把我臂，相與騎白龍。","三留對上帝，玉樓十二重。","上帝賜我酒，送我敲金鍾。","寶閣香斂苒，琪樹寒玲瓏。","動葉如笙篁，音律相怡融。","珍重此一醉，百骸出天地。","長如此夢魂，永謝名與利。"]', '["金风颯已起，還是招漁翁。","携酒天姥岑，自彈嶧陽桐。","脫却登山履，赤脚翹青筇。","泉声掃殘暑，猨臂攀长松。","翠微泛罇綠，苔蘚分煙紅。","造化处術內，相对數壺空。","醉眠嶺上草，不覺夜露濃。","一梦到天晓，始覺一醉中。","皎然梦中路，直到瀛洲东。","初平把我臂，相與騎白龙。","三留对上帝，玉楼十二重。","上帝賜我酒，送我敲金鍾。","寶閣香斂苒，琪樹寒玲瓏。","动葉如笙篁，音律相怡融。","珍重此一醉，百骸出天地。","长如此梦魂，永謝名與利。"]', '诗', 'shi', '', NULL, '秋醉歌 張爲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0de89bd5-852d-4a30-be20-a7c8c6f49eb9', '謝別毛仙翁', '謝別毛仙翁', 'd482da05-63a3-40a5-b2f7-918501a6ae86', '唐', '["羸形感神藥，削骨生豐肌。","蘭炷飄靈煙，妖怪立誅夷。","重覩日月光，何報父母慈。","黃河濁衮衮，別淚流澌澌。","黃河清有時，別淚無收期。"]', '["羸形感神藥，削骨生豐肌。","蘭炷飄靈煙，妖怪立誅夷。","重覩日月光，何報父母慈。","黄河濁衮衮，別泪流澌澌。","黄河清有时，別泪無收期。"]', '诗', 'shi', '', NULL, '謝別毛仙翁 張爲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2341666-1fc9-4c72-8e99-2775ab5dff14', '漁陽將軍', '漁陽將軍', 'd482da05-63a3-40a5-b2f7-918501a6ae86', '唐', '["霜髭擁頷對窮秋，著白貂裘獨上樓。","向北望星提劒立，一生長爲國家憂。"]', '["霜髭擁頷对窮秋，著白貂裘独上楼。","向北望星提劒立，一生长爲国家憂。"]', '诗', 'shi', '', NULL, '漁陽將軍 張爲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98ae2afc-2ec3-4fbf-8561-78d373464a45', '句', '句', 'd482da05-63a3-40a5-b2f7-918501a6ae86', '唐', '["到處即閉戶，逢君方展眉。"]', '["到处即閉戶，逢君方展眉。"]', '诗', 'shi', '', NULL, '句 張爲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30156080-0d07-4b6c-ad53-7ff3ac764b6d', '岑公巖', '岑公巖', '5816c948-54e8-4d18-bd1c-d04177a2b6b7', '唐', '["南溪有仙澗，咫尺非人間。","泠泠松風下，日暮空蒼山。"]', '["南溪有仙澗，咫尺非人间。","泠泠松风下，日暮空蒼山。"]', '诗', 'shi', '', NULL, '岑公巖 馬冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ba5b680-8c05-46fa-8ca3-80cff02ee98a', '諸暨五洩山', '諸暨五洩山', '4dc38819-dc86-43aa-a1dc-897a1aa6f05e', '唐', '["路入蒼煙九過溪，九穿巖曲到招提。","天分五溜寒傾北，地秀諸峰翠插西。","鑿徑破崖來木杪，駕泉鳴竹落榱題。","當年老默無消息，猶有詞堂一杖藜。"]', '["路入蒼煙九過溪，九穿巖曲到招提。","天分五溜寒傾北，地秀諸峰翠插西。","鑿徑破崖来木杪，駕泉鳴竹落榱題。","當年老默無消息，猶有词堂一杖藜。"]', '诗', 'shi', '', NULL, '諸暨五洩山 周鏞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('819a6b2a-6337-4ca8-bcaa-405ca5766415', '贈羅隱', '贈羅隐', '16cbfe3f-d8bc-4f01-acbe-fa73431e376a', '唐', '["人皆言子屈，獨我謂君非。","明主既難謁，青山何不歸？","年虛侵雪鬢，塵枉汚麻衣。","自古逃名者，至今名豈微。"]', '["人皆言子屈，独我謂君非。","明主既难謁，青山何不归？","年虛侵雪鬢，塵枉汚麻衣。","自古逃名者，至今名豈微。"]', '诗', 'shi', '', NULL, '贈羅隱 劉贊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2dacb6eb-7a73-482c-9d02-aedecfd386f0', '句', '句', '16cbfe3f-d8bc-4f01-acbe-fa73431e376a', '唐', '["絮花飛起雪漫漫，長得宮娥帶笑看。"]', '["絮花飞起雪漫漫，长得宮娥带笑看。"]', '诗', 'shi', '', NULL, '句 劉贊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2171e44d-f83c-4277-9155-6d06f66a9fab', '洛陽道', '洛陽道', 'e6053b0b-9357-46ac-916f-8882db143ad0', '唐', '["憧憧洛陽道，塵下生青草。","行者豈無家，無人在家老。","雞鳴前結束，爭去恐不早。","百年路傍盡，白日車中曉。","求富江海狹，取貴山岳小。","二端立在途，奔走無由了。"]', '["憧憧洛陽道，塵下生青草。","行者豈無家，無人在家老。","雞鳴前結束，爭去恐不早。","百年路傍尽，白日车中晓。","求富江海狹，取貴山岳小。","二端立在途，奔走無由了。"]', '诗', 'shi', '', NULL, '洛陽道 任翻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e5cf931-e8ba-4eb5-bba1-08180cb72982', '春晴', '春晴', 'e6053b0b-9357-46ac-916f-8882db143ad0', '唐', '["楚國多春雨，柴門喜晚晴。","幽人臨水坐，好鳥隔花鳴。","野色臨空闊，江流接海平。","門前到溪路，今夜月分明。"]', '["楚国多春雨，柴门喜晚晴。","幽人臨水坐，好鸟隔花鳴。","野色臨空闊，江流接海平。","门前到溪路，今夜月分明。"]', '诗', 'shi', '', NULL, '春晴 任翻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3d9b0ff-0a97-4993-9279-5bed56560e90', '秋晚郊居', '秋晚郊居', 'e6053b0b-9357-46ac-916f-8882db143ad0', '唐', '["遠聲霜後樹，秋色水邊村。","野徑無來客，寒風自動門。","海山藏日影，江月落潮痕。","惆悵高飛晚，年年別故園。"]', '["远声霜後樹，秋色水邊村。","野徑無来客，寒风自动门。","海山藏日影，江月落潮痕。","惆悵高飞晚，年年別故园。"]', '诗', 'shi', '', NULL, '秋晚郊居 任翻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcd30036-50f3-4374-bcc5-940b466d54f2', '秋晚途次', '秋晚途次', 'e6053b0b-9357-46ac-916f-8882db143ad0', '唐', '["秋色滿行路，此時心不閑。","孤貧遊上國，少壯有衰顏。","衆鳥已歸樹，旅人猶過山。","蕭條遠林外，風急水潺潺。"]', '["秋色满行路，此时心不闲。","孤貧游上国，少壯有衰顏。","衆鸟已归樹，旅人猶過山。","蕭條远林外，风急水潺潺。"]', '诗', 'shi', '', NULL, '秋晚途次 任翻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('300aa35a-b18a-4b04-8c8b-9f625cb15c7b', '葛仙井', '葛仙井', 'e6053b0b-9357-46ac-916f-8882db143ad0', '唐', '["古井碧沈沈，分明見百尋。","味甘傳邑內，脉冷應山心。","圓入月輪淨，直涵峰影深。","自從仙去後，汲引到如今。"]', '["古井碧沈沈，分明见百尋。","味甘傳邑內，脉冷應山心。","圓入月輪淨，直涵峰影深。","自從仙去後，汲引到如今。"]', '诗', 'shi', '', NULL, '葛仙井 任翻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78c6e097-b066-4e41-bec8-341110b60443', '桐柏觀', '桐柏观', 'e6053b0b-9357-46ac-916f-8882db143ad0', '唐', '["飄飄雲外者，蹔宿聚仙堂。","半夜人無語，中宵月送涼。","鶴歸高樹靜，螢過小池光。","不得多時住，門開是事忙。"]', '["飄飄云外者，蹔宿聚仙堂。","半夜人無語，中宵月送涼。","鹤归高樹静，螢過小池光。","不得多时住，门开是事忙。"]', '诗', 'shi', '', NULL, '桐柏觀 任翻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b4ccdea-b064-4e64-a8d8-81fe36fc9be4', '冬暮野寺', '冬暮野寺', 'e6053b0b-9357-46ac-916f-8882db143ad0', '唐', '["江東寒近臘，野寺水天昏。","無酒可銷夜，隨僧早閉門。","照墻燈影短，著瓦雪聲繁。","飄泊仍千里，清吟欲斷魂。"]', '["江东寒近臘，野寺水天昏。","無酒可銷夜，隨僧早閉门。","照墻灯影短，著瓦雪声繁。","飄泊仍千里，清吟欲斷魂。"]', '诗', 'shi', '', NULL, '冬暮野寺 任翻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aae858de-d014-439b-b33b-d919dbdeab21', '贈濟禪師', '贈濟禪師', 'e6053b0b-9357-46ac-916f-8882db143ad0', '唐', '["碧峰秋寺內，禪客已無情。","半頂髮根白，一生心地清。","竹房侵月靜，石徑到門平。","山下塵囂路，終年誓不行。"]', '["碧峰秋寺內，禪客已無情。","半頂髮根白，一生心地清。","竹房侵月静，石徑到门平。","山下塵囂路，終年誓不行。"]', '诗', 'shi', '', NULL, '贈濟禪師 任翻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a3a07b0-9369-4e7f-99dd-32685256e16b', '經墮淚碑', '經墮泪碑', 'e6053b0b-9357-46ac-916f-8882db143ad0', '唐', '["羊公傳化地，千古事空存。","碑已無文字，人猶敬子孫。","峴山長閉恨，漢水自流恩。","數處煙嵐色，分明是淚痕。"]', '["羊公傳化地，千古事空存。","碑已無文字，人猶敬子孫。","峴山长閉恨，漢水自流恩。","數处煙嵐色，分明是泪痕。"]', '诗', 'shi', '', NULL, '經墮淚碑 任翻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3abfdba9-2a0c-41fd-83db-17b9a1d18e96', '長安冬夜書事', '长安冬夜书事', 'e6053b0b-9357-46ac-916f-8882db143ad0', '唐', '["憂來長不寐，往事重思量。","清渭幾年客，故衣今夜霜。","春風誰識面，水國但牽腸。","十二門車馬，昏明各自忙。"]', '["憂来长不寐，往事重思量。","清渭幾年客，故衣今夜霜。","春风誰識面，水国但牽腸。","十二门车马，昏明各自忙。"]', '诗', 'shi', '', NULL, '長安冬夜書事 任翻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92e403e1-8dc4-49fe-83f8-b5fcd551be40', '越江漁父', '越江漁父', 'e6053b0b-9357-46ac-916f-8882db143ad0', '唐', '["借問釣魚者，持竿多少年。","眼明汀島畔，頭白子孫前。","櫂入花時浪，燈留雨夜船。","越江深見底，誰識此心堅。"]', '["借问釣鱼者，持竿多少年。","眼明汀島畔，头白子孫前。","櫂入花时浪，灯留雨夜船。","越江深见底，誰識此心堅。"]', '诗', 'shi', '', NULL, '越江漁父 任翻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc087581-acef-4440-9e83-f3d53cdf7bde', '哭友人', '哭友人', 'e6053b0b-9357-46ac-916f-8882db143ad0', '唐', '["逢著南州史，江邊哭問君。","送終時有雪，歸葬處無雲。","官庫惟留劒，隣僧共結墳。","兒孫未成立，誰與集遺文。"]', '["逢著南州史，江邊哭问君。","送終时有雪，归葬处無云。","官庫惟留劒，隣僧共結墳。","兒孫未成立，誰與集遺文。"]', '诗', 'shi', '', NULL, '哭友人 任翻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7597bff3-6104-4b19-96ca-b377b5a53424', '送李衡', '送李衡', 'e6053b0b-9357-46ac-916f-8882db143ad0', '唐', '["羈棲親故少，遠別惜清才。","天畔出相送，路長知未迴。","欲銷今日恨，強把異鄉杯。","君去南堂後，應無客到來。"]', '["羈棲親故少，远別惜清才。","天畔出相送，路长知未迴。","欲銷今日恨，強把異乡杯。","君去南堂後，應無客到来。"]', '诗', 'shi', '', NULL, '送李衡 任翻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f69af4c2-f99b-4593-a732-969d99243fd3', '宮怨', '宮怨', 'e6053b0b-9357-46ac-916f-8882db143ad0', '唐', '["淚乾紅落臉，心盡白垂頭。","自此方知怨，從來豈信愁。"]', '["泪乾紅落臉，心尽白垂头。","自此方知怨，從来豈信愁。"]', '诗', 'shi', '', NULL, '宮怨 任翻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4ca5669-16d6-4b2c-b60a-8b424c1e5d12', '惜花', '惜花', 'e6053b0b-9357-46ac-916f-8882db143ad0', '唐', '["無語與花別，細看枝上紅。","明年又相見，還恐是愁中。"]', '["無語與花別，細看枝上紅。","明年又相见，還恐是愁中。"]', '诗', 'shi', '', NULL, '惜花 任翻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25748fc8-5511-4aa3-b7b2-ee7c7b8af56d', '宿巾子山禪寺', '宿巾子山禪寺', 'e6053b0b-9357-46ac-916f-8882db143ad0', '唐', '["絕頂新秋生夜涼，鶴翻松露滴衣裳。","前峰月映半江水，僧在翠微開竹房。"]', '["絕頂新秋生夜涼，鹤翻松露滴衣裳。","前峰月映半江水，僧在翠微开竹房。"]', '诗', 'shi', '', NULL, '宿巾子山禪寺 任翻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f709816d-d21d-45db-963e-814ce89aba20', '再遊巾子山寺', '再游巾子山寺', 'e6053b0b-9357-46ac-916f-8882db143ad0', '唐', '["靈江江上幘峰寺，三十年來兩度登。","野鶴尚巢松樹徧，竹房不見舊時僧。"]', '["靈江江上幘峰寺，三十年来兩度登。","野鹤尚巢松樹徧，竹房不见旧时僧。"]', '诗', 'shi', '', NULL, '再遊巾子山寺 任翻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28b2104f-d0ca-46e5-af36-f99951136d3a', '三遊巾子山寺感述', '三游巾子山寺感述', 'e6053b0b-9357-46ac-916f-8882db143ad0', '唐', '["清秋絕頂竹房開，松鶴何年去不迴。","惟有前峰明月在，夜深猶過半江來。"]', '["清秋絕頂竹房开，松鹤何年去不迴。","惟有前峰明月在，夜深猶過半江来。"]', '诗', 'shi', '', NULL, '三遊巾子山寺感述 任翻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc0bdb14-572d-41d2-993e-925e8fb7d36e', '畫山水圖荅大愚', '畫山水圖荅大愚', 'd6d4b4f2-8186-43ea-bb5b-498b8349afb8', '唐', '["恣意縱橫埽，峰巒次第成。","筆尖寒樹瘦，墨澹野雲輕。","巖石噴泉窄，山根到水平。","禪房時一展，兼稱苦空情。"]', '["恣意縱橫埽，峰巒次第成。","笔尖寒樹瘦，墨澹野云轻。","巖石噴泉窄，山根到水平。","禪房时一展，兼稱苦空情。"]', '诗', 'shi', '', NULL, '畫山水圖荅大愚 荆浩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77b8c821-bdbc-43c9-819c-1d57ee5a7db0', '宿顧城二首 一', '宿顧城二首 一', '3619014a-4618-47f9-a958-36f54bb41f38', '唐', '["綠草展青裀，樾影連春樹。","茅屋八九家，農器六七具。","主人有好懷，搴衣留我住。","春酒新潑醅，香美連糟濾。","一醉臥花陰，明朝送君去。"]', '["綠草展青裀，樾影連春樹。","茅屋八九家，農器六七具。","主人有好懷，搴衣留我住。","春酒新潑醅，香美連糟濾。","一醉臥花陰，明朝送君去。"]', '诗', 'shi', '', NULL, '宿顧城二首 一 張直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33086607-fc85-487b-adfb-cb937624403d', '宿顧城二首 二', '宿顧城二首 二', '3619014a-4618-47f9-a958-36f54bb41f38', '唐', '["醉臥夜將半，土底聞雞啼。","驚駭問主人，爲我剖荒迷。","武湯東伐韋，固君含悲悽。","神奪悔悟魄，幻化爲石雞。","形骸僅盈寸，咿喔若啁蜺。","吾村耕耘叟，多獲於鋤犂。"]', '["醉臥夜將半，土底闻雞啼。","驚駭问主人，爲我剖荒迷。","武湯东伐韋，固君含悲悽。","神奪悔悟魄，幻化爲石雞。","形骸僅盈寸，咿喔若啁蜺。","吾村耕耘叟，多獲於鋤犂。"]', '诗', 'shi', '', NULL, '宿顧城二首 二 張直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24f25d1e-409b-4d27-bb36-6e9e071e432b', '題桃源僧', '題桃源僧', '2a22b467-4024-411f-a6b5-855957cd08f9', '唐', '["桃源有僧舍，跬步異人天。","花亂似無主，鶴鳴疑有仙。","軒廊明野色，松檜濕春煙。","定擬辭塵境，依師過晚年。"]', '["桃源有僧舍，跬步異人天。","花亂似無主，鹤鳴疑有仙。","軒廊明野色，松檜濕春煙。","定擬辞塵境，依師過晚年。"]', '诗', 'shi', '', NULL, '題桃源僧 陳光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7cf3faf-ef1c-48db-82f6-99bc2ddfabbc', '吟敘', '吟敘', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["歷代興亡億萬心，聖人觀古貴知今。","古今成敗無多事，月殿花臺幸一吟。"]', '["歷代兴亡億万心，聖人观古貴知今。","古今成敗無多事，月殿花台幸一吟。"]', '诗', 'shi', '', NULL, '吟敘 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35b0faff-992f-41d0-a4a3-b00784bcfb34', '閑吟', '闲吟', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["考摭妍媸用破心，翦裁千古獻當今。","閑吟不是閑吟事，事有閑思閑要吟。"]', '["考摭妍媸用破心，翦裁千古獻當今。","闲吟不是闲吟事，事有闲思闲要吟。"]', '诗', 'shi', '', NULL, '閑吟 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5acb2c09-00ec-442b-a39f-8e83ade6609a', '唐虞門 唐堯', '唐虞门 唐堯', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["祆氛不起瑞煙輕，端拱垂衣日月明。","傳事四方無外役，茅茨深處土堦平。"]', '["祆氛不起瑞煙轻，端拱垂衣日月明。","傳事四方無外役，茅茨深处土堦平。"]', '诗', 'shi', '', NULL, '唐虞門 唐堯 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f86ad4d8-a515-4030-91be-293704881180', '唐虞門 虞舜', '唐虞门 虞舜', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["進善懲奸立帝功，功成揖讓益溫恭。","滿朝卿士多元凱，爲黜兜苗與四兇。"]', '["進善懲奸立帝功，功成揖讓益溫恭。","满朝卿士多元凱，爲黜兜苗與四兇。"]', '诗', 'shi', '', NULL, '唐虞門 虞舜 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('246656d3-3a46-430e-b6fd-a8ce60ef9bf3', '唐虞門 舜妃', '唐虞门 舜妃', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["蒼梧一望隔重雲，帝子悲尋不記春。","何事淚痕偏在竹，貞姿應念節高人。"]', '["蒼梧一望隔重云，帝子悲尋不記春。","何事泪痕偏在竹，貞姿應念節高人。"]', '诗', 'shi', '', NULL, '唐虞門 舜妃 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('093748bf-fe6e-4301-99a7-8bd51c2eccaf', '唐虞門 再吟', '唐虞门 再吟', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["瀟湘何代泣幽魂，骨化重泉志尚存。","若道地中休下淚，不應新竹有啼痕。"]', '["瀟湘何代泣幽魂，骨化重泉志尚存。","若道地中休下泪，不應新竹有啼痕。"]', '诗', 'shi', '', NULL, '唐虞門 再吟 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19399c9e-e48a-4a8c-add2-7556ea8f2169', '三代門 夏禹', '三代门 夏禹', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["堯違天孽賴詢謨，頓免洪波浸碧虛。","海內生靈微伯禹，盡應隨浪化爲魚。"]', '["堯違天孽賴詢謨，頓免洪波浸碧虛。","海內生靈微伯禹，尽應隨浪化爲鱼。"]', '诗', 'shi', '', NULL, '三代門 夏禹 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('811f6a9c-d8f3-4f84-9226-e4fc8b47b8ad', '三代門 再吟', '三代门 再吟', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["萬古龍門一旦開，無成甘死作黃能。","司空定有匡堯術，九載之前何處來。"]', '["万古龙门一旦开，無成甘死作黄能。","司空定有匡堯術，九載之前何处来。"]', '诗', 'shi', '', NULL, '三代門 再吟 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13b7acca-48f9-4a53-afea-0bb85af686de', '三代門 太康', '三代门 太康', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["師保何人爲琢磨，安知父祖苦辛多。","酒酣禽色方爲樂，詎肯閑聽五子歌。"]', '["師保何人爲琢磨，安知父祖苦辛多。","酒酣禽色方爲乐，詎肯闲听五子歌。"]', '诗', 'shi', '', NULL, '三代門 太康 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c0c0124-9ede-4c66-9704-924bf61dcdf7', '三代門 后稷', '三代门 后稷', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["人惟邦本本由農，曠古誰高后稷功。","百穀且繁三曜在，牲牢郊祀信無窮。"]', '["人惟邦本本由農，曠古誰高后稷功。","百穀且繁三曜在，牲牢郊祀信無窮。"]', '诗', 'shi', '', NULL, '三代門 后稷 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76e6ea54-baf8-4f83-a9d9-4e1eb5bd4f12', '三代門 文王', '三代门 文王', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["昭然明德報天休，禴祭惟馨勝殺牛。","二老五侯何所詐，不歸商受盡歸周。"]', '["昭然明德報天休，禴祭惟馨勝殺牛。","二老五侯何所詐，不归商受尽归周。"]', '诗', 'shi', '', NULL, '三代門 文王 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('984b76f8-e10e-499e-9e0f-20617a927408', '三代門 武王', '三代门 武王', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["文王寢膳武王隨，內豎言安色始怡。","七載豈堪囚羑里，一夫爲報亦何疑。"]', '["文王寢膳武王隨，內豎言安色始怡。","七載豈堪囚羑里，一夫爲報亦何疑。"]', '诗', 'shi', '', NULL, '三代門 武王 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c5fdfab-f430-4d11-ac34-7a1e0304f0d7', '三代門 太公', '三代门 太公', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["昌獵關西紂獵東，紂憐崇虎棄非熊。","危邦自謂多麟鳳，肯把王綱取釣翁。"]', '["昌獵关西紂獵东，紂怜崇虎棄非熊。","危邦自謂多麟鳳，肯把王綱取釣翁。"]', '诗', 'shi', '', NULL, '三代門 太公 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d76fbbb-4ab7-4fe5-a40b-a0c7850bd7df', '三代門 再吟', '三代门 再吟', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["東鄰不事事西鄰，御物卑和物自親。","天下言知天下者，兆人無主屬賢人。"]', '["东鄰不事事西鄰，御物卑和物自親。","天下言知天下者，兆人無主屬賢人。"]', '诗', 'shi', '', NULL, '三代門 再吟 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7b9a52e-4625-48b5-957f-a9741ffb77dd', '三代門 又吟', '三代门 又吟', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["千妖萬態逞妍姿，破國亡家更是誰。","匡政必能除苟媚，去邪當斷勿狐疑。"]', '["千妖万態逞妍姿，破国亡家更是誰。","匡政必能除苟媚，去邪當斷勿狐疑。"]', '诗', 'shi', '', NULL, '三代門 又吟 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26f94d29-6753-4938-94ab-dce13656557f', '三代門 子牙妻', '三代门 子牙妻', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["陵柏無心竹變秋，不能同戚擬同休。","歲寒焉在空垂涕，覆水如何欲再收。"]', '["陵柏無心竹变秋，不能同戚擬同休。","歲寒焉在空垂涕，覆水如何欲再收。"]', '诗', 'shi', '', NULL, '三代門 子牙妻 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d897850-fcae-4af6-b9f1-611d6a8f99b4', '三代門 周公', '三代门 周公', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["文武傳芳百代基，幾多賢哲守成規。","仍聞吐握延儒素，猶恐民疵未盡知。"]', '["文武傳芳百代基，幾多賢哲守成規。","仍闻吐握延儒素，猶恐民疵未尽知。"]', '诗', 'shi', '', NULL, '三代門 周公 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30a542a9-6133-4d5c-bb54-39498fd9be57', '三代門 夷齊', '三代门 夷齊', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["讓國由衷義亦乖，不知天命匹夫才。","將除暴虐誠能阻，何異崎嶇助紂來。"]', '["讓国由衷義亦乖，不知天命匹夫才。","將除暴虐誠能阻，何異崎嶇助紂来。"]', '诗', 'shi', '', NULL, '三代門 夷齊 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12aa7146-6503-406e-ad47-dd6218c9f547', '三代門 管蔡', '三代门 管蔡', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["伊商胡越尚同圖，管蔡如何有異謨。","不念祖宗危社稷，強于仁聖遣行誅。"]', '["伊商胡越尚同圖，管蔡如何有異謨。","不念祖宗危社稷，強于仁聖遣行誅。"]', '诗', 'shi', '', NULL, '三代門 管蔡 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0708543-def3-40eb-baf5-f17924a73f5d', '三代門 成王', '三代门 成王', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["成王有過伯禽笞，聖惠能新日自奇。","王道既成何所感，越裳呈瑞鳳來儀。"]', '["成王有過伯禽笞，聖惠能新日自奇。","王道既成何所感，越裳呈瑞鳳来儀。"]', '诗', 'shi', '', NULL, '三代門 成王 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('204b8f0c-c742-462e-94f5-adad0b1b0d98', '三代門 幽王', '三代门 幽王', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["狼煙篝火爲邊塵，烽候那宜悅婦人。","厚德未聞聞厚色，不亡家國幸亡身。"]', '["狼煙篝火爲邊塵，烽候那宜悅婦人。","厚德未闻闻厚色，不亡家国幸亡身。"]', '诗', 'shi', '', NULL, '三代門 幽王 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22ff374f-deba-4c5a-b61c-96e399973fa5', '三代門 平王', '三代门 平王', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["犬戎西集殺幽王，邦土何由不便亡。","宜臼東來年更遠，川流難絕信源長。"]', '["犬戎西集殺幽王，邦土何由不便亡。","宜臼东来年更远，川流难絕信源长。"]', '诗', 'shi', '', NULL, '三代門 平王 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ac393dd-7f75-472e-a0da-b6e246724eea', '春秋戰國門 祭足', '春秋戰国门 祭足', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["吳魯燕韓豈別宗，曾無外禦但相攻。","當時周鄭誰爲相，交質將何服遠戎。"]', '["吳魯燕韓豈別宗，曾無外禦但相攻。","當时周鄭誰爲相，交質將何服远戎。"]', '诗', 'shi', '', NULL, '春秋戰國門 祭足 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e81c7639-f9f2-4967-868c-9bd3f63ee8d8', '春秋戰國門 再吟', '春秋戰国门 再吟', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["周室衰微不共匡，干戈終日互爭強。","諸侯若解尊天子，列國何因次第亡。"]', '["周室衰微不共匡，干戈終日互爭強。","諸侯若解尊天子，列国何因次第亡。"]', '诗', 'shi', '', NULL, '春秋戰國門 再吟 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc2e934a-6d91-4849-9d45-167a1d92454b', '春秋戰國門 隱公', '春秋戰国门 隐公', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["今古難隄是小人，苟希榮寵任相親。","陳謀不信懷憂懼，反間須防却害身。"]', '["今古难隄是小人，苟希榮寵任相親。","陳謀不信懷憂懼，反间須防却害身。"]', '诗', 'shi', '', NULL, '春秋戰國門 隱公 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0bee03c-c04b-4c8f-9725-cf433a04a23f', '春秋戰國門 莊公', '春秋戰国门 莊公', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["齊甲強臨力有餘，魯莊爲戰念區區。","魚麗三鼓微曹劌，肉食安能暇遠謨。"]', '["齊甲強臨力有餘，魯莊爲戰念區區。","鱼丽三鼓微曹劌，肉食安能暇远謨。"]', '诗', 'shi', '', NULL, '春秋戰國門 莊公 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd13166f-d052-420a-bd66-12e907754e10', '春秋戰國門 哀公', '春秋戰国门 哀公', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["賢爲鄰用國憂危，廟算無非委豔奇。","兩葉翠娥春乍展，一毛須去不難吹。"]', '["賢爲鄰用国憂危，廟算無非委豔奇。","兩葉翠娥春乍展，一毛須去不难吹。"]', '诗', 'shi', '', NULL, '春秋戰國門 哀公 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31319f1a-06c4-441d-a68a-de98bc663a47', '春秋戰國門 再吟', '春秋戰国门 再吟', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["好龍天爲降真龍，及見真龍瘁厥躬。","接下不勤徒好士，葉公何異魯哀公。"]', '["好龙天爲降真龙，及见真龙瘁厥躬。","接下不勤徒好士，葉公何異魯哀公。"]', '诗', 'shi', '', NULL, '春秋戰國門 再吟 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b8e9657-45ed-46d5-8a0b-f579da9f8f84', '春秋戰國門 平公', '春秋戰国门 平公', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["鴻鵠輕騰萬里高，何殊朝野得賢豪。","能知翼戴穹蒼力，不是蒙茸腹背毛。"]', '["鴻鵠轻腾万里高，何殊朝野得賢豪。","能知翼戴穹蒼力，不是蒙茸腹背毛。"]', '诗', 'shi', '', NULL, '春秋戰國門 平公 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5033659a-77e0-4e66-bb3f-ce3b09162c67', '春秋戰國門 文公', '春秋戰国门 文公', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["滅虢吞虞未息兵，柔秦敗楚霸威成。","文公徒欲三強服，分晉元來是六卿。"]', '["滅虢吞虞未息兵，柔秦敗楚霸威成。","文公徒欲三強服，分晉元来是六卿。"]', '诗', 'shi', '', NULL, '春秋戰國門 文公 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c0eb62e-d588-4036-9a56-6e118eeb3e1e', '春秋戰國門 景公', '春秋戰国门 景公', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["覺病當宜早問師，病深難療恨難追。","晉侯徒有秦醫緩，疾在膏肓救已遲。"]', '["覺病當宜早问師，病深难療恨难追。","晉侯徒有秦醫緩，疾在膏肓救已遲。"]', '诗', 'shi', '', NULL, '春秋戰國門 景公 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('608b0b2a-3e65-4a34-bd34-1b78b107c04e', '春秋戰國門 衛靈公', '春秋戰国门 衛靈公', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["子魚無隱欲源清，死不忘忠感衛靈。","伯玉既親知德潤，殘桃休喫悟蘭馨。"]', '["子鱼無隐欲源清，死不忘忠感衛靈。","伯玉既親知德潤，殘桃休喫悟蘭馨。"]', '诗', 'shi', '', NULL, '春秋戰國門 衛靈公 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a527e4e-6972-4edd-97c3-bf5ce983f0fe', '春秋戰國門 陳靈公', '春秋戰国门 陳靈公', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["誰與陳君嫁禍來，孔寧行父夏姬媒。","靈公徒認徴舒面，至死何曾識禍胎。"]', '["誰與陳君嫁禍来，孔寧行父夏姬媒。","靈公徒認徴舒面，至死何曾識禍胎。"]', '诗', 'shi', '', NULL, '春秋戰國門 陳靈公 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3eb2ee60-69ef-4034-a563-c4ec487cf30c', '春秋戰國門 陳蔡君', '春秋戰国门 陳蔡君', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["楚聘宣尼欲道光，是時陳蔡畏鄰強。","庸謀但解遮賢路，不解迎賢謀自昌。"]', '["楚聘宣尼欲道光，是时陳蔡畏鄰強。","庸謀但解遮賢路，不解迎賢謀自昌。"]', '诗', 'shi', '', NULL, '春秋戰國門 陳蔡君 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e770443-6a95-464e-bfa8-1c5cc8c53013', '春秋戰國門 楚惠王', '春秋戰国门 楚惠王', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["芹中遇蛭強爲吞，不欲緣微有害人。","何事免成心腹疾，皇天惟德是相親。"]', '["芹中遇蛭強爲吞，不欲緣微有害人。","何事免成心腹疾，皇天惟德是相親。"]', '诗', 'shi', '', NULL, '春秋戰國門 楚惠王 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92a6d3a0-914d-4982-a18a-fed6ea83b82d', '春秋戰國門 楚懷王', '春秋戰国门 楚懷王', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["不聽陳軫信張儀，六里商於果見欺。","既舍黔中西換得，又令生去益堪悲。"]', '["不听陳軫信張儀，六里商於果见欺。","既舍黔中西換得，又令生去益堪悲。"]', '诗', 'shi', '', NULL, '春秋戰國門 楚懷王 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25e584a2-98bd-413c-b3c8-6b661b942867', '春秋戰國門 再吟', '春秋戰国门 再吟', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["不得商於又失齊，楚懷方寸一何迷。","明知秦是虎狼國，更忍車輪獨向西。"]', '["不得商於又失齊，楚懷方寸一何迷。","明知秦是虎狼国，更忍车輪独向西。"]', '诗', 'shi', '', NULL, '春秋戰國門 再吟 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f95457b-eca8-458c-8940-e757edf9470a', '春秋戰國門 韓惠王', '春秋戰国门 韓惠王', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["韓惠開渠止暴秦，營田萬頃飽秦人。","何殊般肉供羸獸，獸壯安知不害身。"]', '["韓惠开渠止暴秦，營田万頃飽秦人。","何殊般肉供羸獸，獸壯安知不害身。"]', '诗', 'shi', '', NULL, '春秋戰國門 韓惠王 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55ace381-6f44-4b02-8347-cc439d0ff119', '春秋戰國門 頃襄王', '春秋戰国门 頃襄王', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["秦陷荆王死不還，秪緣偏聽子蘭言。","頃襄還信子蘭語，忍使江魚葬屈原。"]', '["秦陷荆王死不還，秪緣偏听子蘭言。","頃襄還信子蘭語，忍使江鱼葬屈原。"]', '诗', 'shi', '', NULL, '春秋戰國門 頃襄王 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('704d2b78-b094-4113-844e-9792e2def575', '春秋戰國門 武公', '春秋戰国门 武公', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["猛獸來兵秪爲文，豈宜涼德擬圖尊。","君看豹彩蒙麋質，人取無難必不存。"]', '["猛獸来兵秪爲文，豈宜涼德擬圖尊。","君看豹彩蒙麋質，人取無难必不存。"]', '诗', 'shi', '', NULL, '春秋戰國門 武公 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51a0432c-08d9-4ec3-9fe7-924380140c5d', '春秋戰國門 華元', '春秋戰国门 华元', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["未知軍法忌偏頗，徒解于思腹漫皤。","昔日羊斟曾不預，今朝爲政事如何。"]', '["未知軍法忌偏頗，徒解于思腹漫皤。","昔日羊斟曾不預，今朝爲政事如何。"]', '诗', 'shi', '', NULL, '春秋戰國門 華元 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('449a8c03-8fcb-410f-b7ca-390ed2602d12', '春秋戰國門 臧孫', '春秋戰国门 臧孫', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["諸孟憎吾似犬獰，賢臧哭孟倍傷情。","季孫愛我如甘疾，疾足亡身藥故寧。"]', '["諸孟憎吾似犬獰，賢臧哭孟倍傷情。","季孫愛我如甘疾，疾足亡身藥故寧。"]', '诗', 'shi', '', NULL, '春秋戰國門 臧孫 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a6729a2-c9bc-45a7-a5a2-e324edba4346', '春秋戰國門 公叔', '春秋戰国门 公叔', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["吳起南奔魏國荒，必聽公叔失賢良。","無謀縱欲離安邑，可免河溝徙大梁。"]', '["吳起南奔魏国荒，必听公叔失賢良。","無謀縱欲離安邑，可免河溝徙大梁。"]', '诗', 'shi', '', NULL, '春秋戰國門 公叔 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2521ab0b-cd2a-4a41-8b3b-d5c157729d83', '春秋戰國門 莊辛', '春秋戰国门 莊辛', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["莊辛正諫謂妖詞，兵及鄢陵始悔思。","見兔必能知顧犬，亡羊補棧未爲遲。"]', '["莊辛正諫謂妖词，兵及鄢陵始悔思。","见兔必能知顧犬，亡羊補棧未爲遲。"]', '诗', 'shi', '', NULL, '春秋戰國門 莊辛 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82587e00-c82e-4a89-9dbf-d439034df2d3', '春秋戰國門 孫臏', '春秋戰国门 孫臏', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["曾嫌勝己害賢人，鑽火明知速自焚。","斷足爾能行不足，逢君誰肯不酬君。"]', '["曾嫌勝己害賢人，鑽火明知速自焚。","斷足爾能行不足，逢君誰肯不酬君。"]', '诗', 'shi', '', NULL, '春秋戰國門 孫臏 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce907471-05e8-4a83-acae-70ad0ee1f076', '春秋戰國門 靈[輒]', '春秋戰国门 靈[輒]', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["失水枯鱗得再生，翳桑無地謝深情。","朱輪爲染酬恩血，公子何由見赤誠。"]', '["失水枯鱗得再生，翳桑無地謝深情。","朱輪爲染酬恩血，公子何由见赤誠。"]', '诗', 'shi', '', NULL, '春秋戰國門 靈[輒] 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84e7dad7-4cb9-448b-bbb7-d7e543859aa4', '春秋戰國門 郭開', '春秋戰国门 郭开', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["秦襲邯鄲歲月深，何人沾贈郭開金。","廉頗還國李牧在，安得趙王爲爾擒。"]', '["秦襲邯鄲歲月深，何人沾贈郭开金。","廉頗還国李牧在，安得趙王爲爾擒。"]', '诗', 'shi', '', NULL, '春秋戰國門 郭開 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65bc738e-d53f-4baa-9024-714ce6a25c02', '春秋戰國門 樂羊', '春秋戰国门 乐羊', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["桮羹忍啜得非忠，巧佞胡爲惑主聰。","盈篋謗書能寢默，中山不是樂羊功。"]', '["桮羹忍啜得非忠，巧佞胡爲惑主聰。","盈篋謗书能寢默，中山不是乐羊功。"]', '诗', 'shi', '', NULL, '春秋戰國門 樂羊 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f05d684-2335-4aef-9deb-dec38328bb7b', '春秋戰國門 虞卿', '春秋戰国门 虞卿', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["割地求和國必危，安知堅守絕來思。","年年來伐年年割，割盡韓鄲何所之。"]', '["割地求和国必危，安知堅守絕来思。","年年来伐年年割，割尽韓鄲何所之。"]', '诗', 'shi', '', NULL, '春秋戰國門 虞卿 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6179a728-52b3-45f9-884d-c97e42305dc0', '春秋戰國門 豫讓', '春秋戰国门 豫讓', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["門客家臣義莫儔，漆身吞炭不能休。","中行智伯思何異，國士終期國士酬。"]', '["门客家臣義莫儔，漆身吞炭不能休。","中行智伯思何異，国士終期国士酬。"]', '诗', 'shi', '', NULL, '春秋戰國門 豫讓 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b02b80ac-caf6-4f52-bb43-ab491108ad34', '春秋戰國門 毛遂', '春秋戰国门 毛遂', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["不識囊中頴脫錐，功成方信有英奇。","平原門下三千客，得力何曾是素知。"]', '["不識囊中頴脫錐，功成方信有英奇。","平原门下三千客，得力何曾是素知。"]', '诗', 'shi', '', NULL, '春秋戰國門 毛遂 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bc113e9-7c38-4429-a9ad-eff7e88483da', '春秋戰國門 再吟', '春秋戰国门 再吟', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["定獲英奇不在多，然須設網遍山河。","禽雖一目羅中得，豈可空張一目羅。"]', '["定獲英奇不在多，然須設網遍山河。","禽雖一目羅中得，豈可空張一目羅。"]', '诗', 'shi', '', NULL, '春秋戰國門 再吟 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1959138b-5885-46ef-8843-7833bfb71d78', '春秋戰國門 田文', '春秋戰国门 田文', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["下客常才不足珍，誰爲狗盜脫強秦。","秦關若待雞鳴出，笑殺臨淄土偶人。"]', '["下客常才不足珍，誰爲狗盜脫強秦。","秦关若待雞鳴出，笑殺臨淄土偶人。"]', '诗', 'shi', '', NULL, '春秋戰國門 田文 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33abfaee-72d6-4ebe-a17d-1cc30f6ddba5', '春秋戰國門 再吟', '春秋戰国门 再吟', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["門下三千各自矜，頻彈劍客獨無能。","田文不厭無能客，三窟全身果有憑。"]', '["门下三千各自矜，頻彈劍客独無能。","田文不厭無能客，三窟全身果有憑。"]', '诗', 'shi', '', NULL, '春秋戰國門 再吟 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d0328d2-9a89-40a5-bf72-987c5820211b', '春秋戰國門 馮讙', '春秋戰国门 馮讙', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["兔窟穿成主再興，輩流狐伏敢驕矜。","馮讙不是無能者，要試君心欲展能。"]', '["兔窟穿成主再兴，輩流狐伏敢驕矜。","馮讙不是無能者，要試君心欲展能。"]', '诗', 'shi', '', NULL, '春秋戰國門 馮讙 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0ee59ad-9ce7-403d-b015-da0547999e15', '春秋戰國門 章子', '春秋戰国门 章子', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["在家能子必能臣，齊將功成以孝聞。","改葬義無欺死父，臨戎安肯背生君。"]', '["在家能子必能臣，齊將功成以孝闻。","改葬義無欺死父，臨戎安肯背生君。"]', '诗', 'shi', '', NULL, '春秋戰國門 章子 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8a7294f-1830-4952-bfda-248d57e5b38a', '春秋戰國門 卞和', '春秋戰国门 卞和', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["磷磷誰爲惑溫溫，至寶凡姿甚易分。","自是時人多貴耳，目無明鑒使俱焚。"]', '["磷磷誰爲惑溫溫，至寶凡姿甚易分。","自是时人多貴耳，目無明鑒使俱焚。"]', '诗', 'shi', '', NULL, '春秋戰國門 卞和 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e001b27-7c8e-4dfa-a1c4-8807d615ae7c', '春秋戰國門 季札', '春秋戰国门 季札', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["吹毛霜刃過千金，生許徐君死挂林。","寶劍徒稱無價寶，行心更貴不欺心。"]', '["吹毛霜刃過千金，生許徐君死挂林。","寶劍徒稱無價寶，行心更貴不欺心。"]', '诗', 'shi', '', NULL, '春秋戰國門 季札 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('860b72ea-e86b-4358-a15b-33f32ca318c9', '春秋戰國門 孫武', '春秋戰国门 孫武', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["理國無難似理兵，兵家法令貴遵行。","行刑不避君王寵，一笑隨刀八陣成。"]', '["理国無难似理兵，兵家法令貴遵行。","行刑不避君王寵，一笑隨刀八陣成。"]', '诗', 'shi', '', NULL, '春秋戰國門 孫武 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19e6bdb3-dd12-4580-b895-e19246240061', '春秋戰國門 夫差', '春秋戰国门 夫差', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["信聽讒言疾不除，忠臣須殺竟何如。","會稽既雪夫差死，泉下胡顏見子胥。"]', '["信听讒言疾不除，忠臣須殺竟何如。","會稽既雪夫差死，泉下胡顏见子胥。"]', '诗', 'shi', '', NULL, '春秋戰國門 夫差 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c84d0d6-d517-4255-a963-9b92991ba1bc', '春秋戰國門 少孺', '春秋戰国门 少孺', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["寶貴親仁與善鄰，鄰兵何要互相臻。","螳蜋定是遭黃雀，黃雀須訪挾彈人。"]', '["寶貴親仁與善鄰，鄰兵何要互相臻。","螳蜋定是遭黄雀，黄雀須訪挾彈人。"]', '诗', 'shi', '', NULL, '春秋戰國門 少孺 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a058de3e-23f0-485e-949c-1b0e3af892aa', '春秋戰國門 蘇厲', '春秋戰国门 蘇厲', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["百步穿楊箭不移，養由堪教聽弘規。","身隆業著未知退，勿遣功名一旦隳。"]', '["百步穿楊箭不移，養由堪教听弘規。","身隆業著未知退，勿遣功名一旦隳。"]', '诗', 'shi', '', NULL, '春秋戰國門 蘇厲 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6374d5f0-f329-4686-bb3c-bcd4cd9e99cb', '春秋戰國門 鬻拳', '春秋戰国门 鬻拳', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["鬻拳強諫懼威刑，退省懷慙不顧生。","雙刖忍行留痛恨，惟君適足見忠誠。"]', '["鬻拳強諫懼威刑，退省懷慙不顧生。","雙刖忍行留痛恨，惟君適足见忠誠。"]', '诗', 'shi', '', NULL, '春秋戰國門 鬻拳 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51dd0d1a-01d4-434b-8257-a15d7f9c218b', '春秋戰國門 荆軻', '春秋戰国门 荆軻', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["反刃相酬是匹夫，安知突騎駕羣胡。","有心爲報懷權畧，可在於期與地圖。"]', '["反刃相酬是匹夫，安知突騎駕羣胡。","有心爲報懷權畧，可在於期與地圖。"]', '诗', 'shi', '', NULL, '春秋戰國門 荆軻 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('288c3713-0aaf-499b-8c78-c2086e75f4d6', '春秋戰國門 再吟', '春秋戰国门 再吟', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["幾尺如霜利不羣，恩仇未報反亡身。","誠哉利器全由用，可惜吹毛不得人。"]', '["幾尺如霜利不羣，恩仇未報反亡身。","誠哉利器全由用，可惜吹毛不得人。"]', '诗', 'shi', '', NULL, '春秋戰國門 再吟 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e4d539b-1165-4d15-8fbd-510ef8bc5e85', '春秋戰國門 陳軫', '春秋戰国门 陳軫', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["丹青徒有逞諠譁，有足由來不是蛇。","殺將破軍爲柱國，君今官極更何加。"]', '["丹青徒有逞諠譁，有足由来不是蛇。","殺將破軍爲柱国，君今官極更何加。"]', '诗', 'shi', '', NULL, '春秋戰國門 陳軫 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b46b8c5-29f9-4087-bf95-045e8169daed', '春秋戰國門 田饒', '春秋戰国门 田饒', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["廚拋敗肉士懷飢，倉爛餘糧客未炊。","臨難欲行求死士，將何恩信致扶危。"]', '["廚拋敗肉士懷飢，倉爛餘糧客未炊。","臨难欲行求死士，將何恩信致扶危。"]', '诗', 'shi', '', NULL, '春秋戰國門 田饒 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('266b9e36-04c2-4248-a719-7a631d3baf11', '春秋戰國門 鮑叔', '春秋戰国门 鲍叔', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["忠臣祝壽吐嘉詞，鮑叔臨軒酒一巵。","安不忘危臣所願，願思危困必無危。"]', '["忠臣祝壽吐嘉词，鲍叔臨軒酒一巵。","安不忘危臣所願，願思危困必無危。"]', '诗', 'shi', '', NULL, '春秋戰國門 鮑叔 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2cf1e66a-ae37-458b-b5af-3139df74adaf', '春秋戰國門 晏嬰', '春秋戰国门 晏嬰', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["正人徒以刃相危，貪利忘忠死不爲。","麋鹿命懸當有處，驅車何必用奔馳。"]', '["正人徒以刃相危，貪利忘忠死不爲。","麋鹿命懸當有处，驱车何必用奔驰。"]', '诗', 'shi', '', NULL, '春秋戰國門 晏嬰 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9753c9e1-032f-448c-860b-6b6d02ce70b1', '春秋戰國門 再吟', '春秋戰国门 再吟', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["下澤逢蛇蓋是常，還如山上見豺狼。","國中有怪非蛇獸，不用賢能是不祥。"]', '["下澤逢蛇蓋是常，還如山上见豺狼。","国中有怪非蛇獸，不用賢能是不祥。"]', '诗', 'shi', '', NULL, '春秋戰國門 再吟 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32c324a7-d5e8-4eb7-8ce7-59196f059bcd', '春秋戰國門 又吟', '春秋戰国门 又吟', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["馬斃廐人欲就刑，百年臨盡一言生。","賴逢賢相能匡救，仍免吾君播惡聲。"]', '["马斃廐人欲就刑，百年臨尽一言生。","賴逢賢相能匡救，仍免吾君播惡声。"]', '诗', 'shi', '', NULL, '春秋戰國門 又吟 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8446179b-cbd6-475d-baa2-1303e06ec5b5', '春秋戰國門 叔向', '春秋戰国门 叔向', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["重祿存家不敢言，小臣憂禍亦如然。","明開諫諍能無罪，秪此宜爲理國先。"]', '["重祿存家不敢言，小臣憂禍亦如然。","明开諫諍能無罪，秪此宜爲理国先。"]', '诗', 'shi', '', NULL, '春秋戰國門 叔向 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('084ebaa1-3eea-4de8-95f5-6ea844e2f628', '春秋戰國門 師曠', '春秋戰国门 師曠', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["老能勸學照餘生，似夜隨燈到處明。","往行前言如不見，暗中無燭若爲行。"]', '["老能勸学照餘生，似夜隨灯到处明。","往行前言如不见，暗中無燭若爲行。"]', '诗', 'shi', '', NULL, '春秋戰國門 師曠 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e61b2383-baa7-44ed-ae93-5db17c4c079a', '春秋戰國門 智伯', '春秋戰国门 智伯', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["三國連兵敵就擒，晉陽城下碧波深。","風濤撼處看沈趙，舟楫不從飜自沈。"]', '["三国連兵敵就擒，晉陽城下碧波深。","风濤撼处看沈趙，舟楫不從飜自沈。"]', '诗', 'shi', '', NULL, '春秋戰國門 智伯 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d2fafc2-8879-43b7-b338-119a268ad929', '春秋戰國門 再吟', '春秋戰国门 再吟', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["攻城來下惜先分，一旦家邦屬四鄰。","徒逞威強稱智伯，不知權變是愚人。"]', '["攻城来下惜先分，一旦家邦屬四鄰。","徒逞威強稱智伯，不知權变是愚人。"]', '诗', 'shi', '', NULL, '春秋戰國門 再吟 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('523608ab-3a70-4431-90b7-26da6699d1d5', '春秋戰國門 襄子', '春秋戰国门 襄子', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["君子常聞不迫危，城崩何用急重圍。","叛亡能退修文德，果見中牟以義歸。"]', '["君子常闻不迫危，城崩何用急重圍。","叛亡能退修文德，果见中牟以義归。"]', '诗', 'shi', '', NULL, '春秋戰國門 襄子 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13ded6a6-b9c9-4868-ba7f-49f3907962f1', '春秋戰國門 楊回', '春秋戰国门 楊回', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["三逐鄉閭五去君，莫知何地可容身。","楊回不是逢英鑒，白首無成一旅人。"]', '["三逐乡閭五去君，莫知何地可容身。","楊回不是逢英鑒，白首無成一旅人。"]', '诗', 'shi', '', NULL, '春秋戰國門 楊回 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('100a3310-7842-4684-a17a-41f131d0d993', '春秋戰國門 顏回', '春秋戰国门 顏回', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["陋巷簞瓢困有年，是時端木飫腥膻。","宣尼行教何形迹，不肯分甘救子淵。"]', '["陋巷簞瓢困有年，是时端木飫腥膻。","宣尼行教何形迹，不肯分甘救子淵。"]', '诗', 'shi', '', NULL, '春秋戰國門 顏回 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f189cc0a-1389-47ce-9edb-a0076883f068', '春秋戰國門 子貢', '春秋戰国门 子貢', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["救魯亡吳事可傷，誰令利口說田常。","吳亡必定由端木，魯亦宜其運不長。"]', '["救魯亡吳事可傷，誰令利口说田常。","吳亡必定由端木，魯亦宜其運不长。"]', '诗', 'shi', '', NULL, '春秋戰國門 子貢 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6585e8ab-b1aa-46a7-9d32-ccb8ce1b572e', '春秋戰國門 再吟', '春秋戰国门 再吟', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["一言能使定安危，安己危人是所宜。","仁義不思垂教化，背恩亡德豈儒爲。"]', '["一言能使定安危，安己危人是所宜。","仁義不思垂教化，背恩亡德豈儒爲。"]', '诗', 'shi', '', NULL, '春秋戰國門 再吟 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53c3cdf4-6fdd-4f53-9db7-a02d71629b78', '春秋戰國門 鄭相', '春秋戰国门 鄭相', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["鄭相清賢慎有餘，好魚魚至竟何如。","退魚留得終身祿，祿在何憂不得魚。"]', '["鄭相清賢慎有餘，好鱼鱼至竟何如。","退鱼留得終身祿，祿在何憂不得鱼。"]', '诗', 'shi', '', NULL, '春秋戰國門 鄭相 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a504538-462d-42a4-a1fd-8465841458fe', '春秋戰國門 子產', '春秋戰国门 子產', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["爲政何門是化源，寬仁高下保安全。","如嫌水德人多狎，拯溺宜將猛濟寬。"]', '["爲政何门是化源，寬仁高下保安全。","如嫌水德人多狎，拯溺宜將猛濟寬。"]', '诗', 'shi', '', NULL, '春秋戰國門 子產 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbacad07-59a8-4ac8-9f02-3fb689acb3a3', '春秋戰國門 管仲', '春秋戰国门 管仲', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["美酒濃馨客要沽，門深誰敢強提壺。","苟非賢主詢賢士，肯信沽人畏子獹。"]', '["美酒濃馨客要沽，门深誰敢強提壺。","苟非賢主詢賢士，肯信沽人畏子獹。"]', '诗', 'shi', '', NULL, '春秋戰國門 管仲 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85ffdaaf-0a77-480f-a449-8fb2e028a927', '春秋戰國門 再吟', '春秋戰国门 再吟', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["社鼠穿牆巧庇身，何由攻灌若爲燻。","能知窟穴依形勢，不聽讒邪是聖君。"]', '["社鼠穿牆巧庇身，何由攻灌若爲燻。","能知窟穴依形勢，不听讒邪是聖君。"]', '诗', 'shi', '', NULL, '春秋戰國門 再吟 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('411a8335-5893-4d95-aaed-740e399f6d0e', '春秋戰國門 范蠡', '春秋戰国门 范蠡', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["西子能令轉嫁吳，會稽知爾啄姑蘇。","跡高塵外功成處，一葉翩翩在五湖。"]', '["西子能令轉嫁吳，會稽知爾啄姑蘇。","跡高塵外功成处，一葉翩翩在五湖。"]', '诗', 'shi', '', NULL, '春秋戰國門 范蠡 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f30fd00-ca31-4b3e-a4c9-eccb1f0f61e2', '春秋戰國門 屈原', '春秋戰国门 屈原', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["滿朝皆醉不容醒，衆濁如何擬獨清。","江上流人真浪死，誰知浸潤悞深誠。"]', '["满朝皆醉不容醒，衆濁如何擬独清。","江上流人真浪死，誰知浸潤悞深誠。"]', '诗', 'shi', '', NULL, '春秋戰國門 屈原 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5e40872-b1fc-4a9d-a134-e005c242cd14', '春秋戰國門 黃歇', '春秋戰国门 黄歇', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["春申隨質若王圖，爲主輕生大丈夫。","女子異心安足聽，功成何更用陰謨。"]', '["春申隨質若王圖，爲主轻生大丈夫。","女子異心安足听，功成何更用陰謨。"]', '诗', 'shi', '', NULL, '春秋戰國門 黃歇 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b19d41a5-acf2-4cc1-9370-c71ba340b29f', '春秋戰國門 王后', '春秋戰国门 王后', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["連環要解解非難，忽碎瑤堦一旦間。","兩國相持兵不解，會應俱碎似連環。"]', '["連环要解解非难，忽碎瑤堦一旦间。","兩国相持兵不解，會應俱碎似連环。"]', '诗', 'shi', '', NULL, '春秋戰國門 王后 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb469bc6-c55e-4186-b190-22a13a93378f', '春秋戰國門 樊姬', '春秋戰国门 樊姬', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["側影頻移未退朝，喜逢賢相日從高。","當時不有樊姬問，令尹何由進叔敖。"]', '["側影頻移未退朝，喜逢賢相日從高。","當时不有樊姬问，令尹何由進叔敖。"]', '诗', 'shi', '', NULL, '春秋戰國門 樊姬 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc4c506e-541c-4bd5-9610-1a6c06b089f9', '春秋戰國門 齊桓公', '春秋戰国门 齊桓公', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["三往何勞萬乘君，五來方見一微臣。","微臣傲爵能輕主，霸主如何敢傲人。"]', '["三往何勞万乘君，五来方见一微臣。","微臣傲爵能轻主，霸主如何敢傲人。"]', '诗', 'shi', '', NULL, '春秋戰國門 齊桓公 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e34bf22-02ea-4840-8631-834075635f81', '春秋戰國門 中山君', '春秋戰国门 中山君', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["敵臨烹子一何庸，激怒來軍速自攻。","結怨豈思圍不解，愚謀多以殺爲雄。"]', '["敵臨烹子一何庸，激怒来軍速自攻。","結怨豈思圍不解，愚謀多以殺爲雄。"]', '诗', 'shi', '', NULL, '春秋戰國門 中山君 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6b3e799-5926-4564-a576-963a9b19d2db', '春秋戰國門 趙簡子', '春秋戰国门 趙簡子', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["簡子雄心蓄霸機，賢愚聊欲試諸兒。","假言藏寶非真寶，不是生知焉得知。"]', '["簡子雄心蓄霸機，賢愚聊欲試諸兒。","假言藏寶非真寶，不是生知焉得知。"]', '诗', 'shi', '', NULL, '春秋戰國門 趙簡子 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70140c53-4f33-4335-9f15-c3be5b58cc52', '春秋戰國門 再吟', '春秋戰国门 再吟', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["諤諤能昌唯唯亡，亦由匡正得賢良。","一從忠讜無周舍，吾過何人爲短長。"]', '["諤諤能昌唯唯亡，亦由匡正得賢良。","一從忠讜無周舍，吾過何人爲短长。"]', '诗', 'shi', '', NULL, '春秋戰國門 再吟 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b523f030-bfc3-4034-9dd2-578816935a36', '春秋戰國門 趙宣子', '春秋戰国门 趙宣子', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["門人曾不有提彌，連嗾呀呀孰敢支。","臨難若教無苟免，亂朝爭那以獒爲。"]', '["门人曾不有提彌，連嗾呀呀孰敢支。","臨难若教無苟免，亂朝爭那以獒爲。"]', '诗', 'shi', '', NULL, '春秋戰國門 趙宣子 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dead840d-e028-433b-b0e9-29e28032ac14', '春秋戰國門 韓昭侯', '春秋戰国门 韓昭侯', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["去年秦伐我宜陽，今歲天災旱且荒。","對此不思人力困，樓門何可更高張。"]', '["去年秦伐我宜陽，今歲天災旱且荒。","对此不思人力困，楼门何可更高張。"]', '诗', 'shi', '', NULL, '春秋戰國門 韓昭侯 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('043d5cdd-883d-4cbb-94a5-92746b893f7c', '春秋戰國門 魏文侯', '春秋戰国门 魏文侯', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["冒雨如何固出畋，慮乖羣約失乾乾。","文侯不是貪禽者，示信將爲教化先。"]', '["冒雨如何固出畋，慮乖羣約失乾乾。","文侯不是貪禽者，示信將爲教化先。"]', '诗', 'shi', '', NULL, '春秋戰國門 魏文侯 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e063be80-e19f-42fb-abab-0a8c082a1ff3', '春秋戰國門 郄成子', '春秋戰国门 郄成子', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["陳樂無懽璧在隅，宰臣懷智有微謨。","苟非成子當明哲，誰是仁人可託孤。"]', '["陳乐無懽璧在隅，宰臣懷智有微謨。","苟非成子當明哲，誰是仁人可託孤。"]', '诗', 'shi', '', NULL, '春秋戰國門 郄成子 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f7bc94f-538a-43ad-aaca-22aac3e769be', '春秋戰國門 秦武陽', '春秋戰国门 秦武陽', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["丱歲徒聞有壯名，及令爲副誤荆卿。","是時環柱能相副，誰謂燕囚事不成。"]', '["丱歲徒闻有壯名，及令爲副誤荆卿。","是时环柱能相副，誰謂燕囚事不成。"]', '诗', 'shi', '', NULL, '春秋戰國門 秦武陽 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('192651a3-d617-4a46-abe8-1700803a547e', '春秋戰國門 田子方', '春秋戰国门 田子方', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["太子無嫌禮樂虧，願聽貧富與安危。","賤貧驕物貧終在，富貴驕人貴必隳。"]', '["太子無嫌禮乐虧，願听貧富與安危。","賤貧驕物貧終在，富貴驕人貴必隳。"]', '诗', 'shi', '', NULL, '春秋戰國門 田子方 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('726fe16d-5f19-4d3e-97d5-7c83f0715413', '春秋戰國門 淳于髠', '春秋戰国门 淳于髠', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["穰穰何禱手何賷，一呷村漿與隻雞。","以少求多誠可笑，還如輕幣欲全齊。"]', '["穰穰何禱手何賷，一呷村漿與隻雞。","以少求多誠可笑，還如轻幣欲全齊。"]', '诗', 'shi', '', NULL, '春秋戰國門 淳于髠 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74b0fec8-ca73-46d9-92dd-9c91fef9cf5e', '春秋戰國門 再吟', '春秋戰国门 再吟', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["戲問將何對所耽，滑稽無骨是常譚。","昔時王者皆通四，近見君王祗好三。"]', '["戲问將何对所耽，滑稽無骨是常譚。","昔时王者皆通四，近见君王祗好三。"]', '诗', 'shi', '', NULL, '春秋戰國門 再吟 周曇 shi');
